(window.GIM_TS=window.GIM_TS||{})["Niddah.4"]={"from":96,"a":[["\u0003ר' מאיר היא\u0004 שיטת משנתנו, הפוסלת את הסומא באחת מעיניו לדון, אף שהוא כשר להעיד. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 כך \u0003היה ר'\u0004 \u0003מאיר אומר: מה תלמוד לומר\u0004 (מלמדנו) הכתוב בדינם של הכהנים \"כי בם בחר ה' אלהיך לשרתו ולברך בשם ה' ו\u0003על פיהם יהיה כל ריב וכל נגע\"\u0004 (דברים כא, ה). שכן יש לשאול בכתוב זה: \u0003וכי מה ענין ריבים\u0004 (סכסוכים משפטיים שבין אדם לחבירו) \u0003אצל נגעים?\u0004 אלא \u0003מקיש\u0004 (משווה) הכתוב דינם של \u0003ריבים ל\u0004דינם של \u0003נגעים,\u0004 לומר: \u0003מה\u0004 דינם של \u0003נגעים\u0004 נקבע דווקא \u0003ביום, דכתיב\u0004 \u0005[ש\u0006כן \u0005כתוב]\u0006 בדין נגע צרעת האדם: \u0003\"וביום הראות בו\u0004 בשר חי יטמא\" (ויקרא יג, יד), \u0003אף\u0004 דינם של \u0003ריבים\u0004 אינו אלא \u0003ביום.\u0004","\u0003ו\u0004מן הצד האחר יש לומר: \u0003מה\u0004 דינם של \u0003נגעים\u0004 נוהג \u0003שלא ב\u0004כהן שהוא \u0003סומא,\u0004 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005כתוב]\u0006 בדינו של הכהן הרואה את הנגעים: \u0003\"לכל מראה עיני הכהן\"\u0004 (שם יב), ומכאן שאין הכהן כשר לדון בנגעים אלא אם כן רואה הוא בראייה שלימה של שתי עינים, \u0003אף\u0004 דינם של \u0003ריבים\u0004 הריהו \u0003שלא בסומא\u0004 ואפילו בעין אחת. \u0003ו\u0004עוד \u0003מקיש\u0004 דינם של ה\u0003נגעים ל\u0004דינם של ה\u0003ריבים, מה ריבים\u0004 נידונים דווקא \u0003שלא ב\u0004דיינים ה\u0003קרובים\u0004 קירבת משפחה לבעלי הדין, \u0003אף\u0004 דינם של \u0003נגעים\u0004 נוהג דווקא \u0003שלא ב\u0004כהנים \u0003קרובים.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כך שמשווים אנו בכל את דין נגעים וריבים זה לזה, שמא אף נאמר כך: \u0003מה\u0004 דינם של \u0003ריבים\u0004 נוהג דווקא \u0003בשלשה\u0004 דיינים, \u0003אף\u0004 דינם של \u0003נגעים\u0004 יהא דווקא \u0003בשלשה\u0004 כהנים? \u0003ודין\u0004 (קל וחומר) \u0003הוא:\u0004 אם דין \u0003ממונו\u0004 של אדם, שהוא קל, הריהו \u0003בשלשה\u0004 דיינים, דין \u0003גופו\u0004 של אדם, שהוא חמור, \u0003לא כל שכן\u0004 שיהיה בשלושה כהנים! לכך \u0003תלמוד לומר\u0004 הכתוב בענין הנגעים \u0003\"והובא אל אהרן הכהן או אל אחד מבניו הכהנים\"\u0004 (שם ב), \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 מכאן, \u0003שאפילו כהן אחד רואה את הנגעים.\u0004","ובענין הסומא באחת מעיניו לדון, מסופר: \u0003ההוא סמיא דהוה בשבבותיה\u0004 \u0005[סומא אחד\u0006 באחת מעיניו \u0005שהיה\u0006 גר \u0005בשכונתו]\u0006 של \u0003ר' יוחנן, דהוה קדיין דינא\u0004 \u0005[שהיה דן דינים],\u0006 \u0003ולא קאמר ליה ולא מידי\u0004 \u0005[ולא היה\u0006 ר' יוחנן \u0005אומר לו ולא דבר].\u0006 ושואלים: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה\u0006 ר' יוחנן \u0005כך]\u0006 שלא מחה באותו סומא? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 ככלל: \u0003הלכה כסתם משנה\u0004 (שאין הדברים השנוים בה, נשנים בשמו של תנא מסויים),","\u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005]:\u0006 \u0003כל הכשר לדון\u0004 — \u0003כשר להעיד, ויש כשר להעיד ואין כשר לדון, ואמרינן\u0004 \u0005[ואמרנו]:\u0006 הדין שיש הכשר להעיד אך אינו כשר לדון \u0003לאתויי מאי\u0004 \u0005[לרבות\u0006 את \u0005מה]?\u0006 \u0003ו\u0004על כך \u0003אמר ר'\u0004 \u0003יוחנן: לאתויי\u0004 \u0005[לרבות]\u0006 \u0003סומא באחת מעיניו\u0004 שאף שהוא כשר להעיד אינו כשר לדון. הרי שלשיטת ר' יוחנן הלכה היא שהסומא באחת מעיניו פסול מלדון, ומדוע לא מחה באותו סומא שהיה שכנו ודן?","ומשיבים: \u0003ר' יוחנן סתמא אחרינא אשכח\u0004 \u0005[\u0006משנה \u0005סתומה,\u0006 ללא שם התנא, \u0005אחרת מצא],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה במסכת סנהדרין\u0005]:\u0006 \u0003דיני ממונות דנין\u0004 (חובה להתחיל לדונם) \u0003ביום ו\u0004אולם אפשר גם שיהיו \u0003גומרין\u0004 אותם \u0003בלילה.\u0004 ואילו בנגעים אין דנים כלל בלילה, הרי שלשיטת סתם משנה זו, אין משווים דינם של ריבים (דיני ממונות) לדינם של נגעים. ומכאן גם שאין לפסול את הסומא באחת מעיניו מלדון בדיני ממונות (שהרי כל מקור דין זה הריהו מן ההשוואה לנגעים).","ושואלים: \u0003ומאי אולמיה דהאי סתמא מהאי סתמא\u0004 \u0005[ומה חוזקו של סתם\u0006 משנה \u0005זו,\u0006 שבמסכת סנהדרין, \u0005מסתם\u0006 משנה \u0005זו,\u0006 שלנו\u0005],\u0006 שפסק ר' יוחנן כמותה, ולכן לא מחה באותו סומא באחת מעיניו? ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 בהסבר הדבר, כי \u0003סתמא\u0004 \u0005[\u0006משנה \u0005סתומה]\u0006 של \u0003רבים,\u0004 כמשנה זו שבמסכת סנהדרין \u0003עדיף\u0004 על פני סתם משנה כמשנתנו, שהועמדה (למעלה) כשיטת ר' מאיר שהוא תנא יחיד. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003משום דקתני לה גבי הלכתא דדיני\u0004 \u0005[ששנה אותה\u0006 עורך המשנה \u0005אצל הלכות דיינים],\u0006 ולכן עדיף לפסוק על פיה בענין הכשרים לדון, מאשר על פי משנתנו.","\u0003כל\u0004 דבר \u0003שחייב ב\u0004הפרשת \u0003מעשרות\u0004 ממנו — הריהו גם \u0003מטמא\u0004 (ראוי להיטמא) ב\u0003טומאת אוכלין.\u0004 \u0003ו\u0004אולם \u0003יש\u0004 דבר \u0003שמטמא\u0004 ב\u0003טומאת אוכלין ואינו חייב במעשרות.\u0004","שנינו בסוף משנתנו שיש דבר שראוי לקבל טומאת אוכלין ואולם אינו חייב במעשרות. ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות את \u0005מה]\u0006 באה משנתנו? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 דברי מאכל אלו, \u0003בשר ודגים וביצים,\u0004 שראויים הם לקבל טומאת אוכלים, ואולם אין הם חייבים בהפרשת מעשרות.","\u0003כל\u0004 יבול \u0003שחייב ב\u0004השארת \u0003פאה\u0004 ממנו בשדה לעניים — \u0003חייב\u0004 אף \u0003ב\u0004הפרשת \u0003מעשרות.\u0004 \u0003ו\u0004אולם \u0003יש שחייב במעשרות, ואינו חייב בפאה.\u0004","שנינו במשנתנו כי יש יבול שחייב בהפרשת מעשרות ולא בפאה. ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות \u0005מה]\u0006 באה משנתנו? ומשיבים: \u0003לאתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 פרי ה\u0003תאנה, וירק שאינו חייב בפאה,\u0004 אף שחייבים בהפרשת מעשרות. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003כלל אמרו\u0004 בהגדרת החייב \u0003בפאה: כל שהוא אוכל\u0004 (דבר הנאכל), \u0003ונשמר, וגידולו מן הארץ, ו\u0004זמן \u0003לקיטתו כאחד\u0004 (בתקופה אחת מוגדרת בשנה), \u0003ומכניסו\u0004 למחסן \u0003לקיום\u0004 ממושך — הרי זה \u0003חייב בפאה.\u0004","ומסבירים מה בא כל אחד מהתנאים הללו למעט: \u0003אוכל\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003ספיחי סטים וקוצה\u0004 (צמחי צבע, שאינם ראויים לאכילה). \u0003ונשמר\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003הפקר,\u0004 שאין לו בעלים המשמרו מפני אחרים. \u0003וגידולו מן הארץ\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003כמהים ופטריות\u0004 שמקור גידולם לא מן הארץ. \u0003ולקיטתו כאחד\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003תאנה\u0004 שאין לה עונת לקיטה אחת, אלא מתמשכת לאורך זמן. \u0003ומכניסו לקיום\u0004 — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003ירק\u0004 שאינו מתקיים לאורך זמן, ואין מאחסנים אותו לזמן.","\u0003ואילו גבי\u0004 \u0005[אצל]\u0006 הגדרת הדברים החייבים ב\u0003מעשר תנן\u0004 \u0005[שנינו]:\u0006 \u0003כל שהוא אוכל, ונשמר, וגידולו מן הארץ\u0004 — \u0003חייב במעשרות, ואילו\u0004 התנאים הנוספים, שתהא \u0003לקיטתו כאחד, ומכניסו לקיום\u0004 — \u0003לא קתני\u0004 \u0005[אינו שונה].\u0006 הרי איפוא שתאנה וירק, חייבים במעשר ופטורים מהפאה, והם שהתמעטו בדברי משנתנו.","ומציינים: \u0003אם היו בהם,\u0004 בירקות הפטורים מן הפאה, \u0003שומים ובצלין\u0004 שהדרך להכניסם לקיום לאורך זמן, \u0003חייבין\u0004 הם אף בפאה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003מלבנות\u0004 (ערוגות) \u0003בצלים שבין הירק, ר'\u0004 \u0003יוסי אומר:\u0004 יש לתת \u0003פאה מכל אחת ואחת, וחכמים אומרים: מאחת על הכל.\u0004","\u0003אמר רבה בר בר חנה אמר ר'\u0004 \u0003יוחנן:\u0004 צמחי \u0003עולשין שזרען מתחילה\u0004 \u0003ל\u0004צורך מאכל \u0003בהמה, ו\u0004אחר \u0003נמלך עליהן\u0004 שישמשו \u0003ל\u0004מאכל \u0003אדם\u0004"],["כדי שיהיו ראויים לקבל טומאת אוכלין \u0003צריכות\u0004 שיחשוב עליהם \u0003מחשבה\u0004 נוספת לאכילת אדם, \u0003לכשיתלשו.\u0004 ומסבירים את דברי ר' יוחנן, \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 כי \u0003מחשבת חבור\u0004 (מחשבה זו שחשב בשעה שהצמחים היו עדיין מחוברים לקרקע) \u0003לא שמה מחשבה.\u0004","\u0003אמר רבא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 כשיטה זו: \u0003שלשה עשר דברים נאמרו ב\u0004דין טומאת \u0003נבלת עוף טהור.\u0004 \u0003וזה אחד מהן\u0004 — שעל מנת שתיטמא ותטמא מאכלים במגעה, הריהי \u0003צריכה מחשבה\u0004 שתיאכל, \u0003ואינה צריכה הכשר\u0004 (באחד משבעת המשקים) לקבלת טומאה, ואף מקבלת טומאה בלא שיגע בה שרץ, אלא נבלת עוף טהור נטמאת מאליה. ואף שחשב על עוף זה לאוכלו בעודו בחיים, הריהו צריך לחשוב עליו שוב לאכילה (על מנת שיקבל טומאה) לאחר שהתנבל, \u0003אלמא\u0004 \u0005[מכאן נסיק]\u0006 כי \u0003מחשבת חיים לא שמה מחשבה, הכא נמי\u0004 \u0005[כך גם כן]\u0006 \u0003מחשבת חבור לא שמה מחשבה.\u0004","\u0003ר' זירא אמר:\u0004 אין להביא מכאן ראיה לשיטת ר' יוחנן, כי \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003בגוזל\u0004 עוף \u0003שנפל מן הרום\u0004 (מגובה), ממקום שלא ראינוהו מקודם, \u0003עסקינן\u0004 \u0005[עוסקים אנו],\u0006 ש\u0003לא הוה\u0004 \u0005[לא היה]\u0006 עוף זה לפני שהתנבל \u0003קמן, דלחשוב עליה\u0004 \u0005[לפנינו, שנחשוב עליו].\u0006 לאכילה, ולכן נצרך לחשוב עליו לאכילה משהתנבל, אבל אילו אכן היה חושב עליו בחיים — מחשבה זו היתה מועילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לר' זירא: \u0003תרנגולת שביבנה\u0004 (עליה ידובר להלן), שטימאוה חכמים בהסתמך על מחשבה משהתנבלה, והיתה לפניהם בהיותה בחיים, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי שמחשבת חיים אינה נחשבת מחשבה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' זירא לאביי בתשובה: \u0003תרנגול ברא הוה\u0004 \u0005[בר היה]\u0006 זה, שלא היה לפנינו בהיותו בחיים, ולכן לא חשבו עליו לאכילה בחיים.","\u0003אחיכו עליה\u0004 \u0005[גיחכו עליו,\u0006 על הסבר זה של ר' זירא\u0005]:\u0006 והרי \u0003תרנגול ברא\u0004 \u0005[בר]\u0006 \u0003עוף טמא הוא, ועוף טמא מי קמטמא\u0004 \u0005[האם מטמא]?\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003אביי: גברא רבה\u0004 \u0005[אדם גדול]\u0006 כר' זירא \u0003אמר מילתא\u0004 \u0005[דבר],\u0006 \u0003לא תחיכו עליה\u0004 \u0005[אל תגחכו עליו],\u0006 שכן כוונתו היתה שמדובר \u0003בתרנגולת שמרדה\u0004 (שברחה) מבעליה אל המדבר, ובו גדלה את אפרוחיה. והרי אלו כשרים לאכילה, וחזר אחד מהם אל מקומו, ובאופן שלא היה לפנינו בחיים, ולכן לא חשבו עליו לאכילה בהיותו בחיים, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 הלשון שאמר ר' זירא \u0003\"ברא\"\u0004 — \u0003דאיבראי\u0004 \u0005[שנברא]\u0006 \u0003ממרה\u0004 (ממורדת).","\u0003רב פפא אמר\u0004 הסבר אחר: \u0003תרנגולתא דאגמא הואי\u0004 \u0005[תרנגולת של אגם,\u0006 מקום צמחיה שומם מבני אדם, \u0005היתה]\u0006 זו, ומשום כך לא חשבו עליה לאכילה בחיים, ונצרכת מחשבת אכילה משנתנבלה. ומסבירים: \u0003רב פפא\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אמר רב פפא: תרנגול\u0004 זכר \u0003דאגמא\u0004 \u0005[של אגם]\u0006 — \u0003אסור,\u0004 שהריהו עוף טמא. ואולם \u0003תרנגולתא דאגמא\u0004 \u0005[תרנגולת של אגם]\u0006 — \u0003שריא\u0004 \u0005[מותרת],\u0006 שהיא עוף כשר.","\u0003וסימניך\u0004 לזכור מי המותר ומי האסור — ההלכה הנודעת בעניינם של האסורים לבוא בקהל: \u0003עמוני ולא עמונית,\u0004 ואף בענייננו, הזכר אסור, ולא תרנגולת (נקבה) של אגם המותרת. \u0003דרש מרימר: תרנגולתא דאגמא\u0004 \u0005[תרנגולת של אגם]\u0006 — \u0003אסירא\u0004 \u0005[אסורה]\u0006 ושלא כשיטת רב פפא. וסיבת הדבר, שכן \u0003חזיוה רבנן דדרסה ואכלה\u0004 \u0005[ראוה חכמים\u0006 את התרנגולת הזו שהיא \u0005דורסת ואוכלת].\u0006 \u0003והיינו\u0004 \u0005[וזהו]\u0006 העוף הנקרא \u0003גירותא\u0004 שהוא טמא.","ועוד בעניינו של גוזל עוף טהור שנפל ומת, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גוזל\u0004 עוף טהור \u0003שנפל ל\u0004תוך \u0003גת\u0004 (מקום חצוב בסלע לדריכת ענבים ליין), ומת שם, \u0003וחשב\u0004 בעליו \u0003עליו להעלותו\u0004 מהגת. אם חשב להעלותו \u0003ל\u0004שם אכילתו של \u0003כותי\u0004 — הגוזל \u0003טמא,\u0004 כדין כל נבלת עוף טהור. ואם חשב להעלות את הגוזל משם כדי \u0003ל\u0004האכיל בו \u0003כלב\u0004 — הריהו \u0003טהור.\u0004 \u0003ר'\u0004 \u0003יוחנן בן נורי אומר: אף\u0004 אם חשב להעלותו \u0003ל\u0004אכילת \u0003כלב\u0004 — הריהו \u0003טמא,\u0004 שכן הגוזל כשלעצמו ראוי לאכילת אדם, ואין צורך איפוא במחשבה לאכילת אדם דווקא כדי שיטמא.","ובנימוק שיטתו זו \u0003אמר ר'\u0004 \u0003יוחנן בן נורי: קל וחומר\u0004 הוא, \u0003אם\u0004 נבלת עוף טהור הריהי \u0003מטמא טומאה חמורה\u0004 (טומאת בגדים, באכילת כזית ממנה, בהיותו בבית הבליעה) אף \u0003שלא במחשבה\u0004 (שלא ידע בשעת אכילה, שזוהי נבלת עוף טהור), \u0003לא יטמא טומאה קלה\u0004 (טומאת אוכלים, שאינה מטמאה אלא במגע) \u0003שלא במחשבה?!\u0004","\u0003אמרו לו\u0004 חכמים: \u0003לא,\u0004 אין זה קל וחומר, שכן \u0003אם אמרת\u0004 שאין צורך במחשבה \u0003בטומאה חמורה\u0004 (טומאת בגדים, באכילה), הרי זה משום \u0003שכן אינה יורדת לכך\u0004 (לדין מחשבה), \u0003תאמר\u0004 שאין צורך במחשבה \u0003בטומאה קלה\u0004 (טומאת אוכלים) \u0003שכן יורדת לכך!\u0004","\u0003אמר להן: תרנגולת שביבנה תוכיח,\u0004 שכך היה מעשה ביבנה, שמתה תרנגולת, ובא דינה לפני חכמים, \u0003שיורדת לכך\u0004 — \u0003וטמאוה שלא במחשבה.\u0004 \u0003אמרו לו: משם ראיה? כותים היו שם, וחשבו עליה לאכילה.\u0004","ושואלים: \u0003במאי עסקינן\u0004 \u0005[במה,\u0006 באיזה מקרה \u0005אנו עוסקים]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שמדובר \u0003בכרכים\u0004 שהם מקומות שיש בהם עם רב, ורבים הם האוכלים, ונאכל בהם הכל, ואף נבלת עוף טהור וחלב בהמה — \u0003למה לה מחשבה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נבלת בהמה טהורה, בכל מקום\u0004 (בין במקומות מעוטי אנשים ובין במקומות מרובי אנשים), \u0003ונבלת עוף טהור והחלב, בכרכים\u0004 — \u0003אין צריכין לא מחשבה\u0004 לאכילת אדם \u0003ולא הכשר\u0004 משקה ולא הכשר טומאה!","\u0003אלא\u0004 המדובר \u0003בכפרים\u0004 שמעטים האוכלים דבר זה, ואולם גם על צד יש לשאול: \u0003ומי איכא למאן דאמר\u0004 \u0005[והאם יש מי שאומר]\u0006 ש\u0003לא בעיא\u0004 \u0005[לא צריכה]\u0006 נבלת עוף טהור \u0003מחשבה? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003נבלת בהמה טמאה בכל מקום, ונבלת עוף טהור בכפרים\u0004 — \u0003צריכה מחשבה, ואינה צריכה הכשר!\u0004","\u0003אמר ר'\u0004 \u0003זעירא בר חנינא: לעולם\u0004 מדובר \u0003בכרך, ו\u0004אשר לשאלה שבכרכים אין צריך נבלת עוף טהור מחשבה, שונה המקרה כאן, שנפל הגוזל לתוך הגת, שכן \u0003גתו מאסתו\u0004 (לכלכה אותו), \u0003ועשאתו ככפר\u0004 שמעטים האוכלים דבר זה.","ומבררים את מה ששנינו למעלה. \u0003אמר ר'\u0004 \u0003יוחנן בן נורי: קל וחומר, אם מטמאה טומאה חמורה שלא במחשבה לא תטמא טומאה קלה שלא במחשבה?\u0004","\u0003אמרו לו: לא, אם אמרת בטומאה חמורה שכן אינה יורדת לכך.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינה יורדת לכך\"? אמר רבא, הכי קאמרי ליה\u0004 \u0005[כך אמרו לו\u0006 חכמים לר' יוחנן בן נורי\u0005]:\u0006 \u0003לא, אם אמרת\u0004"],["\u0003בטומאה חמורה\u0004 (שבנבלת עוף טהור בבית הבליעה, המטמאת בגדים) — \u0003שכן\u0004 היא \u0003אינה עושה\u0004 (מחילה דין) על הדבר הנטמא על ידה שיהיה מעתה דינו \u0003כיוצא בה\u0004 (כמוה), שהרי האדם הנטמא בנבלה, אינו חוזר ומטמא אדם אחר, כדרך שמטמאת הנבלה. \u0003תאמר בטומאה קלה\u0004 (טומאת אוכלין) — \u0003ש\u0004היא \u0003עושה\u0004 את האוכל הנטמא על ידה שיהא דינו מעתה \u0003כיוצא בה.\u0004 שכן דינו של אוכל זה שנטמא, שהוא חוזר ומטמא אוכל אחר (מדרבנן).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרבא: והרי \u0003כל\u0004 ש\u0003כן הוא,\u0004 ובאופן זה: \u0003ומה טומאה חמורה\u0004 (טומאת נבלת העוף) שאף \u0003דקילא\u0004 \u0005[שקלה]\u0006 היא, שהרי \u0003אינה עושה\u0004 את הנטמא על ידה שיהיה \u0003כיוצא בה\u0004 — \u0003מטמאה שלא במחשבה\u0004 (אף אם לא היה האוכל את נבלת העוף יודע שבבית הבליעה ישנה נבלת עוף טהור). אם כן, \u0003טומאה קלה\u0004 כגון זו של טומאת אוכלין, \u0003דחמירא\u0004 \u0005[שחמורה],\u0006 שהרי היא \u0003עושה\u0004 את הנטמא על ידה שיהיה דינו \u0003כיוצא בה\u0004 — \u0003אינו דין שמטמאה שלא במחשבה?\u0004","\u0003אלא אמר רב ששת, הכי קאמר\u0004 \u0005[כך הוא,\u0006 חכמים שהשיבו לר' יוחנן בן נורי, \u0005אומר,\u0006 זו כוונתם\u0005]:\u0006 \u0003לא אם אמרת בטומאה חמורה\u0004 (נבלת העוף), שהרי היא חמורה \u0003שכן אינה צריכה הכשר\u0004 כדי להיטמא, \u0003תאמר בטומאה קלה\u0004 (טומאת אוכלין) \u0003ש\u0004הרי היא \u0003צריכה הכשר\u0004 כדי להיטמא.","ושואלים על כך: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003צריכה\u0004 נבלת עוף טהור \u0003הכשר\u0004 כדי לטמא טומאת אוכלין? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשה דברים נאמרו בנבלת עוף טהור: צריכה מחשבה\u0004 להיאכל, כדי שתיטמא טומאת אוכלין. \u0003ואינה מטמאה\u0004 את האוכל אותה טומאת בגדים \u0003אלא\u0004 בזמן שלפחות כשיעור זית מן הנבלה נמצא \u0003בבית הבליעה.\u0004 \u0003ואינה צריכה הכשר\u0004 כדי שתטמא!","ומשיבים: \u0003נהי\u0004 \u0005[אף שאמנם]\u0006 \u0003הכשר שרץ\u0004 המטמא אותה היא \u0003לא בעיא\u0004 \u0005[אינה צריכה],\u0006 שכן נטמאת היא מעצמה, ואינה נזקקת לכך. ואולם \u0003הכשר מים\u0004 או שאר משקים המכשירים לקבלת טומאה, היא \u0003בעיא\u0004 \u0005[צריכה].\u0006","ושואלים על כך: \u0003מאי שנא\u0004 \u0005[מה שונה,\u0006 מיוחד\u0005]\u0006 \u0003הכשר שרץ\u0004 ש\u0003לא בעיא\u0004 \u0005[לא צריך]\u0006 — הרי זה \u0003כדתנא דבי\u0004 \u0005[כפי ששנה\u0006 החכם \u0005של בית]\u0006 המדרש של \u0003ר' ישמעאל, הכשר מים נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תבעי\u0004 \u0005[לא תצטרך],\u0006 ומסבירים: \u0003כדתנא דבי\u0004 \u0005[כפי ששנה\u0006 החכם \u0005של בית]\u0006 המדרש של ר' ישמעאל.","\u0003דתנא דבי\u0004 \u0005[ש\u0006כך \u0005שנה\u0006 החכם \u0005של בית]\u0006 המדרש של \u0003ר' ישמעאל:\u0004 ממה נאמר בדין הכשר לקבלת טומאת אוכלין \"וכי יפול מנבלתם \u0003על כל זרע זרוע אשר יזרע\u0004 טהור הוא. וכי יותן מים על זרע ונפל מנבלתם עליו טמא הוא לכם\" (ויקרא יא, לז—לח), למדים שכל עוד לא הוכשר בנפילת מים עליו, אין הוא נטמא. ומקור הלכה זו של הכשר לקבלת טומאה, הריהו זרעים, ללמדנו שדין זה נוהג בדומה לזרעים.","ומכאן נלמד: \u0003מה זרעים,\u0004 \u0003שאין סופן לטמא טומאה חמורה\u0004, שהרי אין האוכל מטמא אדם בכל אופן — הריהם \u0003צריכין הכשר\u0004 לקבלת טומאה. \u0003אף כל שאין סופן לטמא טומאה חמורה\u0004 — \u0003צריכין הכשר.\u0004 \u0003יצתה\u0004 (יצאה) מכלל אלו, \u0003נבלת עוף טהור שסופה לטמא טומאה חמורה\u0004 שהרי היא מטמאת אדם בהיותה בבית הבליעה — \u0003שאין צריך הכשר\u0004 לקבלת טומאה.","\u0003אלא אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב פפא:\u0004 כך דחו חכמים את הקל וחומר של ר' יוחנן בן נורי, שאף שנבלת עוף טהור נראית כחמורה מטומאת נבלה, שכן אינה צריכה מחשבה, אבל סוף סוף \u0003שום\u0004 \u0005[שם,\u0006 מהות\u0005]\u0006 \u0003טומאה חמורה בעולם\u0004 היא טומאת הנבלה, בעוד ש\u0003שום\u0004 \u0005[שם,\u0006 מהות\u0005]\u0006 טומאת אוכלין, הריהי \u0003טומאה קלה בעולם.\u0004","ועוד בדינו של ר' יוחנן שמחשבת חיבור (מחשבה שחשב אדם על דבר בעודנו מחובר לקרקע) אינה נחשבת (לענין טומאת אוכלים), \u0003אמר רבא: ומודה ר'\u0004 \u0003יוחנן לענין\u0004 חיוב הפרי בהפרשת \u0003מעשר,\u0004 ש\u0003מחשבת חיבור\u0004 — \u0003שמה מחשבה.\u0004 \u0003אמר רבא\u0004 בהסבר שיטתו זו, \u0003מנא אמינא לה\u0004 \u0005[מנין אומר אני,\u0006 שיטתי זו בדעת ר' יוחנן\u0005]\u0006 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 לענין חיוב מעשר: \u0003הסיאה\u0004 (מין ממיני האזוב), \u0003והאזוב, והקורנית\u0004 (מין ממיני האזוב) \u0003ש\u0004גדלים \u0003בחצר\u0004 הבית, שאף ששלושת מיני האזוב הללו אינם מיוחדים למאכל אדם, ואולם יש שאוכלים אותם, \u0003אם היו נשמרין\u0004 בידי בעלי אותה חצר — הריהם \u0003חייבין\u0004 במעשר.","ומעתה יש לברר, \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אילימא דזרעינהו\u0004 \u0005[אם תאמר\u0006 במקרה שזרע אותם] \u0003מתחלה ל\u0004שם אכילת \u0003אדם\u0004 — וכי \u0003צריכא למימר\u0004 \u0005[צריך\u0006 דבר זה \u0005להיאמר],\u0006 שהם חייבים במעשר אם הם נשמרים, והרי קיימים בו התנאים המחייבים דבר במעשר: שהוא אוכל, ושהוא נשמר! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר במקרה \u0003דזרעינהו\u0004 \u0005[שזרע אותם]\u0006 \u0003מתחלה ל\u0004אכילת \u0003בהמה, וקתני\u0004 \u0005[ושנינו]\u0006 במשנה זו ש\u0003אם היו נשמרין\u0004 על ידי בעלי החצר, כלומר שהוא נמלך על מיני האזוב הללו, וחשב עליהם לאכילת אדם — הריהם \u0003חייבין\u0004 במעשר, והרי שמחשבת חיבור נחשבת לענין מעשר.","\u0003אמר רב אשי\u0004 בדחיית ראייתו זו של רבא: \u0003הכא\u0004 \u0005[כאן,\u0006 במשנה זו\u0005],\u0006 \u0003בחצר שעלו\u0004 (שצמחו) בה מיני האזוב הללו \u0003מאיליהן עסקינן\u0004 \u0005[עוסקים אנו],\u0006 \u0003וסתמא\u0004 \u0005[ובסתם]\u0006 — מיני האזוב הללו \u0003ל\u0004אכילת \u0003אדם\u0004 הם \u0003קיימי\u0004 \u0005[עומדים],\u0006 והרי מתקיים תנאי זה של אוכל, בחיוב המעשר מהם. \u0003ו\u0004אילו באשר לתנאי שיהא נשמר, \u0003הכי קאמר\u0004 \u0005[כך הוא\u0006 התנא במשנה \u0005אומר]:\u0006 \u0003אם החצר משמרת פירותיה\u0004 — \u0003חייבין\u0004 במעשר, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פטורין.\u0004","ועוד, \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אשי\u0004 על הסברו של רבא בשיטת ר' יוחנן, ממה ששנינו בדף הקודם, כי \u0003כל\u0004 הדברים \u0003שחייבין ב\u0004הפרשת \u0003מעשרות\u0004 מהם — הריהם \u0003מטמאין\u0004 (ראויים לקבל) \u0003טומאת אוכלין.\u0004 \u0003ו\u0004מעתה יש לשאול: \u0003אם איתא\u0004 \u0005[יש,\u0006 נכונים דבריך\u0005]\u0006 בשיטת ר' יוחנן, שאף שמחשבת חיבור אינה נחשבת לענין קבלת טומאת אוכלין, הריהי נחשבת לענין חיוב מעשרות, \u0003הא איכא הני\u0004 \u0005[הרי ישנם אלו]\u0006 עולשין שזרעם בתחילה לצורך אכילת בהמה, ונמלך עליהם בהיותם מחוברים לקרקע, לאכילת אדם — \u0003דקחייבין\u0004 \u0005[שהם חייבים]\u0006 \u0003במעשר, ואין\u0004 הם \u0003מטמאין טומאת אוכלין!\u0004","\u0003אמר רבא\u0004 בתשובה \u0003הכי קאמר\u0004 \u0005[כך הוא\u0006 התנא אומר, זו היא כוונתו\u0005]:\u0006 \u0003כל מין\u0004 צומח \u0003שחייב במעשר\u0004 — הריהו גם \u0003מטמא טומאת אוכלין.\u0004 ואולם אפשר שבתוך מין מסויים, יהיה מקרה מוגדר, שבו לא יתקיים כלל זה, ויהיה חייב במעשרות, ולא יקבל טומאת אוכלין, כגון הזורע עולשין לאכילת בהמה ונמלך עליהם לאכילת אדם.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 שהתנא מדבר על מין הצומח, ולא על מקרה מסויים, \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנינו\u0006 ב\u0005סוף\u0006 המשנה, בעמוד הבא\u0005]:\u0006 \u0003כל\u0004 בהמה \u0003שחייב\u0004 בעליה \u0003ב\u0004נתינת \u0003ראשית הגז\u0004 ממנה — \u0003חייב במתנות\u0004 כהונה, הזרוע הלחיים והקיבה אם נשחטה. \u0003ויש שחייב במתנות, ואין חייב בראשית הגז.\u0004","\u0003ו\u0004מעתה נאמר: \u0003אם איתא\u0004 \u0005[יש]\u0006 כסברה שהתנא מדבר על כל המקרים, אם כן יש לשאול, \u0003האיכא\u0004 \u0005[הרי יש]\u0006 מקרה של \u0003טרפה\u0004 — ש\u0003חייבת\u0004 היא \u0003בראשית הגז ואינה חייבת במתנות!\u0004 אלא מכאן יש להוכיח, כדברי רבא, שהתנא אינו מדבר על כל המקרים, אלא על המינים, וכגון כלל זה, שכל מין שחייב במעשר הריהו מקבל טומאת אוכלין.","\u0003אמר רבינא\u0004 בדחיית ראיה זו: אפשר שהתנא מדבר על כל המקרים, ואין להקשות מדין הטריפה, שחייבת בראשית הגז ואינה חייבת במתנות כהונה, כי \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' שמעון היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0005ר' שמעון פוטר את הטרפה מראשית הגז.\u0006","\u0003אמר רב שימי בר אשי, תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ראיה להסברו זה של רבא, שהתנא דבר רק על המינים, ולא על כל המקרים, ממה ששנינו בברייתא: \u0003המפקיר את כרמו, ו\u0004למחרת \u0003השכים בבקר,\u0004 לפני שזכה בו אחר, \u0003ובצרו\u0004 (קטף את פירותיו) — \u0003חייב ב\u0004נתינת מתנות עניים, ב\u0003פרט, ובעוללות, ובשכחה, ובפאה,\u0004 שכן ריבה אותם הכתוב, שאף שכתב כל אחד מאלה במקומו הוסיף וכתב \"לעני ולגר תעזוב אותם\" (ויקרא יט, י. ושם כג, כב), לרבות חיובם אף בכגון זה. \u0003ופטור מן המעשר,\u0004 כדין הפקר שפטור מן המעשר.","ואולם על כך יש להקשות: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנה בדף הקודם כי \u0003כל שחייב בפאה\u0004 — \u0003חייב במעשרות! אלא לאו שמע מינה\u0004 \u0005[האם לא תשמע,\u0006 תלמד, \u0005מכאן]\u0006 כי \u0003מין קתני\u0004 \u0005[שנה],\u0006 ואולם ייתכנו מקרים מסויימים, שבהם יהיה דבר חייב בפאה, ולא יהיה חייב במעשר. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[שמע,\u0006 למד \u0005מכאן]\u0006 כך, כהסברו של רבא.","ועוד בדין החייב בפאה ובמעשר, \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה במסכת פאה\u0005]\u0006 כי אף שנחלקו חכמים ור' עקיבא בענין שדה שנקצרה במספר מקומות נבדלים, והריהי מנומרת בקטעים קצורים ושאינם קצורים, האם צריך בעליה להפריש פאה מכל מקום קצור (כשיטת ר' עקיבא) או שנותן פאה מאחד על הכל (כשיטת חכמים). ואולם \u0003מודים חכמים לר'\u0004 \u0003עקיבא\u0004 שצריך להפריש פאה מכל אחד ואחד, \u0003בזורע\u0004 ירק ה\u0003שבת או\u0004 ירק ה\u0003חרדל,\u0004 שהם ירקות החייבים בפאה, מלכתחילה \u0003בשנים ושלשה מקומות\u0004 על פני השדה, \u0003שנותן פאה מכל אחד ואחד\u0004 לעצמו."],["ומעתה יש לומר: \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003שבת\u0004 הוא צמח \u0003דמיחייב\u0004 \u0005[שחייב]\u0006 \u0003בפאה,\u0004 כמבואר במשנה, \u0003ו\u0004מכאן ש\u0003מיחייב\u0004 \u0005[חייב]\u0006 אף \u0003במעשר, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה למעלה\u0005]\u0006 ש\u0003כל שחייב בפאה\u0004 — \u0003חייב במעשר.\u0004","\u0003ומ\u0004תוך שהוא \u0003חייב במעשר\u0004 — הריהו אף \u0003מטמא טומאת אוכלין,\u0004 וכמו ששנינו במשנה כי כל החייב במעשרות ראוי לקבל טומאת אוכלין. \u0003אלמא\u0004 \u0005[מכאן נסיק]\u0006 כי \u0003כל מילי דעביד לטעמא\u0004 \u0005[דבר שעשוי ל\u0006שם \u0005טעם]\u0006 כדוגמת השבת — \u0003מטמא טומאת אוכלין, דהאי\u0004 \u0005[ש\u0006הרי \u0005זה]\u0006 ה\u0003שבת לטעמא עבידא\u0004 \u0005[לטעם\u0006 הוא \u0005עשוי].\u0006","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 על מסקנה זו ממה ששנינו במשנה במסכת עוקצין בדין האוכלים שאינם מקבלים טומאת אוכלין: צמחי התבלין — \u0003הקושט, והחימום, וראשי בשמים, והתיאה, והחלתית, והפלפלים, וחלת חריע\u0004 — אף שהם באים רק לתבל את האוכל, נחשבים הם בכלל דברי מאכל, לענין זה שהם \u0003נקחין\u0004 (נקנים) \u0003בכסף מעשר\u0004 שני שנאמר שקונים בו רק דברי מאכל ושתיה. \u0003ו\u0004אולם אינם נחשבים לגמרי כמאכל, ולכן \u0003אין\u0004 הם \u0003מטמאין טומאת אוכלין,\u0004 אלו \u0003דברי ר'\u0004 \u0003עקיבא.\u0004","\u0003אמר לו ר' י\u0004 \u0003וחנן בן נורי: אם\u0004 נחשבים הם כמאכל לענין ש\u0003נקחין בכסף מעשר, מפני מה אין\u0004 הם נחשבים כמאכל לענין ש\u0003מטמאין טומאת אוכלין? ואם אינן מטמאין,\u0004 משום שאינם נחשבים כמאכל, אם כן \u0003אף הם לא ילקחו בכסף מעשר!\u0004","\u0003ואמר ר'\u0004 \u0003יוחנן בן נורי\u0004 בהלכה זו: \u0003נמנו\u0004 החכמים \u0003וגמרו שאין\u0004 צמחי התבלין הללו \u0003נקחין בכסף מעשר, ואין\u0004 הם \u0003מטמאין טומאת אוכלין.\u0004 ומעתה קשה על מה ששנינו למעלה כי השבת, שהוא צמח תבלין, מיטמא טומאת אוכלים!","\u0003אמר רב חסדא\u0004 בתירוץ סתירה זו: \u0003כי תניא ההיא\u0004 \u0005[כאשר שנויה אותה\u0006 ברייתא\u0005]\u0006 שהשבת נחשב כדבר מאכל, לענין שיקבל טומאת אוכלין — הרי זה \u0003בשבת העשויה\u0004 (שיוחדה) \u0003לכמך\u0004 (לכתישה ונתינה בכותח — רוטב שנועד לתיבול מאכלים שונים).","\u0003אמר רב אשי אמריתה לשמעתיה קמיה\u0004 \u0005[אמרתי את השמועה\u0006 הזו, תירוצו של רב חסדא, לפני] \u0003רב כהנא, (אמר): לא תימא\u0004 \u0005[אל תאמר\u0006 תדייק בדברים\u0005]\u0006 שמדובר דווקא \u0003בשבת העשויה\u0004 (המיועדת מלכתחילה) \u0003לכמך\u0004 — שמכאן תוכל להסיק: \u0003הא סתמא\u0004 \u0005[הרי בסתם]\u0006 השבת מיועדת \u0003לקדרה, אלא\u0004 ודאי \u0003סתם שבת לכמך\u0004 היא \u0003עשויה, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה בעוקצין\u0005]:\u0006 \u0003השבת\u0004 של תרומה ששמו אותו בתוך הקדירה המתבשלת כדי לתת טעם בתבשיל, ולאחר מכן הוציאוהו מן הקדירה, \u0003משנתנה טעם בקדרה\u0004 ויצא ממנו טעמו המיוחד — שוב \u0003אין בה\u0004 בשבת זה \u0003משום\u0004 איסור אכילת \u0003תרומה,\u0004 ואין הזר שאכלו חייב. \u0003ואינה מטמאה טומאת אוכלין.\u0004","ונדייק: \u0003הא\u0004 \u0005[הרי\u0006 מכאן יוצא\u0005]\u0006 ש\u0003עד שלא\u0004 (בטרם) \u0003נתנה\u0004 השבת \u0003טעם בקדרה\u0004 — \u0003יש בה משום תרומה, ומטמאה טומאת אוכלין.\u0004 \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003סתמא\u0004 \u0005[בסתם]\u0006 שבת מיועדת \u0003ל\u0004נתינה ב\u0003קדרה\u0004 — \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא נתנה\u0004 בקדירה \u0003נמי סתמא\u0004 \u0005[גם כן בסתם]\u0006 \u0003לקדרה\u0004 היא עומדת, ותיאסר אכילתה ותקבל טומאה אף לפני שניתנה לקדירה! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא נשמע מכאן]\u0006 כי \u0003סתמא\u0004 \u0005[בסתם]\u0006 השבת \u0003לכמך\u0004 היא \u0003עשויה.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי כך הוא.","\u0003כל שחייב בראשית הגז\u0004 שמצות התורה לתת לכהן מראשית גיזת הכבשים (רחלים ואילים) — \u0003חייב במתנות\u0004 כהונה, שהיא מצות התורה לתת לכהן מהבהמה הטהורה שנשחטה את הזרוע הלחיים והקיבה. \u0003ויש\u0004 מבעלי החיים \u0003שחייב\u0004 בהם \u0003במתנות\u0004 כהונה, כגון בקר ועיזים, \u0003ו\u0004אולם \u0003אינו חייב\u0004 בהם \u0003בראשית הגז.\u0004","וכלל דומה: \u0003כל\u0004 פרי שגדל בשנה השביעית (שנת השמיטה) \u0003שיש לו\u0004 (עליו) חובת \u0003ביעור\u0004 מן הבית, בזמן שכלה אותו מין לחיה שבשדה — \u0003יש לו\u0004 (עליו) דיני קדושת \u0003שביעית,\u0004 שאסור בסחורה וחייב להפקירו כשהוא עדיין מחובר לקרקע. \u0003ו\u0004אולם \u0003יש\u0004 מן הפירות \u0003שיש לו\u0004 דיני קדושת \u0003שביעית,\u0004 וכגון פרי שאינו כלה לחיה מן השדה, כיון שהוא פרי המתקיים בארץ, \u0003ו\u0004משום כך \u0003אין לו\u0004 חובת \u0003ביעור.\u0004","שנינו במשנתנו שכל פרי שיש עליו חובת ביעור, יש עליו כל דיני שביעית, ואולם יש פרי שיש עליו דיני שביעית ואין עליו חובת ביעור. ומביאים מקרה של צמח מסויים, שמתקיימים בו (בחלקיו השונים) שתי ההלכות הללו: \u0003כגון\u0004 צמח הלוף (צמח בעל פקעת ועלים גדולים). שההלכה הראשונה, שכל פרי שיש בו חובת ביעור, יש בו דיני שביעית — הריהי נוהגת ב\u0003עלה הלוף שוטה, והדנדנה,\u0004 שהם כלים מן השדה בימות הגשמים. ואילו ההלכה השניה, ש\u0003יש\u0004 פרי \u0003שיש לו שביעית ואין לו ביעור\u0004 — מתקיימת ב\u0003עיקר\u0004 (בשורש) \u0003הלוף שוטה, ועיקר הדנדנה.\u0004","והסבר דין חובת הביעור, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בדין השביעית \u0003\"ולבהמתך ולחיה אשר בארצך תהיה כל תבואתה לאכל\"\u0004 (ויקרא כה, ז), והרי זה בא ללמדנו: \u0003כל זמן שחיה אוכלת מן השדה,\u0004 שלא כלה אותו מין מהשדה — \u0003אתה מאכיל לבהמתך בבית, כלה לחיה מן השדה\u0004 — \u0003כלה לבהמתך שבבית,\u0004 והרי זו מצות הביעור. \u0003ו\u0004אילו \u0003הני\u0004 \u0005[אלו,\u0006 עיקרי הלוף והדנדנה\u0005]\u0006 \u0003לא כלו להו\u0004 \u0005[להם]\u0006 מן השדה, ולכן אין עליהם חובת ביעור.","נאמר בתורה בדיני הדג הכשר לאכילה \"את זה תאכלו מכל אשר במים כל אשר לו סנפיר וקשקשת\" (ויקרא יא, ט). וכלל הוא בסימני הדגים, \u0003כל\u0004 דג \u0003שיש לו קשקשת\u0004 — בידוע ש\u0003יש לו\u0004 גם \u0003סנפיר, ו\u0004אולם \u0003יש\u0004 דג \u0003שיש לו סנפיר ואין לו קשקשת.\u0004 וכן נאמר בדין בעלי החיים הכשרים לאכילה \"כל מפרסת פרסה ושוסעת שסע פרסות מעלת גרה בבהמה אותה תאכלו\" (שם ג). וכלל הוא בסימן הבהמה המפרסת פרסה (שפרסותיה סדוקות, טלפים) ש\u0003כל\u0004 בעל חיים \u0003שיש לו קרנים\u0004 — \u0003יש לו טלפים, ו\u0004אולם \u0003יש\u0004 בעל חיים \u0003שיש לו טלפים ואין לו קרנים.\u0004","שנינו במשנתנו בדין סימני הדגים הכשרים לאכילה כי \u0003כל\u0004 דג \u0003שיש לו קשקשת\u0004 — בידוע שיש לו גם סנפיר, והרי הוא איפוא \u0003דג טהור\u0004 (כשר לאכילה). ו\u0003יש\u0004 דג \u0003שיש לו סנפיר, ו\u0004אולם \u0003אין לו קשקשת\u0004 — והרי הוא \u0003דג טמא\u0004 (אסור באכילה). ושואלים: \u0003מכדי\u0004 \u0005[כיון]\u0006 ש\u0003אנן\u0004 \u0005[אנחנו]\u0006 על סימן ה\u0003קשקשת\u0004 בלבד \u0003סמכינן\u0004 \u0005[סומכים אנו],\u0006 שהרי אם יש בו קשקשת, בודאי יש בו גם סנפיר, ואם כן \u0003סנפיר דכתיב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 כתנאי נוסף לכשרות הדג, \u0003למה לי?\u0004","ומשיבים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא כתב רחמנא\u0004 \u0005[לא היתה כותבת התורה]\u0006 גם את סימן ה\u0003סנפיר, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003קשקשת\u0004 זו \u0003דכתיב\u0004 \u0005[שנאמרה]\u0006 בתורה — הכוונה ל\u0003סנפיר, ואפילו דג טמא,\u0004 זה שאין לו קשקשת, אלא רק סנפיר בלבד, כשר לאכילה — לכן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 את שני הסימנים, \u0003סנפיר וקשקשת.\u0004","ושואלים עוד: \u0003והשתא דכתיב רחמנא\u0004 \u0005[ועכשיו שאמרה התורה]\u0006 \u0003סנפיר וקשקשת מנלן\u0004 \u0005[מנין לנו]\u0006 ש\u0003קשקשת לבושא\u0004 \u0005[לבוש]\u0006 \u0003הוא?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 על גלית הפלישתי \u0003\"ושריון קשקשים הוא לבוש\"\u0004 (שמואל א יז, ה).","ושואלים שוב: \u0003ו\u0004מעתה שלמדים אנו מכתוב זה שהקשקשת הריהי לבושו של הדג, ולא נטעה איפוא בה שמשמעה סנפיר, ולכתוב \u0003רחמנא\u0004 \u0005[ותכתוב התורה]\u0006 \u0003קשקשת ולא בעי\u0004 \u0005[ולא צריך]\u0006 לכתוב שוב \u0003סנפיר! אמר ר'\u0004 \u0003אבהו, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם של \u0005בית]\u0006 מדרשו של \u0003ר' ישמעאל:\u0004 טעם הדבר הוא לקיים הנאמר \u0003\"יגדיל תורה ויאדיר\"\u0004 (ישעיה מב, כא), ששבח הוא כשהתורה גדלה ומתרחבת, מרחיבה את דבריה.","ועוד כלל דומה, \u0003כל\u0004 דבר (כגון מאכל ומשתה) \u0003הטעון\u0004 (החייב) \u0003ברכה לאחריו\u0004 (לאחר אכילתו או שתייתו) — הריהו גם \u0003טעון ברכה לפניו\u0004 (לפני האכילה או השתייה). \u0003ו\u0004אולם \u0003יש\u0004 דבר \u0003שטעון ברכה לפניו, ואין טעון ברכה לאחריו.\u0004","שנינו במשנתנו כי יש דבר מאכל ומשתה החייב בברכה לפני אכילתו, ולא לאחר אכילתו. ומבררים: \u0003לאתויי מאי\u0004 \u0005[לרבות\u0006 את \u0005מה]\u0006 בא כלל זה? ומשיבים: \u0003לאתויי\u0004 \u0005[לרבות]\u0006 \u0003ירק,\u0004 שמברכים עליו ברכה לפני אכילתו, ולא לאחר אכילתו. \u0003ו\u0004שואלים: \u0003ל\u0004שיטת \u0003ר' יצחק\u0004 ש\u0003מברך\u0004 על \u0003ירק\u0004 אף לאחרי אכילתו, \u0003לאתויי מאי\u0004 \u0005[לרבות מה]\u0006 בא כלל זה שבמשנתנו? ומשיבים: \u0003לאתויי מיא\u0004 \u0005[לרבות מים],\u0006 שמברכים עליהם לפני שתייתם, ולא לאחר שתייתם.","ושואלים: \u0003ול\u0004שיטת \u0003רב פפא\u0004 ש\u0003מברך אמיא\u0004 \u0005[על מים]\u0006 גם לאחר שתייתם, \u0003לאתויי מאי\u0004 \u0005[לרבות מה]\u0006 בא כלל זה שבמשנתנו? ומשיבים: \u0003לאתויי\u0004 \u0005[לרבות]\u0006 \u0003מצו‍ת.\u0004 שמברכים על מעשה המצוות, כגון לבישת הציצית ונטילת הלולב ושאר המצוות, לפני קיום מצוותן, ולא לאחר עשייתן. ושואלים: \u0003ול\u0004מנהגם של \u0003בני מערבא\u0004 \u0005[המערב,\u0006 ארץ ישראל\u0005]\u0006 \u0003דמברכי בתר דסליקו תפילייהו\u0004 \u0005[שמברכים לאחר שהסירו תפיליהם]\u0006 ברכה זו \u0003\"אשר קדשנו במצו‍תיו וצונו לשמור חוקיו\",\u0004 \u0003לאתויי מאי\u0004 \u0005[לרבות מה]\u0006 כלל זה שבמשנתנו? \u0003לאתויי\u0004 \u0005[לרבות]\u0006"],["\u0003ריחני\u0004 (בשמים), שהנאתם מועטה, ומשום כך מברכים עליהם \"בורא מיני בשמים\" לפניהם, אך לא לאחריהם.","\u0003תינוקת\u0004 (הקטנה, לאחר שהגיעה לגיל בגרות) \u0003שהביאה\u0004 (שהופיעו אצלה) \u0003שתי שערות\u0004 במקום הערווה — הריהי נחשבת כגדולה לכל דבר, ואם מת בעלה בלא זרע, ונפלה לפני אחיו לייבום, הריהי \u0003או חולצת\u0004 לאחי בעלה, ומותרת להינשא לכל, \u0003או מתיבמת\u0004 לו לאשה. \u0003וחייבת בכל מצו‍ת האמורות בתורה\u0004 שנשים חייבות בהן.","\u0003וכן תינוק\u0004 (הקטן לאחר שהגיע לגיל בגרות) \u0003שהביא שתי שערות\u0004 — הריהו מעתה נחשב כגדול, ו\u0003חייב בכל מצו‍ת האמורות בתורה.\u0004 \u0003וראוי\u0004 הוא מצד גילו \u0003להיות בן סורר ומורה\u0004 (אם התקיימו בו שאר התנאים שבהם הוא נעשה בן סורר ומורה), בפרק הזמן \u0003משיביא שתי שערות עד שיקיף\u0004 את הגיד \u0003זקן\u0004 (שיער). שכן בפרק זמן זה הוא יצא מכלל קטן שאינו נענש על מעשיו, ואולם עדיין הוא לא הגיע לכלל מי שהוא ראוי להיות אב (שכל עוד לא הקיף הזקן את הגיד, אין הוא ראוי להוליד). שכך היא הגדרת הראוי להיות בן סורר ומורה: שהוא \"בן\" ולא אב.","ומסבירים, כי כוונת הלשון \"זקן\" הריהי לשיער \u0003התחתון\u0004 שמסביב לגיד \u0003ולא\u0004 לשיער \u0003העליון\u0004 שעל פני אדם. ומדוע השתמשו חכמים בלשון זו, שיש אפשרות שלא להבינה כראוי? \u0003אלא שדברו חכמים בלשון נקיה.\u0004","\u0003תינוקת\u0004 (קטנה שעדיין לא הגיעה לגיל בגרות) \u0003ש\u0004היא יתומה מאביה, והשיאוה אמה ואחיה, כל עוד היא קטנה יכולה היא למאן בבעלה, ולהפקיע את נישואיהן. ואולם משהגיעה לגיל שתים עשרה שנה ויום אחד ו\u0003הביאה שתי שערות\u0004 — שוב \u0003אינה יכולה למאן.\u0004 \u0003ר'\u0004 \u0003יהודה אומר:\u0004 עדיין יכולה היא למאן, \u0003עד שירבה\u0004 השיער בבית הערוה, עד כדי שייראה אותו \u0003ה\u0004מקום \u0003שחור.\u0004","שנינו במשנתנו שהקטנה שהגיעה לגיל בגרות והביאה שתי שערות, נחשבת כגדולה לענין זה שאם נפלה לייבום הריהי חולצת או מתייבמת, וכן חייבת בכל המצוות שהאשה חייבת בהן. \u0003ו\u0004שואלים: \u0003כיון דתנן\u0004 \u0005[ששנינו]\u0006 שהיא \u0003חייבת בכל\u0004 ה\u0003מצו‍ת האמורות בתורה,\u0004 דין זה שהיא \u0003או חולצת או מתיבמת למה לי\u0004 לשנותו, והרי בכלל כל המצוות הוא!","ומשיבים: כדי \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004שיטתו של \u0003ר' יוסי,\u0004 ש\u0003אמר:\u0004 אכן \u0003\"איש\" כתוב בפרשה\u0004 של החליצה (\"ואם לא יחפוץ האיש לקחת את יבמתו...\". דברים כה, ז). ולכן אין דין חליצה אלא בנחלץ שהוא גדול, \u0003אבל\u0004 לשון \u0003אשה\u0004 לא נזכרה בפרשה, אלא \"יבמתו\" — להורות שנוהג דין הייבום והחליצה, \u0003בין\u0004 במי שהיא \u0003גדולה ובין\u0004 במי שהיא \u0003קטנה.\u0004 לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו],\u0006 שאין הלכה כר' יוסי, ולכן דינה של היבמה, \u0003דאי אייתי\u0004 \u0005[שאם הביאה]\u0006 \u0003שתי שערות\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חולצת או מתייבמת. אבל \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 הביאה שתי שערות — \u0003לא.\u0004 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? משום שדינה של ה\u0003אשה כ\u0004דינו של ה\u0003איש.\u0004","ושואלים עוד, בדומה לכך: \u0003וכיון דתנא\u0004 \u0005[ששנה]\u0006 בהמשך המשנה \u0003\"וכן התינוק שהביא שתי שערות\",\u0004 נחשב כגדול לכל דבר, אם כן זה ששנינו \u0003\"חייב בכל המצו‍ת האמורות בתורה\" למה לי?\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ששנה במשנה שמשהביא שתי שערות הריהו חייב בכל המצוות האמורות בתורה, \u0003משום דקבעי למתני\u0004 \u0005[שהוא רוצה לשנות]\u0006 את הדין המיוחד לו \u0003\"וראוי להיות בן סורר ומורה\"\u0004 — הרי כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 זאת \u0003חדא זימנא\u0004 \u0005[פעם אחת],\u0006 במסכת סנהדרין: \u0003אימתי הוא\u0004 נעשה \u0003בן סורר ומורה\u0004 — \u0003משיביא שתי שערות ועד שיקיף זקן, התחתון ולא העליון, אלא שדברו חכמים בלשון נקיה!\u0004","ומשיבים: \u0003אין הכי נמי\u0004 \u0005[אכן כן גם כן],\u0006 כשאלתך, שלא היה צריך התנא במשנתנו לומר זאת \u0003אלא איידי דפריש מילי\u0004 \u0005[אגב שפירש דברי,\u0006 הלכות\u0005]\u0006 הנוגעות ל\u0003תינוקת\u0004 — \u0003קמפרש נמי מילי\u0004 \u0005[הוא מפרש גם כן דברי,\u0006 הלכות\u0005]\u0006 הנוגעות ל\u0003תינוק.\u0004","שנינו במשנתנו כי ה\u0003תינוקת\u0004 היתומה שהשיאוה אמה ואחיה \u0003שהביאה\u0004 שתי שערות — אינה יכולה עוד למאן בנישואיה, ואילו ר' יהודה סובר שיכולה עדיין למאן, עד לזמן שבו השחיר מקום הערוה מרוב שיער. ובענין זה \u0003אמר ר'\u0004 \u0003אבהו, אמר ר'\u0004 \u0003אלעזר: הלכה כר'\u0004 \u0003יהודה\u0004 במחלוקתו זו עם חכמים.","\u0003ו\u0004בהסבר שיטת ר' יהודה: \u0003מודה ר'\u0004 \u0003יהודה\u0004 לחכמים, \u0003שאם נבעלה\u0004 הקטנה לבעלה \u0003לאחר שהביאה שתי שערות,\u0004 והרי היא מתקדשת לו בכך קידושין מן התורה, כקידושי ביאה — \u0003שוב אינה יכולה למאן\u0004 בו ולהפקיע בכך את הקידושין, שכן אין תקנה זו של מיאון אלא להפקיע קידושין שמדברי חכמים.","ונמסר כי \u0003חברוהי\u0004 \u0005[חבריו]\u0006 של \u0003רב כהנא סבור למעבד עובדא\u0004 \u0005[חשבו לעשות מעשה]\u0006 להתיר לקטנה שהביאה שתי שערות שתמאן, ו\u0003כר' יהודה\u0004 שבמשנתנו, \u0003ואף על גב\u0004 שקטנה זו \u0003נבעלה\u0004 על ידי בעלה לאחר שהביאה שתי שערות, משום שסברו שכל עוד לא השחיר מקום בית הערוה לא התקדשה בכך קידושין של תורה.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב כהנא: לא כך היה מעשה בבתו\u0004 היתומה הקטנה \u0003של ר'\u0004 \u0003ישמעאל\u0004 שהשיאוה אמה ואחיה, \u0003שבאת\u0004 (שבאה) \u0003לבית המדרש למאן\u0004 בבעלה. \u0003ובנה מורכב לה על כתפה.\u0004 \u0003ואותו היום הוזכרו דבריו של ר'\u0004 \u0003ישמעאל\u0004 (שקטנה יכולה למאן אף שהביאה שתי שערות ואף שנבעלה לבעלה לאחר מכן) \u0003בבית המדרש, ובכתה בכייה גדולה בבית המדרש.\u0004","\u0003אמרו\u0004 החכמים יושבי בית המדרש: האם ייתכן ש\u0003דבר\u0004 הלכה \u0003שאמר אותו צדיק\u0004 (שיכולה היא למאן, אפילו בא עליה בעלה לאחר שהביאה שתי שערות) \u0003יכשל בו זרעו\u0004 (שתפקיע קידושיה במיאונה, ונמצא שילדה בן שלא מן הנישואין).","שכן \u0003אמר רב יהודה, אמר שמואל משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל\u0004 על האמור בדין האשה המזנה, הנאסרת על בעלה: \u0003\"והיא לא נתפשה\"\u0004 (במדבר ה, יד), כלומר, לא נאנסה — זו היא ה\u0003אסורה\u0004 לבעלה, ומכאן נסיק: \u0003הא\u0004 \u0005[הרי]\u0006 זו ש\u0003נתפשה\u0004 — הריהי \u0003מותרת\u0004 לבעלה. \u0003ויש לך אחרת, שאף על פי שלא נתפשה\u0004 אלא מרצונה היה הדבר — הריהי \u0003מותרת\u0004 לבעלה. \u0003ואיזו\u0004 היא \u0003זו\u0004 — \u0003שקדושיה\u0004 היו \u0003קדושי טעות,\u0004 כגון זה שקידש את הקטנה על ידי אמה ואחיה \u0003שאף על פי שבנה מורכב על כתפה\u0004 — \u0003ממאנת והולכת לה.\u0004 ואף שבעל אותה לאחר שהביאה שתי שערות, הריהו סומך על קידושיו הראשונים, שהם מדברי חכמים, ואינה מתקדשת לו בביאה זו בקידושין מן התורה, ויכולה היא איפוא להפקיע את קידושיה שמדברי חכמים.","\u0003ו\u0004נמסר, כי בעקבות מקרה זה בבתו של ר' ישמעאל, שמיאנה בבעלה בעוד שיש לה בן, \u0003נמנו\u0004 החכמים להצבעה, \u0003וגמרו\u0004 (וקבעו הלכה): \u0003עד מתי הבת ממאנת\u0004 — עד שתביא שתי שערות! כיון ששמעו חבריו של רב כהנא את דבריו אלה, \u0003פרוש\u0004 \u0005[פרשו,\u0006 חזרו בהם\u0005]\u0006 מכוונתם הקודמת לאפשר לה למאן, וכשיטת ר' יהודה, \u0003ולא עבוד עובדא\u0004 \u0005[עשו מעשה].\u0006","ועוד מסופר שר' יצחק ותלמידי ר' \u0003חנינא\u0004 באה לפניהם שאלה דומה, בקטנה שהביאה שתי שערות, שרצתה למאן בנישואיה לבעלה, וחכמים \u0003עבוד עובדא\u0004 \u0005[עשו מעשה]\u0006 והתירו לה שתמאן, ו\u0003כ\u0004שיטת \u0003ר' יהודה, ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003נבעלה.\u0004 ובעקבות זה, הלכה אותה אשה ונישאה לאיש אחר. ומסופר כי \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב שמן בר אבא\u0004 ו\u0003אמרה קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן, אזל\u0004 \u0005[הלך]\u0006 \u0003ר' יוחנן אמרה קמיה\u0004 \u0005[לפני]\u0006 \u0005ר' יהודה נשיאה.\u0006 \u0003שדר\u0004 \u0005[שלח]\u0006 ר' יהודה נשיאה \u0003בלשא\u0004 \u0005[שוטרים],\u0006 \u0003ואפקוה\u0004 \u0005[והוציאוה]\u0006 מבעלה השני.","שנינו במשנתנו שלדעת ר' יהודה יכולה למאן אף לאחר שהביאה שתי שערות, עד שירבה השחור. ובהסבר דבריו \u0003אמר רב חסדא,\u0004 \u0003אמר מר עוקבא: לא שירבה השחור ממש, אלא כדי שיהיו שתי שערות שוכבות\u0004 (משתרעות על פני אותו מקום, \u0003ונראות כמי שירבה השחור על הלבן.\u0004 \u0003רבא אמר:\u0004 עד שתהיינה \u0003שתי שערות המקיפות\u0004 אותו מקום \u0003משפה לשפה.\u0004","שנינו במשנתנו כי הבאת שתי שערות הריהי סימן גדלות. ובאשר לטיבן של שערות אלו, \u0003אמר ר'\u0004 \u0003חלבו, אמר רב הונא: שתי שערות שאמרו\u0004 חכמים שהן סימן גדלות — \u0003צריך שיהא בעיקרן גומות.\u0004 \u0003רב מלכיו אמר\u0004 בשם \u0003רב אדא בר אהבה:\u0004 שתי \u0003גומות\u0004 שיער הנמצאות בקטנים, \u0003אף על פי שאין\u0004 בגומות אלה \u0003שערות\u0004 — סימן גדלות הוא, שכיון שיש גומה, הרי זה מוכיח שהיה בה שערה, אף שאיננה עתה בה, מפני שנשרה.","הלכה זו נאמרה מפי החכם הנקרא רב מלכיו, וכדי שלא להתבלבל עם הלכות שאמר חכם אחר הנקרא בשם דומה רב מלכיא, \u0003אמר רב חנינא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא:\u0004 את ההלכה בענין ה\u0003שפוד,\u0004 ואת ההלכה בענין ה\u0003שפחות, ו\u0004את ההלכה בענין \u0003גומות\u0004 — אמרן \u0003רב מלכיו.\u0004 ולעומת זאת, את ההלכה בענין \u0003בלורית,\u0004 ואת ההלכה בענין \u0003אפר מקלה, ו\u0004את ההלכה בענין \u0003גבינה\u0004 — אמר \u0003רב מלכיא.\u0004","\u0003רב פפא אמר\u0004 אופן אחר: ההלכות הנוגעות לעניינים השנויים ב\u0003מתניתין ומתניתא\u0004 \u0005[\u0006ב\u0005משניות וברייתות]\u0006 — אמר \u0003רב מלכיא,\u0004 ואת ההלכות שלמדנום כ\u0003שמעתתא\u0004 \u0005[שמועת הלכה\u0006 לעצמן\u0005]\u0006 — אמר \u0003רב מלכיו.\u0004 \u0003וסימנא\u0004 \u0005[וסימן]\u0006 לזכירת כלל זה: \u0003מתניתא מלכתא\u0004 \u0005[הברייתא,\u0006 ובדומה לה, המשנה \u0005מלכה,\u0006 דברי הלכה הנוגעים למשנה רמז לרב מלכיא\u0005].\u0006","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל ביניהם, בין רב חנינא בנו של רב איקא לבין רב פפא\u0005]?\u0006 ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל בהלכה זו של \u0003שפחות\u0004 מי אמרה, שכן כיון שקשורה היא למשנה הריהי לשיטת רב פפא הלכתו של רב מלכיא, ואולם רב חנינא בנו של רב איקא שנה אותה בין הלכותיו של רב מלכיו. ולעצם ההלכה רב מלכיו שהגומות כשלעצמן, אף שאין בהן שיער, נחשבות כסימן גדלות.","\u0003אמר רב אשי,\u0004 כך \u0003אמר לי מר זוטרא, קשה\u0004 \u0005[התקשה]\u0006 \u0003בה ר' חנינא מסורא:\u0004 מדוע אין דין זה של הגומות נאמר במפורש במשנה, \u0003לא לישתמיט\u0004 \u0005[לא ישתמט]\u0006 ה\u0003תנא\u0004 של משנתנו, \u0003ואשמועינן\u0004 \u0005[וישמעינו]\u0006 דין זה של \u0003גומות!\u0004 ומשיבים: \u0003אי אשמועינן\u0004 \u0005[אם היה משמיענו]\u0006 דין זה של ה\u0003גומות\u0004 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שאין זה סימן גדלות אלא \u0003עד שיהו שתי שערות בשתי גומות.\u0004 לכך, בזה שלא הזכיר כלל במשנה גומות, \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 ש\u0003אפילו שתי שערות\u0004 הנמצאות \u0003בגומא אחת\u0004 הרי זה סימן גדלות.","ותוהים: \u0003ומי איכא כי האי גוונא\u0004 \u0005[והאם יש\u0006 בכלל \u0005כדבר הזה],\u0006 שתהיינה שתי שערות בגומה אחת? \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"אשר בשערה ישופני והרבה פצעי חנם\"\u0004 (איוב ט, יז), \u0003ואמר רבא\u0004 בפירושו על פסוק זה: \u0003איוב בסערה חירף, בסערה השיבוהו.\u0004 \u0003בסערה חירף\u0004 — \u0003אמר לפניו: רבונו של עולם, שמא רוח סערה עברה לפניך ונתחלפה לך בין איוב לאויב,\u0004 בגלל דמיון של שתי מלים אלה? \u0003בסערה השיבוהו\u0004 — \u0003\"ויען ה'\u0004 \u0003את\u0004"],["\u0003איוב מן הסערה ויאמר\"\u0004 (איוב לח, א) \u0003אליו: שוטה שבעולם, הרבה נימין\u0004 (שערות) \u0003בראתי בראשו של אדם, ולכל נימא ונימא בראתי לו גומא בפני עצמה,\u0004 בכדי \u0003שלא יהיו שתים יונקות מגומא אחת.\u0004 \u0003שאלמלא\u0004 (שאילו היו) \u0003שתים יונקות מגומא אחת\u0004 — היה הדבר \u0003מכחיש\u0004 (מחליש) את \u0003מאור עיניו של אדם.\u0004 ומאחר שאפילו \u0003גומא בגומא לא נתחלף לי,\u0004 מי ששמו \u0003איוב באויב נתחלף לי?\u0004 ולענייננו מוכח מכאן כי אין שתי שערות צומחות בגומה אחת!","ומשיבים: \u0003לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמרנו שיכולות לצמוח שתי שערות בגומה אחת — הרי זה \u0003בגופא\u0004 \u0005[ב\u0006שערות ה\u0005גוף],\u0006 ואילו \u0003הא\u0004 \u0005[זה]\u0006 שלמדנו מדברי התשובה לאיוב כי אין שתי שערות יוצאות מגומה אחת — הרי זה \u0003ברישא\u0004 \u0005[ב\u0006שערות הראש].","ועוד בהגדרת שתי השערות של סימן גדלות, \u0003אמר רב יהודה,\u0004 \u0003אמר שמואל: שתי שערות שאמרו\u0004 חכמים שהם סימני גדלות — \u0003אפילו\u0004 לא היו בקירבת מקום זו לזו, אלא היו רחוקות זו מזו, שהיתה שערה \u0003אחת על הכף\u0004 (מקום שמעל האבר, ומתחת לכרס, ובולט כעין כף) \u0003ו\u0004שערה \u0003אחת על הביצים\u0004 של הבן הקטן.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא\u0006 האומרת גם כן כך]: \u0003שתי שערות שאמרו\u0004 חכמים שהן סימן גדלות — \u0003אפילו\u0004 היתה שערה \u0003אחת בגבה\u0004 (מתחת לבית הערוה של הילדה) \u0003ו\u0004שערה \u0003אחת בכריסה.\u0004 או שהיתה שערה \u0003אחת על גבי קשרי אצבעותיה של יד, ו\u0004שערה \u0003אחת על גבי קשרי אצבעותיה של רגל,\u0004 אלו \u0003דברי ר'\u0004 \u0003שמעון בן יהודה איש כפר עכו שאמר משום\u0004 \u0005[בשם]\u0006 \u0005ר' שמעון.\u0006 \u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[חכמים],\u0006 מה דעתם בענין זה? \u0003אמר רב חסדא:\u0004 לשיטת חכמים אין השערות משמשות סימן גדלות \u0003עד שיהו שתי שערות במקום אחד.\u0004","שנינו במשנתנו שנחלקו חכמים ור' יהודה עד מתי יכולה הקטנה למאן, שלדעת חכמים ממאנת עד שתביא שתי שערות משהגיעה לגיל בגרות, ולדעת ר' יהודה ממאנת אף לאחר שתביא שתי שערות, עד שירבה השחור. ובענין זה עוד \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003עד מתי הבת ממאנת? עד שתביא שתי שערות,\u0004 אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 \u0003ר'\u0004 \u0003יהודה אומר: עד שירבה השחור.\u0004 \u0003ר'\u0004 \u0003יוסי אומר: עד שתקיף העטרה\u0004 בשיער. \u0003בן שלקות אומר: עד שתכלכל\u0004 (שיהיה מקום הערוה רצוף שיער).","\u0003ואמר ר'\u0004 \u0003שמעון, מצאני חנינא בן חכינאי ב\u0004יישוב \u0003צידן ואמר\u0004 לי: \u0003כשאתה מגיע אצל ר'\u0004 \u0003עקיבא, אמור לו: \"עד מתי הבת ממאנת\"? אם יאמר לך: \"עד שתביא שתי שערות\", אמור לו: \"והלא בן שלקות העיד במעמד כולכם ביבנה: עד שתכלכל\", ולא אמרתם לו דבר!\u0004 הרי שהודיתם לו בכך.","וסיפר ר' שמעון: \u0003כשבאתי אצל ר'\u0004 \u0003עקיבא,\u0004 ואמרתי לו את הדברים, ו\u0003אמר לי: כלכול זה\u0004 — \u0003איני יודע מהו, בן שלקות\u0004 — \u0003איני מכיר,\u0004 ולדעתי \u0003עד מתי הבת ממאנת\u0004 — \u0003עד שתביא שתי שערות.\u0004","\u0003שתי שערות האמורות בפרה\u0004 אדומה, שאם נמצאו בה שתי שערות שחורות או לבנות הריהי פסולה, \u0003ו\u0004כן שתי שערות האמורות \u0003בנגעים,\u0004 שכשצמחו שתי שערות לבנות בתוך הבהרת הריהן סימן שזהו נגע טמא. \u0003ו\u0004כן שתי שערות \u0003האמורות בכל מקום\u0004 — אין הן נחשבות אלא אם כן הן גדולות במידה כזו שיש בהן \u0003כדי לכוף\u0004 (לכופף) את \u0003ראשן\u0004 עד שיגיע \u0003לעיקרן\u0004 (לשורשן), אלו \u0003דברי ר'\u0004 \u0003ישמעאל.\u0004 \u0003ר'\u0004 \u0003אליעזר אומר:\u0004 צריך שתהיינה גדולות במידה שיש בהן \u0003כדי\u0004 לאחוז בהן ו\u0003לקרוץ\u0004 (לחתוך) אותן \u0003בציפורן.\u0004 \u0003ר'\u0004 \u0003עקיבא אומר:\u0004 צריך שתהיינה גדולות במידה כזו \u0003כדי שיהו ניטלות בזוג\u0004 (נגזזות במספריים).","שנינו במשנתנו שיטות שונות בגודל השערות המחשיבן לשיער, ועל כך \u0003אמר רב חסדא, אמר מר עוקבא: הלכה כדברי כולן,\u0004 ככל השיטות הללו, \u0003להחמיר.\u0004 שרק אם התקיימו כל התנאים הללו נחשבות אלה לשערות, או לחילופין, יש להחמיר שאפילו אם התקיים תנאי אחד בלבד מכל אלה, הרי אלו נחשבות שערות.","האשה \u0003הרואה כתם\u0004 אדום על בגדה, \u0003הרי זו מקולקלת\u0004 (לסדר זמני נדתה), שכיון שאינה יודעת מתי נראה הדם, אינה יודעת גם מתי הם שבעת ימי נדתה, ומתי יתחיל מנין אחד עשר הימים של זיבה.","\u0003ו\u0004דינה, שהיא \u0003חוששת משום זוב.\u0004 שאם ראתה את הכתם לאחר שעברו שלושה ימי זיבה מזמן שלבשה את חלוקה זה, והכתם הוא בגודל שלושה גריסים ויותר, יש לחשוש שמא בכל יום ויום משלושת הימים הללו ראתה כגריס ועוד (כשיעור הכתם המטמא). ולאחר שעברו עליה שלושת ימי זיבה, הריהי מעתה זבה גמורה וצריכה למנות שבעה נקיים. אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 \u0003ו\u0004אילו \u0003חכמים אומרים: אין ב\u0004מקרה זה, שלבשה חלוק אחד במשך שלושה ימים ומצאה בו כתם כזה שיש בו שיעור שלושה \u0003כתמים משום\u0004 חשש ל\u0003זוב.\u0004","שנינו במשנתנו מחלוקת ר' מאיר וחכמים בדינה של האשה שמצאה כתם על חלוקה. ומבררים: כשיטת \u0003מאן\u0004 \u0005[מי]\u0006 היא שיטתם זו של \u0003חכמים?\u0004 ומשיבים: כשיטת ר' חנינא בן אנטיגנוס היא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' חנינא בן אנטיגנוס אומר: כתמים אין\u0004 לחשוש \u0003בהן משום זוב.\u0004 \u0003ו\u0004אולם יש \u0003פעמים שהכתמים מביאין לידי זיבה.\u0004","ומסבירים: \u0003כיצד\u0004 הוא האופן שהכתמים מביאים לידי זיבה, לשיטת ר' חנינא בן אנטיגנוס? — \u0003לבשה\u0004 האשה במשך שלושה ימים \u0003שלשה חלוקות\u0004 שונים, \u0003הבדוקות לה\u0004 לפני כן שהם נקיים מכתם, בכל יום חלוק אחד, \u0003ומצאה עליהם,\u0004 על כל אחד מהם, \u0003כתם.\u0004 \u0003או שראתה שני ימים\u0004 בזה אחר זה דם מגופה, \u0003ו\u0004\u0003ביום השלישי מצאה כתם על\u0004 \u0003חלוק אחד\u0004 שלבשתו באותו יום — \u0003הן הן הכתמים המביאין לידי זיבה.\u0004","ושואלים: לשיטת ר' חנינא בן אנטיגנוס \u0003השתא\u0004 \u0005[עכשיו]\u0006 שאפילו ראתה כתם ב\u0003שלשה חלוקות, דלאו\u0004 \u0005[שלא]\u0006 \u0003מגופה קחזיא\u0004 \u0005[היא רואה]\u0006 — בכל זאת \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 בה לזיבה. אם ראתה דם מגופה \u0003שני ימים ו\u0004מצאה כתם ב\u0003חלוק אחד מיבעיא\u0004 \u0005[נצרך]\u0006 לומר שחוששים בה לזיבה?","ומשיבים: יש חידוש בדבר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003כל\u0004 מקרה \u0003כי האי גוונא\u0004 \u0005[כעין זה],\u0006 שראתה יומיים דם מגופה, וכתם על חלוקה ביום השלישי שתהא \u0003מביאה קרבן ונאכל\u0004 כדין זבה ודאית, לכן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאין היא אלא זבה מספק, ומביאה חטאת העוף הבאה על הספק, ואינה נאכלת.","\u0003אמר רבא: בהא זכנהו\u0004 \u0005[ב\u0006טענה \u0005זו זכה,\u0006 ניצח בויכוח\u0005]\u0006 \u0003ר' חנינא בן אנטיגנוס לרבנן\u0004 \u0005[את חכמים]:\u0006 \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מיוחד\u0005]\u0006 \u0003פחות משלשה גריסין במקום אחד\u0004 ש\u0003לא חיישינן\u0004 \u0005[חוששים אנו]\u0006 בה לזיבה — משום \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 כי \u0003בתרי יומי חזיתיה\u0004 \u0005[בשני ימים ראתה אותו],\u0006 ומכאן בזמן שמצאה על חלוקה \u0003שלשה גריסין במקום אחד נמי\u0004 \u0005[גם כן]\u0006 \u0003נימא תרתי ופלגא\u0004 \u0005[נאמר\u0006 כי \u0005שנים וחצי\u0006 גריסים\u0005]\u0006 \u0003מגופה חזיתיה\u0004 \u0005[ראתהו],\u0006 \u0003ו\u0004אילו \u0003אידך\u0004 \u0005[ה\u0006גריס האחר] \u0003אגב\u0004 (על ידי) \u0003זוהמא\u0004 הכרוכה ב\u0003דם\u0004 הנדות באה \u0003מאכולת\u0004 (כינה), והדם \u0003הוא\u0004 מן המאכולת הזו.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה משיבים הם על כך? ומשיבים: לדעתם \u0003כיון\u0004 שבמקרה שמצאה כתם שגודלו שלושה גריסים ויותר, \u0003דאיכא לפלוגי\u0004 \u0005[שיש מקום לחלק]\u0006 \u0003בגריס ועוד לכל יומא\u0004 \u0005[יום]\u0006 משלושת הימים הללו — \u0003לא תלינן\u0004 \u0005[אין אנו תולים]\u0006 את הכתם בדם מאכולת.","\u0003ור' חנינא בן אנטיגנוס,\u0004 מה משיב הוא על כך? \u0003שלשה גריסין במקום אחד הוא דלא חיישינן\u0004 \u0005[שאין אנו חוששים],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 נסיק מכאן כי \u0003בשלשה מקומות\u0004 — \u0003חיישינן\u0004 \u0005[חוששים אנו].\u0006 ושואלים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרת\u0004 כי \u0003בשלשה חלוקות\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בשלשה מקומות\u0004 — \u0003לא!\u0004","ומשיבים: \u0003לדבריהם דרבנן קאמר להו\u0004 \u0005[של חכמים הוא אמר להם].\u0006 וכך אמר: \u0003לדידי\u0004 \u0005[לי עצמי,\u0006 לשיטתי\u0005]\u0006 \u0003בשלשה חלוקות\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בשלשה מקומות\u0004 — \u0003לא.\u0004 \u0003אלא לדידכו\u0004 \u0005[לכם,\u0006 לשיטתכם\u0005],\u0006 \u0003אודו\u0004 \u0005[הודו]\u0006 \u0003לי מיהת\u0004 \u0005[לפחות],\u0006 \u0003דהיכא דחזאי\u0004 \u0005[שהיכן,\u0006 במקרה \u0005שראתה]\u0006 \u0003שלשה גריסין במקום אחד, דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003תרי ופלגא\u0004 \u0005[שנים וחצי]\u0006 \u0003מגופה חזיתיה\u0004 \u0005[ראתה אותו],\u0006 \u0003ואידך\u0004 \u0005[והאחר]\u0006 — \u0003אגב זוהמא\u0004 \u0005[על ידי הלכלוך,\u0006 שבהפרשת הדם מגופה\u0005]\u0006 באה מאכולת, ו\u0003דם מאכולת הוא!\u0004","\u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם סבורים? — \u0003כיון דאיכא לפלוגי\u0004 \u0005[שיש\u0006 מקום \u0005לחלק]\u0006 \u0003בגריס ועוד לכל יומא\u0004 \u0005[לכל יום]\u0006 — \u0003לא תלינן\u0004 \u0005[אין אנו תולים].\u0006","ועוד בענין אשה המוצאת כתם בחלוקה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003הרואה כתם\u0004 על חלוק שלבשתו כמה ימים, ואינה יודעת ממתי הכתם, וכיצד בא, מה דינה? \u0003אם יש בו\u0004 בכתם זה שיעור \u0003כדי לחלק\u0004 אותו לכדי \u0003שלשה גריסין, שהן\u0004 כלומר, שבכל אחד יש \u0003כגריס ועוד\u0004 (שהוא שיעור הכתם המטמא) — הריהי \u0003חוששת\u0004 לזיבה, שמא נוצר כתם זה משלוש ראיות, שיש בכל אחת מהן כדי שיעור טומאה. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שהיה הכתם קטן משיעור זה — \u0003אינה חוששת.\u0004","\u0003ר'\u0004 \u0003יהודה בן אגרא אומר משום\u0004 \u0005[בשם]\u0006 \u0003ר' יוסי: אחת זו\u0004 שראתה שיעור כתם שגודלו שלושה גריסים ועוד, \u0003ואחת זו\u0004 שמצאה כתם פחות משיעור זה — הריהי \u0003חוששת\u0004 משום זיבה, שכן יש לחשוש שמא אמנם ראתה שתי ראיות המטמאות, אבל אחת הראיות היתה בזמן בין השמשות, וראיה זו עולה לראיית יומיים, ובכללן הן שלוש ראיות."],["\u0003אמר רבי\u0004 בהכרעת מחלוקת זו שבין חכמים ור' יהודה בן אגרא: \u0003נראין דברי ר'\u0004 \u0003יהודה בן אגרא\u0004 שחוששים שראתה ראייה אחת בין השמשות, ועולה לה לשתי ראיות — \u0003ב\u0004מקרה \u0003שלא בדקה, ו\u0004נראים \u0003דברי חכמים\u0004 שאין חוששים לכך — \u0003ב\u0004מקרה \u0003שבדקה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בדקה\", ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"לא בדקה\"\u0004 שבדבריו? \u0003אמר רבא, אשכחתינהו לרבנן דבי רב דיתבי וקאמרי\u0004 \u0005[פגשתי את החכמים של בית המדרש של רב שיושבים ואומרים]\u0006 בפירוש דבריו: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שבדקה\u0004 האשה את \u0003עצמה, ו\u0004אולם \u0003לא בדקה\u0004 את \u0003חלוקה, ואף\u0004 את \u0003עצמה לא בדקה אלא\u0004 בפרק זמן \u0003בין השמשות\u0004 שלשיטת \u0003ר' יהודה\u0004 (משך זמן הליכת חצי מיל, שלפני צאת הכוכבים), \u0003ו\u0004אילו \u0003ב\u0004פרק הזמן שהוא \u0003בין השמשות\u0004 לשיטת \u0003ר' יוסי\u0004 (שהוא כהרף עין, לפני צאת הכוכבים) \u0003לא בדקה.\u0004","\u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]\u0006 כי זמן זה של \u0003בין השמשות\u0004 לשיטת \u0003ר' יוסי\u0004 — \u0003ליליא\u0004 \u0005[לילה]\u0006 \u0003הוא,\u0004 ולכן זה שלא בדקה בפרק זמן זה, אינו משנה, שהרי לשיטתו הוא כבר לילה. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בדקה בבין השמשות\u0004 שלשיטת \u0003ר' יהודה,\u0004 ולא מצאה דם, ולכן אין לומר שראתה בבין השמשות, שתעלה לה ראייה זו לשני ימים. \u0003ו\u0004אילו \u0003ר' יוסי\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003דאמר\u0004 \u0005[שאומר]\u0006 כי \u0003בין השמשות\u0004 הזה הקרוב לצאת הכוכבים אף הוא \u0003ספיקא הוי\u0004 \u0005[ספק הוא],\u0006 ולכן יש לחשוש שראתה אז, ועולה לה ראייה זו לשני ימים.","\u0003ואמינא להו אנא\u0004 \u0005[ואמרתי להם אני]:\u0006 \u0003אילמלי\u0004 (אילו) היו \u0003ידיה\u0004 נתונות בבדיקה \u0003בעיניה\u0004 (כינוי בלשון נקיה לבית הערווה) \u0003כל\u0004 משך זמן \u0003בין השמשות\u0004 — \u0003יפה אתם אומרים, עכשיו\u0004 שבוודאי לא כך היה הדבר, יש מקום לחשש \u0003שמא\u0004 מיד \u0003עם סלוק ידיה ראתה? ואמרו לי: כי קאמרינן\u0004 \u0005[כאשר אמרנו]\u0006 את דברינו, הרי זה מדובר אכן \u0003כשנתנה ידיה בעיניה כל\u0004 משך זמן \u0003בין השמשות.\u0004","ומבררים עוד ברייתא זו, \u0003אמר רבי: נראין דברי ר'\u0004 \u0003יהודה בן אגרא\u0004 בשם ר' יוסי, שיש לחשוש לראיית בין השמשות, העולה לשתי ראיות, \u0003כשלא בדקה.\u0004 ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003לא בדקה?\u0004","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003בדקה ב\u0004זמן המוגדר כבין השמשות לשיטת \u0003ר' יהודה, ולא בדקה ב\u0004זמן המוגדר כבין השמשות לשיטת \u0003ר' יוסי,\u0004 יש להקשות: \u0003מכלל\u0004 הדברים נסיק שרבי אמנם פסק כר' יהודה בן אגרא במקרה זה, אבל \u0003ר' יהודה\u0004 בן אגרא עצמו \u0003סבר\u0004 \u0005[סבור]:\u0006 ש\u0003אף על גב\u0004 ש\u0003בדקה בתרוייהו\u0004 \u0005[בשניהם],\u0006 בשני פרקי בין השמשות, של ר' יהודה ושל ר' יוסי, \u0003חיישא\u0004 \u0005[חוששת]?\u0006 ו\u0003הא\u0004 \u0005[הרי]\u0006 היא \u0003בדקה!\u0004","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמה שאמר רבי ש\u0003לא בדקה,\u0004 הכוונה שלא בדקה, \u0003לא ב\u0004בין השמשות לשיטת \u0003ר' יהודה ולא ב\u0004בין השמשות לשיטת \u0003ר' יוסי, אבל\u0004 אם \u0003בדקה ב\u0004בין השמשות לשיטת \u0003ר' יהודה ולא בדקה ב\u0004בין השמשות לשיטת \u0003ר' יוסי\u0004 — \u0003לא חיישא\u0004 \u0005[אינה חוששת].\u0006","\u0003אלמא\u0004 \u0005[מכאן]\u0006 כי הזמן המוגדר כ\u0003בין השמשות\u0004 לשיטת \u0003ר' יוסי\u0004 — \u0003ל\u0004שיטת \u0003רבי ליליא\u0004 \u0005[לילה]\u0006 \u0003הוא.\u0004 \u0003אימא סיפא\u0004 \u0005[אמור\u0006 עתה את \u0005סוף\u0006 המשנה\u0005]:\u0006 \u0003ודברי חכמים בשבדקה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003בדקה?\u0004","\u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהכוונה ש\u0003בדקה ב\u0004בין השמשות כשיטת \u0003ר' יהודה ולא בדקה ב\u0004בין השמשות כשיטת \u0003ר' יוסי, מכלל\u0004 הדברים אתה למד \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]\u0006 ש\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא בדקה בתרוייהו\u0004 \u0005[בשניהם]\u0006 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003לא בדקה!\u0004","\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 ש\u0003בדקה בין ב\u0004בין השמשות לשיטת \u0003ר' יהודה בין ב\u0004בין השמשות לשיטת \u0003ר' יוסי, אבל\u0004 אם \u0003בדקה ב\u0004בין השמשות לשיטת \u0003ר' יהודה ולא בדקה ב\u0004בין השמשות לשיטת \u0003ר' יוסי\u0004 — \u0003חיישינן\u0004 \u0005[חוששים אנו].\u0006","\u0003אלמא\u0004 \u0005[מכאן נסיק]\u0006 כי \u0003בין השמשות\u0004 לשיטת \u0003ר' יוסי\u0004 — \u0003לרבי ספיקא הוי\u0004 \u0005[ספק הוא],\u0006 והרי מכאן \u0003קשיא\u0004 \u0005[קשה,\u0006 שיש בדבר סתירה] משיטת \u0003רבי\u0004 על שיטת","\u0003רבי!\u0004 ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר,\u0006 זו כוונתו\u0005]: נראין דברי ר'\u0006 \u0003יהודה בן אגרא לרבנן\u0004 \u0005[לחכמים]\u0006 בש \u0003לא בדקה כלל לא ב\u0004בין השמשות לשיטת \u0003ר' יהודה ולא ב\u0004בין השמשות לשיטת \u0003ר' יוסי, שאף חכמים לא נחלקו עליו אלא\u0004 כש\u0003בדקה ב\u0004בין השמשות לשיטת \u0003ר' יהודה, ולא בדקה ב\u0004בין השמשות לשיטת ר' יוסי. \u0003אבל היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003לא בדקה כלל\u0004 — \u0003מודו ליה\u0004 \u0005[מודים לו].\u0006","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]:\u0006 \u0003הרואה כתם,\u0004 אם היה \u0003לראיה מרובה,\u0004 ששיעורו גדול, שלושה גריסים ועוד — הרי זו \u0003חוששת\u0004 לזיבה, אבל \u0003לראיה מועטת\u0004 שהיה קטן משיעור שלושה גריסים ועוד — \u0003אינה חוששת\u0004 לזיבה. \u0003זו דברי ר'\u0004 \u0003יהודה בן אגרא שאמר משום\u0004 \u0005[בשם]\u0006 \u0005ר' יוסי.\u0006","\u0003אמר רבי: אני שמעתי ממנו שאחת זו\u0004 שראתה כתם גדול, \u0003ואחת זו\u0004 שראתה כתם קטן משלושה גריסים ועוד — \u0003חוששת\u0004 לזוב, \u0003ומן הטעם הזה אמר לי: ומה אילו נדה שלא הפרישה בטהרה מן המנחה ולמעלה\u0004 — \u0003לא תהא בחזקת טמאה? ונראין דבריו כשבדקה.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003בדקה? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003בדקה ב\u0004בין השמשות לשיטת \u0003ר' יהודה ולא בדקה ב\u0004בין השמשות לשיטת \u0003ר' יוסי, מכלל\u0004 הדברים אתה למד ש\u0003ר' יהודה בן אגרא סבר\u0004 \u0005[סבור]\u0006 כי \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא בדקה לא ב\u0004בין השמשות לשיטת \u0003ר' יהודה ולא ב\u0004בין השמשות לשיטת \u0003ר' יוסי\u0004 — \u0003לא חיישא\u0004 \u0005[אינה חוששת]\u0006 לזיבה? ומדוע לא תחשוש לכך, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא בדקה!\u0004","\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמדובר ש\u0003בדקה בין ב\u0004בין השמשות לשיטת \u0003ר' יהודה ובין ב\u0004בין השמשות לשיטת \u0003ר' יוסי, מכלל\u0004 הדברים נלמד כי \u0003ר' יהודה בן אגרא סבר\u0004 שאם \u0003בדקה ב\u0004בין השמשות שלשיטת \u0003ר' יהודה ולא בדקה ב\u0004בין השמשות שלשיטת \u0003ר' יוסי\u0004 — \u0003לא חיישא\u0004 \u0005[אינה חוששת].\u0006","\u0003אלמא\u0004 \u0005[מכאן\u0006 נסיק\u0005]\u0006 כי פרק הזמן שהוא \u0003בין השמשות\u0004 לשיטת ר' יוסי, לר' \u0003יהודה בן אגרא\u0004 — \u0003ליליא\u0004 \u0005[לילה]\u0006 \u0003הוא.\u0004 \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' יהודה בן אגרא\u0004 על דברי \u0003ר' יהודה בן אגרא!\u0004","\u0003בשלמא\u0004 \u0005[זה נוח]\u0006 \u0003בלא\u0004 דברי \u0003רבי\u0004 — \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן אפשר להבחין בין המקרים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר ש\u0003בדקה ב\u0004בין השמשות לשיטת \u0003ר' יהודה ולא בדקה ב\u0004בין השמשות לשיטת \u0003ר' יוסי,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 מדובר כש\u0003בדקה נמי\u0004 \u0005[גם כן]\u0006 \u0003ב\u0004בין השמשות לשיטת \u0003ר' יהודה וב\u0004בין השמשות לשיטת ר' יוסי. \u0003אלא בדרבי קשיא\u0004 \u0005[ב\u0006של דברי \u0005רבי קשה]!\u0006","ומתרצים: אין זו סתירה, שכן נחלקו בדבר \u0003תרי תנאי\u0004 \u0005[שני תנאים]\u0006 \u0003ואליבא\u0004 \u0005[ולשיטתו]\u0006 של \u0003ר' יהודה בן אגרא; האי תנא סבר\u0004 \u0005[תנא זה סבור]\u0006 כי \u0003שלים\u0004 \u0005[נשלם]\u0006 \u0003בין השמשות\u0004 לשיטת \u0003ר' יהודה\u0004"],["\u0003והדר חייל\u0004 \u0005[ו\u0006אז \u0005שב חל]\u0006 \u0003בין השמשות\u0004 של \u0003ר' יוסי,\u0004 שספק הוא, ויש לחשוש שאולי ראתה בו. \u0003והאי\u0004 \u0005[ו\u0006אילו \u0005זה]\u0006 ה\u0003תנא\u0004 האחרון \u0003סבר\u0004 \u0005[סבור]\u0006 כי \u0003בין השמשות\u0004 של \u0003ר' יוסי מישך שייך\u0004 \u0005[שייך]\u0006 הוא חלק מבין השמשות של \u0003ר' יהודה,\u0004 וכיון שבודקת כל בין השמשות הזה, הריהי איפוא גם בודקת בבין השמשות של ר' יוסי, ולכן אין מקום לחשוש בה.","ועוד בדינה של הרואה כתם, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הרואה כתם\u0004 בבגדה — \u0003מטמאה\u0004 את \u0003עצמה\u0004 בכך לענין טהרות \u0003וקדשים\u0004 שנגעה בהם \u0003למפרע,\u0004 עד לשעה שנתכבס הבגד שנמצא בו הכתם. אלו \u0003דברי רבי.\u0004","ואילו \u0003ר' שמעון בן אלעזר אומר: קדשים\u0004 שנגעה בהם — \u0003מטמאה\u0004 אותם למפרע, במציאת כתמה. ואולם את \u0003עצמה\u0004 לענין שייטמאו הטהרות שנגעה בהן עד שעת הכיבוס — \u0003אינה מטמאה.\u0004 וטעמו של דבר, משום \u0003שלא יהא\u0004 דינו של \u0003כתמה חמור מ\u0004דין \u0003ראייתה\u0004 דם. שהרי הרואה דם, מטמאה למפרע טהרות שנגעה בהן רק עד מעת לעת.","ושואלים על נימוקו זה של ר' שמעון בן אלעזר: \u0003והא מצינו\u0004 \u0005[והרי מצאנו]\u0006 שר' שמעון בן אלעזר עצמו סבור ש\u0003כתמה חמור מראייתה לענין קדשים,\u0004 שמציאת הכתם מטמאה קדשים למפרע עד שעת כיבוס הבגד, ואילו ראיית דם אינה מטמאה קדשים למפרע אלא מעת לעת בלבד!","ומתרצים: \u0003אלא תני הכי\u0004 \u0005[שנה כך]\u0006 בברייתא זו, \u0003ר' שמעון בן אלעזר אומר: אף קדשים אינה מטמאה\u0004 למפרע עד שעת הכיבוס, אלא מעת לעת בלבד. וטעם הדבר, \u0003שלא יהא\u0004 דין \u0003כתמה חמור מ\u0004דין \u0003ראתה לכל דבר.\u0004","ועוד בענין זה, \u0003תנו רבנן\u0004 \u0005[ שנו חכמים] :\u0006 \u0003ראתה כתם, ואחר כך ראתה דם,\u0004 מה דינה? — הריהי \u0003תולה\u0004 את מציאת \u0003כתמה בראייתה,\u0004 וכאילו ראתה בשעת מציאת הכתם, ודין רואה עליה, ולכן הריהי מטמאה למפרע רק מעת לעת. ובלבד, שנראה הדם בתוך \u0003מעת לעת\u0004 מזמן שמצאה את כתמה. ואולם אם בין מציאת כתמה וראייתה עבר יותר ממעת לעת — אינה תולה את הכתם בראיית הדם. אלו \u0003דברי רבי.\u0004","\u0003ר'\u0004 \u0003שמעון בן אלעזר אומר:\u0004 אינה תולה את הכתם בראיית הדם, אלא אם כן ראתה בו ב\u0003יומו,\u0004 אבל אם ראתה לאחר יום מציאת הכתם, אף שלא עבר עדיין מעת לעת ממציאת הכתם — אינה תולה את הכתם בראיית הדם, ומטמאה למפרע משעת כיבוס. \u0003אמר רבי: נראין דבריו\u0004 של ר' שמעון בן אלעזר יותר \u0003מדברי,\u0004 משום \u0003שהוא\u0004 בשיטתו \u0003מתקנה\u0004 (מקל עליה), \u0003ו\u0004אילו \u0003אני\u0004 לשיטתי \u0003מעוותה\u0004 (מחמיר עליה). וכיון, שטומאת כתם הריהי מדברי חכמים, יש ללכת בה אחר שיטת המקיל.","ותוהים על כך: וכי ר' שמעון בן אלעזר בשיטתו \u0003מתקנה?\u0004 והרי \u0003עוותי מעוית לה\u0004 \u0005[מקלקל אותה ],\u0006 שהרי אם ראתה דם לאחר יום מציאת הכתם, ובתוך מעת לעת, לשיטת ר' שמעון בן אלעזר הריהי מטמאה למפרע משעת כיבוס, ואילו לשיטת רבי במקרה זה אינה מטמאה למפרע אלא מעת לעת! \u0003אמר רבינא: איפוך\u0004 \u0005[הפוך]\u0006 את דברי רבי, שכך אמר: נראים דבריי מדברי ר' שמעון בן אלעזר, שאני מתקנה והוא מעוותה.","\u0003רב נחמן אמר: לעולם לא תיפוך\u0004 \u0005[אל תהפוך]\u0006 את דברי רבי, ומה שאמר שר' שמעון בן אלעזר בשיטתו מתקנה ואילו הוא בשיטתו מעוותה, כוונתו: \u0003שהוא\u0004 ר' שמעון בן אלעזר \u0003מתקן הלכותיה לידי זיבה.\u0004 שכן מעתה אם תראה דם ביום שלאחר מציאת הכתם, הרי מנין שבעת ימי נדותה מתחיל מזמן זה (ולא מזמן מציאת הכתם, שהרי אין הכתם תלוי בראייתה זו), ונמצא איפוא שאם תראה ביום השביעי לראייתה זו (שהוא היום השמיני למציאת הכתם) — אין היא נחשבת זבה קטנה, ויכולה היא להיטהר מטומאת נדתה.","\u0003ו\u0004אילו \u0003אני\u0004 (רבי, לשיטתי) נמצא \u0003מעוות הלכותיה לידי זיבה.\u0004 שכן במקרה זה, כיון שהכתם תולה בראיית הדם שלמחרת היום (בתוך מעת לעת), הרי איפוא בראייה שראתה ביום השמיני למציאת הכתם, הריהי זבה קטנה, ושומרת יום כנגד יום.","ועוד בדין הכתמים, \u0003בעי מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0005ר' זירא מר'\u0006 \u0003אסי:\u0004 האם דין ה\u0003כתמים\u0004 הריהו כדין ראיית דם, ו\u0003צריכין\u0004 שתבדוק עצמה ל\u0003הפסק טהרה\u0004 לפני הטבילה ביום השביעי בערב, \u0003או לא? אשתיק\u0004 \u0005[שתק],\u0006 ר' אסי \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 לר' זירא \u0003ולא מידי\u0004 \u0005[דבר].\u0006","ומסופר כי \u0003זימנין אשכחיה דיתיב וקאמר\u0004 \u0005[פעמים מצאו\u0006 ר' זירא את ר' אסי \u0005שיושב ואומר]\u0006 את דינה של הרואה כתם ואחר כך רואה דם, כי \u0003תולה\u0004 היא את \u0003כתמה בראייתה,\u0004 אם ראתה בתוך \u0003מעת לעת,\u0004 ל\u0003דברי רבי.\u0004","והוסיף ואמר שנחלקו בכך חכמים, שכן \u0003אמר ריש לקיש: והוא\u0004 (ובתנאי) \u0003שבדקה\u0004 עצמה בסוף היום השביעי למציאת הכתם. שבדיקה זו מוכיחה שאכן הכתם שייך לראיית הדם, ונוהגת איפוא ככל הפוסקת לטהרה בסוף היום השביעי. ואולם אם לא בדקה אלא בסוף היום השמיני למציאת הכתם, שהוא היום השביעי לראיית הדם, מוכיח הדבר שאין מציאת הכתם קשורה לראיית הדם. \u0003ו\u0004אילו \u0003ר' יוחנן אמר:\u0004 מציאת הכתם קשורה לראיית הדם, בכל אופן שבו נהגה האשה בבדיקתה. ולכן \u0003אף על פי שלא בדקה\u0004 בסוף היום השביעי למציאת הכתם, אלא בסוף היום השביעי לראיית הדם, עדיין מציאת הכתם קשורה לראיית הדם.","כששמע כן ר' זירא \u0003אמר ליה\u0004 \u0005[לו]\u0006 לר' אסי: האם \u0003מכלל\u0004 הדברים האלו יש להסיק כי \u0003כתמים צריכין הפסקת טהרה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 שאלו: \u0003והא זימנין סגיאין בעא מינך\u0004 \u0005[והרי פעמים רבות שאלתי אותך]\u0006 האם כתמים צריכים הפסק, \u0003ולא אמרת ולא מידי\u0004 \u0005[דבר],\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003אגב שיטפך אתיא\u0004 \u0005[שטף\u0006 לימודך באה נזכרה\u0005]\u0006 \u0003לך\u0004 הלכה זו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003אגב שיטפאי אתיא\u0004 \u0005[שטף\u0006 לימודי \u0005באה]\u0006 \u0003לי\u0004 הלכה זו.","אשה \u0003הרואה\u0004 דם ביום האחרון של ימי הזיבה, שהוא ה\u0003יום\u0004 ה\u0003אחד עשר, בין השמשות,\u0004 כיון שספק אם ראייה זו נחשבת כשל יום זה ובתוך ימי זיבה ראתה או של הלילה ובתוך ימי נידה ראתה — ראייה זו נחשבת מספק כ\u0003תחלת נדה\u0004 (שמא ראיית לילה היא), וטמאה מעתה שבעת ימים, \u0003ו\u0004כ\u0003סוף נדה.\u0004 \u0003תחלת זיבה וסוף זיבה\u0004 (ואם ראתה עוד יומיים הריהי זבה גמורה וצריכה לספור שבעה נקיים).","ובדומה לכך, הרואה דם בין השמשות של \u0003יום\u0004 ה\u0003ארבעים\u0004 \u0003ל\u0004לידת \u0003זכר,\u0004 שהוא היום האחרון לימי טהרת היולדת זכר, שאם ראתה בימי טהרתה — אינה נטמאת בכך. ומעתה, אם נחשבת ראייה זו כראיית יום — אינה נטמאת. ואם נחשבת היא כראיית לילה — הריהי נטמאת. \u0003ו\u0004כן הרואה בין השמשות של \u0003יום\u0004 ה\u0003שמונים ל\u0004לידת \u0003נקבה,\u0004 שהוא היום האחרון לימי טהרת היולדת נקבה. שדין הראייה \u0003בין השמשות לכולן,\u0004 כל אלה — \u0003הרי אלו טועות\u0004 בדעתן, שמסופקות הן, ואף הקרבן שהן מביאות, כיון שבא על הספק, אינו נאכל.","\u0003אמר ר'\u0004 \u0003יהושע: עד שאתם מתקנים את השוטות\u0004 (הטועות) מחמת הספק, \u0003באו ותקנו את הפקחות\u0004 (היודעות בוודאות) זמן ראייתן, שאף הן נצרכות לתיקון מחמת רוב ראיות שרואות.","שנינו במשנתנו כי הרואה דם בבין השמשות של היום האחד עשר לימי זיבתה, שראייה זו נחשבת \u0003תחלת נדה וסוף נדה.\u0004 ותוהים על כך: והרי אין החשש בראייה זו אלא ש\u0003תחלת נדה\u0004 היא (אם נחשב זמן בין השמשות ללילה) \u0003וסוף זיבה היא\u0004 (אם נחשב זמן בין השמשות ליום)!","\u0003אמר רב חסדא:\u0004 \u0003הכי קאמר\u0004 \u0005[כך הוא\u0006 התנא \u0005אומר]:\u0006 \u0003הרואה יום אחד עשר בין השמשות\u0004 — יש לחשוש בה גם ש\u0003תחילת נדה\u0004 היא \u0003ו\u0004גם ש\u0003סוף זיבה\u0004 היא, ולכן אם ראתה גם בתשיעי ובעשירי קודם לכן — הריהי זבה מספק.","וכן בהמשך דברי המשנה \"תחילת זיבה וסוף זיבה\", כך אומר התנא: \u0003ו\u0004הרואה בין השמשות \u0003בשביעי לנדתה\u0004 — יש לחשוש בה ש\u0003סוף נדה\u0004 היא \u0003ותחלת זיבה\u0004 היא.","שנינו במשנתנו ש\u0003אמר ר'\u0004 \u0003יהושע\u0004 לחכמים: \u0003עד שאתם מתקנין את השוטות,\u0004 באו ותקנו את הפקחות. ושואלים על כך: וכי \u0003הני\u0004 \u0005[אלו]\u0006 הרואות בין השמשות,"],["\u0003שוטות נינהו\u0004 \u0005[הן]?\u0006 הלא כיון שמסופקות הן בדינן \u0003טועות נינהו\u0004 \u0005[הן]!\u0006 ומתקנים את הלשון: \u0003אלא\u0004 אכן \u0003תני\u0004 \u0005[שנה]\u0006 כך במשנה בדברי ר' יהושע: \"עד שאתם מתקנים את ה\u0003טועות\u0004 באו ותקנו את הפקחות\".","\u0003דתניא\u0004 \u0005[ ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בענין \"פקחות\" אלה: אשה שכל ימיה ערוכים באופן כזה שבכל שני ימים, \u0003יום אחד טמא,\u0004 שרואה בו \u0003ויום אחד טהור\u0004 שאינה רואה בו, מה תקנתה לשמש עם בעלה? — הריהי \u0003משמשת\u0004 עם בעלה בליל היום ה\u0003שמיני\u0004 מהיום שבו ראתה לראשונה. שהרי טהורה היא, שכן טבלה וטהרה עצמה ביום השביעי בערב. ויש לפניה מעתה גם כל היום השמיני \u0003ולילו\u0004 (הלילה שאחריו) \u0003עמו\u0004 לשמש עם בעלה, שהרי לא תראה אלא ביומו של היום התשיעי.","\u0003ו\u0004כן עוד \u0003ארבעה לילות מתוך\u0004 מחזור הימים של \u0003שמונה עשר יום\u0004 (שבעת ימי נדה, ואחד עשר ימי זיבה). \u0003ו\u0004אולם \u0003אם היתה רואה\u0004 לא ביום אלא \u0003מבערב\u0004 — \u0003אינה משמשת\u0004 עם בעלה \u0003אלא\u0004 בליל היום ה\u0003שמיני\u0004 וביומו \u0003בלבד.\u0004","ואם היתה אשה זו רואה באופן שבכל ארבעה ימים, \u0003שני ימים\u0004 הריהם \u0003טמאין ושני ימים טהורין\u0004 — \u0003משמשת\u0004 ביום ה\u0003שמיני\u0004 (לילה ויום), \u0003ו\u0004ביום ה\u0003שנים עשר, ו\u0004ביום ה\u0003ששה עשר, ו\u0004ביום ה\u0003עשרים.\u0004","ושואלים על כך: \u0003ותשמש נמי בתשסר\u0004 \u0005גם כן ב\u0006יום תשעה עשר], שהרי כיון שכבר חלפו אחד עשר ימי הזיבה (בסוף היום השמונה עשר), שוב אין לה דין שימור? \u0003אמר רב ששת: זאת אומרת,\u0004 שהביטוי \u0003\"גרגרן\"\u0004 (זללן) \u0003דתנן\u0004 \u0005[ ששנינו]\u0006 במשנה להלן, ככינויו של המתאווה לבעול אף את זו שראתה ביום האחד עשר לימי זיבתה, וטבלה למחרת — מורה ש\u0003אסור\u0004 הדבר מן הדין.","\u0003רב אשי אמר:\u0004 אין האשה אסורה לשמש עם בעלה ביום השנים עשר לימי זיבתה, אף לא מדברי חכמים, שכן אינה צריכה לשמור את היום שלמחרת היום האחד עשר לימי זיבה, שכן הוא היום הראשון מימי נדותה. ואולם \u0003נהי\u0004 \u0005[הגם]\u0006 שביום \u0003חד\u0004 \u0005[אחד]\u0006 \u0003עשר לא בעי\u0004 \u0005[צריך]\u0006 \u0003שימור,\u0004 ביום \u0003עשירי מיהא בעי\u0004 \u0005[על כל פנים צריך]\u0006 \u0003שימור.\u0004","ודנים עוד: אשה שכל ימיה רואה \u0003שלשה ימים טמאין ושלשה ימים טהורין\u0004 — \u0003משמשת שני ימים, ושוב אינה משמשת לעולם.\u0004 שכן משיצא היום השביעי לנדתה, שוב אינה יכולה להיטהר, שהרי היום השמיני הוא היום השני מתוך שלושת הימים שבהם היא רואה. וראיית היום השמיני והיום התשיעי היא ראיית זיבה. ויוצא איפוא שאין לה מועד להיטהר אלא בליל היום האחד עשר ולשמש עם בעלה בכל היום האחד עשר ולמחרת ביום השנים עשר (ואלו שני הימים בלבד שמותרת לשמש עם בעלה). ואולם מכאן והלאה כשתראה שלושה ימים — הריהי נחשבת זבה גדולה. וכדי להיטהר מזבה, נזקקת היא לספירת שבעה ימים נקיים, ואילו זו אינה רואה יותר משלושה ימים נקיים.","היתה אשה זו רואה תמיד \u0003ארבעה ימים טמאים, וארבעה ימים טהורין\u0004 — \u0003משמשת\u0004 עם בעלה \u0003יום אחד\u0004 בלבד, \u0003ושוב אינה משמשת לעולם.\u0004","היתה רואה \u0003חמשה ימים טמאים, וחמשה ימים טהורין\u0004 — הרי זו \u0003משמשת שלשה ימים, ושוב אינה משמשת לעולם.\u0004 היתה רואה \u0003ששה ימים טמאין וששה ימים טהורין\u0004 — הרי זו \u0003משמשת חמשה ימים, ושוב אינה משמשת לעולם.\u0004","היתה רואה \u0003שבעה ימים טמאין ושבעה ימים טהורין\u0004 — \u0003משמשת רביע ימיה, מתוך עשרים ושמונה ימים.\u0004","היתה רואה \u0003שמונה ימים טמאין ושמונה ימים טהורין\u0004 — \u0003משמשת חמשה עשר יום מתוך ארבעים ושמונה.\u0004 ושואלים: ואיך תשמש ביום הארבעים ושמונה, והרי שמונת הימים החמישיים, ארבעה מהם הם ימי זיבה וארבעה הם ימי נדה. והשמונה שאחריהם, שלושה מהם הם בימי נדה וחמישה בימי זיבה. והשלושה הראשונים אינם יכולים לעלות לה לימי ספירת זיבתה, שהרי אין ימי נדה עולים לספירתה. שאף שאינה נדה, שהרי אינה חוזרת לפתח נדתה עד שתספור שבעה נקיים, מכל מקום כיון שהם ימים הראויים לימי נדה, אינם עולים לספירת זיבתה.","\u0003הרי ארביסר הוו\u0004 \u0005[ארבעה עשר הם]!\u0006","\u0003אמר רב אדא בר יצחק, זאת אומרת: ימי נדתה שאין רואה בהן\u0004 — \u0003עולין\u0004 (נחשבים) \u0003לספירת\u0004 שבעה ימי טהרה מטומאת \u0003זיבתה.\u0004 ולכן, אף שמנין שבעת ימי הנקיות מתחילים ביום החמישי לנדתה, יכולה היא למנות שבעה נקיים מהיום השישי לנדה, ולהיטהר ביום השמיני. \u0003דאיבעיא להו\u0004 \u0005[ש\u0006כן \u0005נשאלה להם,\u0006 לחכמים\u0005]:\u0006"],["האשה שילדה כשהיא זבה, ובאופן שלאחר הלידה במשך \u0003ימי\u0004 טומאת \u0003לידה\u0004 (שבעה ימים ליולדת זכר, ושבועיים ליולדת נקבה, שהיולדת טמאה בהם, אף אם לא ראתה דם) \u0003אינה רואה בהן, מהו\u0004 דינה לענין \u0003שיעלו\u0004 (שייחשבו) הימים הללו \u0003לספירת\u0004 שבעת ימי נקיות מטומאת \u0003זיבתה?\u0004","\u0003אמר רב כהנא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו: \u0003ראתה שנים\u0004 (יומיים) בתוך אחד עשר ימי זיבתה, \u0003ול\u0004יום ה\u0003שלישי הפילה, ואינה יודעת מה\u0004 \u0003הפילה,\u0004 אם היה זה נפל והריהי טמאה טומאת לידה, או רוח סתם ואינה טמאה טומאת לידה —","\u0003הרי זו ספק זיבה ספק לידה.\u0004","ולכך \u0003מביאה קרבן,\u0004 וקרבן זה הריהו ספק קרבן יולדת, ספק קרבן זבה, ספק חולין. \u0003ו\u0004משום כך \u0003אינו נאכל.\u0004 \u0003וימי לידתה\u0004 (אף שספק אם היתה זו לידה) \u0003שאין רואה בהן\u0004 — \u0003עולין לה לספירת זיבתה.\u0004 הרי זו איפוא פתרון לשאלת חכמים, שימי טומאת לידה שלא ראתה בהם, נחשבים כימי ספירת נקיים של זבה.","\u0003אמר רב פפא:\u0004 אין זו הוכחה שכן \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003כיון דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 ש\u0003יולדת זכר היא, וכל הני\u0004 \u0005[אלו]\u0006 ה\u0003שבעה\u0004 ימים \u0003יתירי דקיהבינן\u0004 \u0005[יתרים שאנו נותנים]\u0006 \u0003לה\u0004 משום הספק שמא ילדה נקבה, ונזקקת לטומאת ארבעה עשר יום — \u0003סלקי\u0004 \u0005[עולים]\u0006 \u0003לה לספירת זיבתה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: ביולדת זכר איכא לספוקי\u0004 \u0005[יש\u0006 מקום \u0005להסתפק],\u0006 \u0003ביולדת נקבה ליכא לספוקי\u0004 \u0005[אין\u0006 מקום \u0005להסתפק]?\u0006 ובכל זאת, אומרים אנו, שעולים לה הימים הללו שלא ראתה בהם, אף שאולי יולדת נקבה היתה! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תשמע מכאן]\u0006 כי \u0003עולין!\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[תשמע מכאן]\u0006 שכך הוא.","וממשיכים בדברי הברייתא. האשה הרואה בקביעות \u0003תשעה ימים טמאין ותשעה ימים טהורין\u0004 — \u0003משמשת\u0004 עם בעלה \u0003שמונה ימים מתוך שמונה עשר.\u0004","הרואה \u0003עשרה ימים טמאין ועשרה ימים טהורים\u0004 — \u0003ימי שמושה כימי זיבתה.\u0004 \u0003וכן למאה וכן לאלף.\u0004 \u0003דם הנדה ו\u0004כן כזית מ\u0003בשר המת\u0004 — \u0003מטמאין\u0004 במגע ובמשא כשהם \u0003לחין\u0004 \u0003ומטמאין\u0004 כשהם \u0003יבשין.\u0004 \u0003אבל הזוב\u0004 (טיפות הזוב היוצאות מן הזב), \u0003והניע\u0004 (הליחה המצויה באף או בפה) \u0003והרוק\u0004 היוצאים מהזב. \u0003והשרץ\u0004 המת, \u0003ו\u0004בשר \u0003הנבלה, והשכבת זרע\u0004 — כל אלה \u0003מטמאין\u0004 רק כשהם \u0003לחין, ואין מטמאין\u0004 כשהם \u0003יבשין.\u0004 \u0003ו\u0004אולם \u0003אם יכולין להשרות\u0004 את היבשים במים, \u0003ו\u0004על ידי כך \u0003לחזור\u0004 להיות \u0003לכמות שהן\u0004 בתחילה — הריהם \u0003מטמאין לחין ומטמאין יבשין.\u0004 \u0003ו\u0004מסבירים: \u0003כמה\u0004 זמן \u0003היא שרייתן\u0004 במים, שעל פיה ייקבע אם יחזרו להיות לחים ומטמאים? \u0003ב\u0004מים \u0003פושרין,\u0004 בפרק זמן של \u0003מעת לעת\u0004 (יממה). \u0003ר' יוסי אומר: בשר המת יבש, ואינו יכול להשרות\u0004 אותו \u0003ולחזור\u0004 על ידי כך \u0003לכמות שהיה\u0004 — הריהו \u0003טהור\u0004 מלטמא בטומאת המת בשיעור כזית. ואולם הריהו מטמא טומאת רקב כמלוא תרווד.","","","","שנינו במשנתנו כי דם הנדה מטמא במגע ובמשא הן כשהוא לח והן כשהוא יבש. ומבררים הלכה זו, ותחילה באשר לעצם טומאת דם הנדה: \u0003מנא הני מילי\u0004 \u0005[מנין אלו הדברים]?\u0006 \u0003אמר חזקיה:\u0004 שכך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדינה של הנדה \u0003\"והדוה בנדתה\"\u0004 (ויקרא טו, לג) — השווה הכתוב את דין הדבר הזב מן הנדה (\"דוה\") לדין הנדה עצמה, שיהא דין ה\u0003מדוה\u0004 (דם הנדה) \u0003כמותה: מה היא\u0004 עצמה \u0003מטמאה\u0004 במגע ובמשא. \u0003אף\u0004 ה\u0003מדוה מטמאה\u0004 במגע ובמשא.","ומבררים עוד: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 מכאן מקור לטומאת דם הנדה ה\u0003לח\u0004 (\"הדוה\" = הדבר הזב), ואולם דם הנדה ה\u0003יבש מנלן\u0004 \u0005[מנין לנו]\u0006 שאף הוא מטמא? \u0003אמר ר'\u0004 \u0003יצחק:\u0004 שכך \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בטומאת הנדה \"דם \u0003יהיה\u0004 זובה בבשרה\" (שם, יט) — והרי זה מורה: דם זה \u0003בהויתו יהא,\u0004 שאף שהוא יבש, הריהו מטמא, וכדם הלח.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003ב\u0004דם שהיה בתחילתו \u0003לח ונעשה\u0004 אחר כך \u0003יבש,\u0004 שבכגון זה הריהו כבתחילתו, ומטמא. ואולם הדם שהיה \u0003יבש מעיקרו, מנלן\u0004 \u0005[מנין לנו]\u0006 שהריהו מטמא? \u0003ותו, הא דתנן\u0004 \u0005[ועוד, זה ששנינו\u0006 במסכתנו בתחילת פרק \"המפלת\"\u0005]:\u0006 \u0003המפלת כמין קליפה,\u0004 או \u0003כמין עפר, כמין שערה, כמין יבחושין\u0004 (יתושים) \u0003אדומים\u0004 — \u0003תטיל\u0004 אותן חתיכות \u0003למים, אם נמוחו\u0004 במים — הרי זה דם \u0003טמא, מנלן\u0004 \u0005[מנין לנו]\u0006 שאף דם כזה מטמא? ומשיבים: הכתוב \u0003\"יהיה\"\u0004 — \u0003רבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 המלמד שבכל האופנים הללו מטמא הדם בנדה.","ושואלים על לימוד זה: \u0003אי\u0004 \u0005[אם]\u0006 כן, נוסיף ונלמד מאותה דרשה: \u0003מה היא\u0004 הזבה — \u0003עושה\u0004 (מטמאת) \u0003משכב ומושב לטמא אדם ולטמא בגדים\u0004 שעליו, אף שלא נגע בהם המשכב, כדין אב הטומאה. ומעתה נאמר ש\u0003אף דמה נמי\u0004 \u0005[גם כן]\u0006 \u0003עושה משכב ומושב,\u0004 כאב הטומאה, \u0003לטמא אדם ולטמא בגדים?\u0004 ומשיבים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003דמה בר\u0004 \u0005[בן]\u0006 \u0003משכב ומושב הוא?!\u0004 ולכך אין מקום לומר שיטמא טומאת משכב ומושב.","ושואלים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 זו, שאין טומאת משכב ומושב נוהגת אלא בדבר שהוא בן משכב ומושב — מעתה, \u0003אבן\u0004 ה\u0003מנוגעת\u0004 (בנגע הצרעת), וכי \u0003בת משכב ומושב היא, דאיצטריך קרא למעוטי\u0004 \u0005[שהוצרך הכתוב למעט]\u0006 שאינה מטמאת טומאת משכב ומושב? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול תהא אבן מנוגעת עושה משכב ומושב, לטמא אדם לטמא בגדים? ו\u0004יש מקום לומר כן, שהרי","\u0003דין\u0004 (קל וחומר) \u0003הוא:\u0004 \u0003ומה זב,\u0004 הקל בדינו, \u0003ש\u0004כן \u0003אינו מטמא בביאה\u0004 (שאין אדם הנכנס לבית עם זב, נטמא בכך) — הריהו \u0003עושה משכב ומושב\u0004 \u0003לטמא אדם לטמא בגדים.\u0004 \u0003אבן מנוגעת,\u0004 שהיא חמורה, \u0003ש\u0004כן היא \u0003מטמאה בביאה\u0004 (שאדם הנכנס לבית שנמצאת בו, נטמא בכך) — \u0003אינו דין ש\u0004תהא \u0003מטמאה משכב ומושב לטמא אדם לטמא בגדים!\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) בדין טומאת משכב ומושב \"כל המשכב אשר ישכב עליו \u0003הזב\u0004 יטמא\" (ויקרא טו, ד). ובאה המלה היתירה הזב להורות: דווקא \u0003הזב\u0004 הוא המטמא בטומאת משכב ומושב, \u0003ולא אבן מנוגעת.\u0004 ונדייק מכאן: \u0003טעמא דמעטיה קרא\u0004 \u0005[הטעם\u0006 שאין אבן המנוגעת מטמאת משכב ומושב הוא משום \u0005שמיעטה הכתוב],\u0006 ומכאן נסיק: \u0003הא לאו הכי\u0004 \u0005[הרי\u0006 ש\u0005בלא כך]\u0006 הריהי \u0003מטמאה,\u0004 אף שאין היא בת משכב ומושב!","","ומשיבים: \u0003ומינה\u0004 \u0005[וממנה]\u0006 מאותה דרך דרשה נלמד גם שאין דם הנדה עושה משכב ומושב, \u0003לאו מי אמרת\u0004 \u0005[האם לא אמרת]\u0006 שיש לדרוש מן הכתוב \u0003\"הזב\"\u0004 — \u0003ולא אבן מנוגעת, הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"ואם על המשכב הוא או על הכלי \u0003אשר היא יושבת עליו\u0004 בנוגעו בו יטמא עד הערב\" (שם, כג) — הרי זה בא למעט: דווקא \u0003היא, ולא דמה.\u0004"],["ומוסיפים ודנים: \u0003אי\u0004 \u0005[אם]\u0006 כדבריך שהשווה הכתוב \"דם יהיה זובה\" (ויקרא טו,יט) את דין הנדה לדין דמה, מעתה נאמר \u0003מה היא,\u0004 הנדה, \u0003מטמאה ב\u0004טומאת \u0003אבן מסמא\u0004 (שנטמאים בה הכלים הנמצאים מתחת לאבן גדולה עליה נישאת הנדה), \u0003אף מדוה\u0004 (דם נדתה) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מטמאה באבן מסמא\u0004 שעליה נתון דם הנדה?","\u0003אמר רב אשי\u0004 בתשובה: אפשר היה לומר כן, ואולם \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין משכב הזב \u0003\"והנושא אותם\u0004 יכבס בגדיו ורחץ במים וטמא עד הערב\" (ויקרא טו, י) — הרי הלשון \u0003\"אותם\",\u0004 לשון \u0003מיעוטא\u0004 \u0005[מיעוט]\u0006 \u0003הוא,\u0004 וללמדנו כי דווקא אלה מטמאים באבן מסמא, ולא דם הנדה.","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003בשר המת\u0004 מטמא בין כשהוא לח ובין כשהוא יבש. ודנים בדבר: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא הדין? \u0003אמר ריש לקיש\u0004 בתשובה: שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \"או איש אשר יגע... באדם אשר יטמא לו \u0003לכל טמאתו\"\u0004 (ויקרא כב, ה), ו\"לכל\" הריהו לשון ריבוי, \u0003ל\u0004למדנו שכן הוא ב\u0003כל טומאות הפורשות ממנו,\u0004 בין כלח ובין כיבש.","ואילו \u0003ר' יוחנן אמר:\u0004 המקור לדין זה הוא \"וכל אשר יגע על פני השדה בחלל חרב או במת \u0003או בעצם אדם או בקבר\u0004 יטמא שבעת ימים\" (במדבר יט, טז). שבא הכתוב \"בעצם אדם\" ללמדנו כי דין ה\u0003אדם\u0004 המטמא בטומאת מת הריהו \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003עצם.\u0004 ומכאן: \u0003מה עצם\u0004 — הריהו \u0003יבש, אף כאן\u0004 — המת מטמא אף ב\u0003יבש,\u0004 ולא רק בלח.","ומבררים: \u0003מאי בינייהו\u0004 \u0005[מה,\u0006 איזה הבדל הלכתי יש \u0005ביניהם,\u0006 בין הסברו של ריש לקיש והסברו של ר' יוחנן\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל בדינו של בשר מן המת, כאשר התייבש עד \u0003דאפריך אפרוכי\u0004 \u0005[ש\u0006הוא נפרך]. שכן לדעת ריש לקיש הריהו טמא (שאף באופן זה התרבה מן הכתוב \"לכל טומאתו\"), ואילו לדעת ר' יוחנן הריהו טהור (שכן אינו דומה לעצם).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שיטת ריש לקיש ממה ששנינו כי \u0003בשר המת שהופרך\u0004 — הריהו \u0003טהור!\u0004 ומתרצים: אין זו קושיה, שכן \u0003התם\u0004 \u0005[שם]\u0006 מדובר באופן שיבש כל כך, עד \u0003דאקמח והוי עפרא\u0004 \u0005[שנהיה לקמח, והריהו עפר].\u0006","ועוד \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003כל שב\u0004גוף ה\u0003מת\u0004 הריהו \u0003מטמא, חוץ מן השינים, והשער, והצפורן.\u0004 וזהו דווקא כשהשינים או השיער והציפורן נפרדו מגוף המת, \u0003ו\u0004אולם \u0003בשעת חבורן\u0004 — \u0003הכל טמא.\u0004 והרי זו קושיה הן לר' יוחנן (שהרי אף השינים הריהן כעצם, ומדוע אינן מטמאות) והן לריש לקיש (מדוע לא התרבו אף אלה מן הכתוב \"לכל טומאתו\")!","\u0003אמר רב אדא בר אהבה\u0004 בתשובה: אין מטמא בטומאת מת אלא הדבר שהוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003עצם, מה עצם\u0004 — הריהי דבר \u0003שנברא עמו,\u0004 עם לידתו של האדם. \u0003אף כל\u0004 שמטמא בטומאת מת — הריהו דבר \u0003שנברא עמו,\u0004 ואלה לא נבראו עם לידתו של האדם. ומקשים על הסבר זה: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003שער וצפורן, שנבראו עמו\u0004 עם לידתו — \u0003ו\u0004בכל זאת הריהם \u0003טהורין\u0004 (אינם נטמאים בטומאת מת)!","\u0003אלא אמר רב אדא בר אהבה\u0004 \u0003הסבר שונה: אין מטמא בטומאת מת אלא הדבר שהוא\u0004 \u0005[בדומה]\u0006 ל\u0003עצם, מה עצם\u0004 — הריהו דבר \u0003שנברא עמו\u0004 בלידתו, \u0003ו\u0004מאז שוב \u0003אין גזעו\u0004 (עיקרו) \u0003מחליף, אף כל\u0004 שמטמא בטומאת מת — הריהו דבר \u0003שנברא עמו, ואין גזעו מחליף.\u0004 \u0003יצאו\u0004 מכלל זה \u0003השינים\u0004 — \u0003שלא נבראו עמו\u0004 בלידתו. וכמו כן \u0003יצאו\u0004 מכלל זה ה\u0003שער ו\u0004ה\u0003צפורן\u0004 — \u0003שאף על פי שנבראו עמו\u0004 בשעת לידתו, ואולם \u0003גזעו מחליף.\u0004","ומקשים על הסבר זה: \u0003והרי עור,\u0004 ש\u0003גזעו\u0004 \u0003מחליף,\u0004 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 ש\u0003הגלודה\u0004 (בהמה שנקלף כל עורה מעליה), ר' מאיר \u0003מכשיר\u0004 אותה באכילה, שאינה נעשית טריפה בכך, כיון שבמקום עור זה שנגלד, יצמח עור חדש. \u0003ו\u0004אילו \u0003חכמים פוסלין\u0004 אותה כטריפה. \u0003ו\u0004אולם \u0003אפילו רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא קפסלי\u0004 \u0005[אינם פוסלים]\u0006 אותה, \u0003אלא\u0004 משום \u0003דאדהכי והכי שליט\u0004 \u0005[שבין כה וכה,\u0006 בפרק הזמן שבין ירידת העור הקודם וצמיחת העור החדש, \u0005שולט]\u0006 \u0003בה אוירא\u0004 \u0005[אויר]\u0006 \u0003ו\u0004כתוצאה מכך הריהי \u0003מתה.\u0004 \u0003ו\u0004אולם אף לדעת חכמים \u0003לעולם גזעו מחליף.\u0004 \u0003ו\u0004בכל זאת \u0003תנינן\u0004 \u0005[שונים אנו]\u0006 \u0003אלו\u0004 הם \u0003שעורותיהם\u0004 נחשבים \u0003כבשרן\u0004 לענין הטומאה, ובכלל אלה \u0003עור האדם,\u0004 אף שהעור גזעו מחליף!","ומתרצים: \u0003הא איתמר עלה\u0004 \u0005[הרי\u0006 כבר \u0005נאמרו\u0006 דברים \u0005עליה,\u0006 על הלכה זו\u0005],\u0006 שכך \u0003אמר עולא\u0004 בהסבר הלכה זו: \u0003דבר\u0004 (מדין) \u0003תורה\u0004 — \u0003עור אדם\u0004 הריהו \u0003טהור, ומאי טעמא\u0004 \u0005[ומה טעם]\u0006 \u0003אמרו\u0004 חכמים כי הריהו \u0003טמא\u0004 — \u0003גזרה שמא יעשה אדם\u0004 מן ה\u0003עורות\u0004 שמגופותיהם של \u0003אביו ואמו שטיחין לחמור.\u0004 ולכן גזרו בכך טומאה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 את מהלך הסוגיה באופן שונה, שכך הקשו: \u0003הרי עור,\u0004 שאין \u0003גזעו מחליף, ו\u0004מנין לנו שהוא כך, שכן \u0003תנן\u0004 \u0005[שנינו]\u0006 שנחלקו חכמים בדין הבהמה שנגלד עורה אם היא טריפה, ואסורה באכילה. \u0003וחכמים פוסלין\u0004 אותה, ומטעם שאין עתיד לצמוח עור חדש במקום העור שנקלף. \u0003ואפילו ר' מאיר\u0004 המכשירה — \u0003לא קא מכשר\u0004 \u0005[אין הוא מכשיר]\u0006 \u0003אלא\u0004 משום \u0003דקריר בשרא, וחייא\u0004 \u0005[שמתקרר הבשר, ונרפא],\u0006 \u0003ו\u0004אולם אף לדעתו \u0003לעולם\u0004 העור \u0003אין גזעו מחליף.\u0004 \u0003ו\u0004בכל זאת \u0003אמר עולא דבר\u0004 (מדין) \u0003תורה\u0004 — \u0003עור אדם טהור\u0004 (אינו מטמא). ומדוע לדעתו אינו מטמא, והרי גזעו אינו מחליף!","ומשיבים: \u0003כי איתמר\u0004 \u0005[כאשר נאמרו]\u0006 דברי \u0003עולא\u0004 — לא נאמרו על ראשית הדברים (\"אלו שעורותיהן כבשרן, עור אדם\"), אלא \u0003אסיפא איתמר\u0004 \u0005[על סוף\u0006 הדברים הם \u0005נאמרו],\u0006 ששנינו בהמשך \u0003\"וכולן\u0004 (כל העורות המטמאים) \u0003שעבדן\u0004 כדרך הבורסקאים, \u0003או שהילך בהן\u0004 (עליהם) \u0003כדי עבודה\u0004 וכדרך המקובלת בעיבוד עורות — הרי אלה \u0003טהורין\u0004 (שאין הם מטמאים), \u0003חוץ מעור אדם.\u0004 \u0003ו\u0004על כך \u0003אמר עולא: דבר תורה\u0004 — אף \u0003עור אדם, כי\u0004 \u0005[כאשר]\u0006 \u0003עבדו\u0004 הריהו \u0003טהור, ומה טעם אמרו\u0004 חכמים \u0003טמא\u0004 — \u0003גזרה שמא יעשה אדם עור אביו ואמו שטיחין.\u0004","ושואלים עוד: \u0003והרי בשר,\u0004 ש\u0003גזעו מחליף, ו\u0004עם זאת, דינו שהריהו \u0003טמא\u0004 (מטמא)! \u0003אמר מר בר רב אשי\u0004 בתשובה: אין הבשר נחשב כדבר שגזעו מחליף, שכן אף שבא בשר חדש במקום ה\u0003בשר\u0004 שנלקח מהגוף, מכל מקום \u0003נעשה מקומו צלקת.\u0004","שנינו במשנתנו כי דם הנדה ובשר המת מטמאים כשהם לחים ומטמאים אף כשהם יבשים, \u0003אבל הזוב\u0004 (וכמותו גם הניע והרוק, ושאר דברים המנויים במשנתנו) מטמא כשהוא לח ואינו מטמא יבש. ומבררים: ה\u0003זוב, מנלן\u0004 \u0005[מנין לנו]\u0006 שהוא עצמו מטמא? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 במה שנאמר בפרשת הזב \"איש איש כי יהיה זב מבשרו \u0003זובו טמא\u0004 הוא\" (ויקרא טו, ב), \u0003לימד על הזוב\u0004 עצמו \u0003שהוא טמא,\u0004 ולא רק האדם הזב.","ויש לשאול מדוע נזקקים אנו ללימוד מיוחד, \u0003והלא דין\u0004 (קל וחומר) \u0003הוא:\u0004 מאחר ש\u0003לאחרים\u0004 (לאדם שיצא ממנו הזוב) — הריהו \u0003גורם טומאה, לעצמו\u0004 — \u0003לא כל שכן\u0004 שהריהו טמא! ואולם דינו של \u0003שעיר המשתלח\u0004 ביום הכיפורים \u0003יוכיח\u0004 שאין זו הוכחה. \u0003ש\u0004הרי השעיר המשתלח לעזאזל ביום הכיפורים \u0003גורם טומאה לאחרים\u0004 (לאדם המשלחו), \u0003ו\u0004אילו \u0003הוא עצמו\u0004 (השעיר) \u0003טהור.\u0004 ומעתה, \u0003אף אתה אל תתמה על זה,\u0004 על הזוב, \u0003שאף על פי שגורם טומאה לאחרים\u0004 — מכל מקום אפשר שיהא \u0003הוא עצמו טהור.\u0004 לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \u0003\"זובו טמא\u0004 הוא\" — \u0003לימד על הזוב\u0004 עצמו \u0003שהוא טמא.\u0004","\u0003ו\u0004עדיין \u0003אימא\u0004 \u0005[אמור]\u0006 מתוך דרשה זו, כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003ב\u0004טומאת \u0003מגע,\u0004 שהזוב מטמא במגע, \u0003אבל ב\u0004טומאת \u0003משא\u0004 — \u0003לא\u0004 מטמא, \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 בטומאת ה\u0003שרץ\u0004 שמטמא במגע ולא במשא! \u0003אמר רב ביבי בר אביי:\u0004 אין לומר כן, כי לענין טומאה \u0003במגע לא איצטריך קרא\u0004 \u0005[לא נצרך כתוב]\u0006 להשמיענו כן, \u0003דלא גרע\u0004 \u0005[ש\u0006הרי \u0005אין\u0006 הזוב \u0005גרוע,\u0006 פחות] \u0003משכבת זרע\u0004 המטמאת במגע."],["ואולם \u0003כי איצטריך קרא\u0004 \u0005[כאשר נצרך הכתוב]\u0006 לדרשה זו, הרי זה \u0003ל\u0004ענין טומאת הזוב ב\u0003משא.\u0004 ושואלים עוד: עדיין יש לדון בטומאת הזוב עצמו, כי \u0003אימא\u0004 \u0005[אמור]\u0006 מתוך דרשה זו, שאכן \u0003במשא,\u0004 הריהו \u0003מטמא\u0004 את ה\u0003אדם\u0004 הנושא אותו, \u0003ו\u0004כמו כן את \u0003בגדים\u0004 שעליו. \u0003ו\u0004אולם \u0003במגע\u0004 — את ה\u0003אדם\u0004 הנוגע בו הריהו \u0003מטמא,\u0004 ואולם את ה\u0003בגדים\u0004 שעליו — \u0003לא לטמא\u0004 \u0005[אינו מטמא].\u0006 והרי זה \u0003מידי דהוה\u0004 \u0005[כמו שהוא]\u0006 בטומאת \u0003מגע נבלה\u0004 המטמאת את האדם הנוגע בה, ולא את הבגדים שעליו. אף שבמשא הריהי מטמאת את האדם ואת הבגדים!","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[אין להעלות על הדעת]\u0006 הצעה שכזו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005],\u0006 \u0003אחרים אומרים\u0004 כי הכתוב החותם את פרשת הטומאות \"ו \u0003הזב את זובו לזכר ולנקבה\"\u0004 (ויקרא טו, לג) \u0003מקיש\u0004 (משווה) את דין \u0003זובו\u0004 של האדם \u0003לו,\u0004 לדינו של הזב עצמו. \u0003מה הוא\u0004 בטומאת הזב, \u0003לא חלקת בין מגעו למשאו\u0004 — שדין שניהם \u0003לטמא אדם\u0004 הנוגע והנושא \u0003ולטמא בגדים\u0004 שעליהם, \u0003אף\u0004 בטומאת \u0003זובו כן\u0004 הוא, שמטמאת אדם ובגדים, הן במגע והן במשא.","ושואלים: \u0003והשתא דנפקא לן\u0004 \u0005[ועכשיו, שיוצא לנו,\u0006 שנלמד\u0005]\u0006 דין טומאת הזוב \u0003מ\u0004ההיקש שבכתוב \u0003\"הזב את זובו\",\u0004 אם כן הכתוב \"איש איש כי יהיה זב מבשרו \u0003זובו טמא\u0004 הוא\" (שם ב) שממנו למדנו (כמובא בתחילת הסוגיה) את דין טומאת הזוב, \u0003למה לי?\u0004","\u0003אמר רב יהודה מדסקרתא\u0004 בתשובה: \u0003איצטריך\u0004 \u0005[נצרך]\u0006 כתוב זה, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי דין \u0003שעיר המשתלח יוכיח\u0004 שאין הזוב טמא. \u0003ש\u0004הרי השעיר המשתלח \u0003גורם טומאה לאחרים\u0004 (לאדם המשלח אותו לעזאזל), \u0003ו\u0004בכל זאת \u0003הוא\u0004 השעיר \u0003עצמו טהור.\u0004 והיה מקום לומר שאף הזוב, אף שגורם טומאה לאדם שיצא ממנו, מכל מקום הוא עצמו לא יהיה טמא. \u0003ואי\u0004 \u0005[ואם]\u0006 תאמר כי אין לומר כן, \u0003משום\u0004 הכתוב \u0003\"הזב את זובו\"\u0004 המלמדנו שהזוב עצמו נטמא, ובדומה לזב — יש מקום לדחות ולומר כי לא בא היקש זה שבין הזוב לזב ללמדנו לענין טומאת הזוב, אלא ללמדנו \u0003ל\u0004ענין \u0003מניינא\u0004 \u0005[מנין,\u0006 מספר\u0005]\u0006 ראיות הזיבה שבהן חלה על הרואה טומאת זב \u0003הוא דאתא\u0004 \u0005[שבא],\u0006 שהן שלוש ראיות.","ובאופן זה: הכתוב \u0003\"זוב\"\u0004 (הכלול במלה \"זובו\") — מלמד על \u0003חד\u0004 \u0005[\u0006ראיה \u0005אחת]\u0006 של זיבה. הכתוב \u0003\"זובו\"\u0004 — מלמד על \u0003תרתי\u0004 \u0005[שתי\u0006 ראיות\u0005]\u0006 של זיבה. ומן הכתוב \"לזכר\" למדים אנו שבשתי ראיות דינו שונה משל הנקבה (שאין הוא מטמא בראיית אונס כאשה). ואולם לענין ראייה \u0003בשלישי\u0004 בא הכתוב הנוסף \"או לנקבה\" שבו \u0003אקשיה רחמנא\u0004 \u0005[הקישו הכתוב]\u0006 \u0003לנקבה,\u0004 ללמדנו כי בראייה שלישית, אפילו היתה זו באונס, הריהו נטמא ומביא קרבן על טומאתו, ולא היינו יודעים עדיין כי הזוב עצמו הריהו טמא.","לכך \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"זובו טמא\".\u0004 \u0003והשתא דאמר רחמנא\u0004 \u0005[ועכשיו שאמר הכתוב]\u0006 \u0003\"זובו טמא הוא\",\u0004 וכדרך שנדרש הכתוב — \u0003דרוש ביה נמי האי\u0004 \u0005[דרוש בו גם כן\u0006 דרשה \u0005זו]\u0006 הנלמדת מהכתוב \"הזב את זובו\".","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003הרוק\u0004 של הזב מטמא לח ואינו מטמא ביבש. ומבררים: עצם דין הטומאה שב\u0003רוק\u0004 הזב \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בפרשת הזב \u0003\"וכי ירק\u0004 הזב בטהור וכבס בגדיו ורחץ במים וטמא עד הערב\" (ויקרא טו, ח). ומבררים: \u0003יכול\u0004 יהא הדין שהרוק מטמא את האדם הטהור, \u0003אף על פי שלא נגע\u0004 בו, אלא שרק נרוק לעברו — לכך \u0003תלמוד לומר\u0004 (מלמדנו הכתוב) \"וכי ירוק הזב \u0003בטהור\"\u0004 — שאין הטהור נטמא ביריקה זו \u0003עד שיגע\u0004 הרוק \u0003בטהור.\u0004","ומוסיפים לברר: מלשון הכתוב \"וכי ירוק\" \u0003אין לי\u0004 לטמא \u0003אלא\u0004 את \u0003רוקו\u0004 של הזב בלבד, ואולם לענין \u0003כיחו וניעו ומי האף שלו\u0004 שאף הם מטמאים \u0003מנין\u0004 לי? לכך \u0003תלמוד לומר \"וכי ירק\"\u0004 בתוספת וא\"ו (שהרי היה יכול לכתוב \"כי\"), כלשון ריבוי המלמדת שאף אלה מטמאים. ומעתה דנים בדברי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם\u0006 בברייתא\u0005]:\u0006 \u0003יכול\u0004 יטמא הרוק \u0003אף על פי שלא נגע\u0004 בזה שנרוק לעברו, והביא מן הכתוב ללמדנו שאין הרוק מטמא אלא בנגיעה. ותוהים על עצם השאלה: \u0003מהיכא תיתי\u0004 \u0005[מהיכן תבוא,\u0006 מדוע נעלה על דעתנו\u0005]\u0006 לומר שיהא האדם הטהור נטמא אף ביריקה שלא נגעה בו, עד שנצרך הכתוב להשמיענו שלא כך הדין.","ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003נילף\u0004 \u0005[נלמד]\u0006 בגזירה שווה של המלה \u0003\"רוק\"\u0004 האמורה בזב, מהמלה \u0003\"רוק\"\u0004 האמורה בדין ה\u0003יבמה\u0004 החולצת (שנאמר בה \"וירקה בפניו\". דברים כה, ט). \u0003מה התם\u0004 \u0005[שם,\u0006 במעשה חליצת יבמה\u0005]\u0006 — הרי זה מעשה חליצה ראוי, \u0003אף על פי\u0004 ש\u0003לא נגע\u0004 הרוק בפני היבם, \u0003אף הכא נמי\u0004 \u0005[כאן,\u0006 בטומאת רוק הזב, \u0005גם כן]\u0006 — מטמא הרוק את האדם הטהור, אף ש\u0003לא נגע\u0004 בו, לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 הכתוב \u0005משמיע לנו]\u0006 שאין הרוק מטמא אלא כשנגע באדם הטהור.","ודנים עוד: \u0003ואימר\u0004 \u0005[ואמור]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שרוקו של הזב מטמא, אמורים דווקא \u0003במגע, אבל במשא\u0004 — \u0003לא\u0004 מטמא, \u0003מידי דהוה\u0004 \u0005[כמו ש\u0006כך \u0005הוא]\u0006 הדין בטומאת ה\u0003שרץ\u0004 (המטמא במגע, ולא במשא)! \u0003אמר ריש לקיש:\u0004 אין לומר כן, שהרי כך \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005של בית]\u0006 המדרש של ר' ישמעאל: \u0003אמר קרא\u0004 \u0005[הכתוב] \"\u0006\u0003בטהור\"\u0004 — ללמדנו כי כל \u0003מה\u0004 מטומאת רוק הזב \u0003ש\u0004נמצא \u0003ביד\u0004 ה\u0003טהור,\u0004 ואף שאין הוא נוגע בו במישרין, אלא רק נישא על ידו, גם כן \u0003טמאתי לך.\u0004","ודנים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי אף שנטמא הטהור במגע ובמשא, נבחין בדיניהן, ו\u0003במשא\u0004 הטהור את רוק הזב — הריהו \u0003מטמא\u0004 את ה\u0003אדם\u0004 הנושא \u0003ו\u0004כן את ה\u0003בגדים\u0004 שעליו. ואילו \u0003במגע\u0004 — את ה\u0003אדם\u0004 הנוגע עצמו \u0003לטמא,\u0004 אך את ה\u0003בגדים\u0004 שעליו — \u0003לא לטמא,\u0004 \u0003מידי דהוה\u0004 \u0005[כמו ש\u0006כך \u0005הוא]\u0006 הדין בטומאת \u0003מגע נבלה,\u0004 שאין היא מטמאת אלא את הנוגע, ול","\u0003ריש לקיש, וכן\u0004 \u0003תנא דבי\u0004 \u0005[שנה החכם של בית\u0006 המדרש\u0005]\u0006 של \u0003ר' ישמעאל: אמר קרא\u0004 \u0005[הכתוב] \"\u0006\u0003בטהור\"\u0004 — ללמדנו כי \u0003טהרה שטהרתי לך במקום אחר, טמאתי לך כאן, ואיזה זה?\u0004 — \u0003זה מגע נבלה\u0004 שאכן אינה מטמאת אדם ובגדים, ואולם רוק הזב מטמא אדם ובגדים.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי כך היא כוונת הכתוב שטהרה שטהרתי לך במקום אחר, \u0003כ\u0004טומאת ה\u0003משא\u0004 של ה\u0003שרץ,\u0004 שאין הוא מטמא במשא, טמאתי לך כאן ברוקו של הזב, שהריהו מטמא במשא. ואולם עדיין יש מקום לומר שתהא טומאת רוק הזוב כטומאת הנבלה, המטמאה את האדם בלבד, ולא את הבגדים שעליו! ודוחים: אין לומר כן, שהרי \u0003אם כן\u0004 הוא, \u0003נכתוב קרא\u0004 \u0005[שתכתוב התורה]\u0006 \"וכי ירוק הזב \u0003באדם\", מאי\u0004 \u0005[מה\u0006 טעם\u0005]\u0006 נאמר \"וכי ירוק הזב \u0003בטהור\"\u0004 — \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 שנוהגת טומאת משא ברוק הזב, ושמגעו מטמא את הנוגע ואת הבגדים שעליו.","\u0003ו\u0004עוד שנינו בברייתא כי \u0003מי האף\u0004 של הזב מטמאים בלח ולא ביבש. ומבררים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003מי האף? אמר רב:\u0004 מדובר \u0003ב\u0004מי האף ה\u0003נגררין\u0004 (נפלטים) \u0003דרך הפה\u0004 של האדם. והטעם שהם טמאים: \u0003לפי שאי אפשר למי האף\u0004 היוצאים דרך הפה \u0003בלא\u0004 שיהיה בתוכם \u0003צחצוחי\u0004 (שאריות מועטות) \u0003הרוק.\u0004 והריהם טמאים איפוא מטומאת הרוק. \u0003ו\u0004אילו \u0003ר' יוחנן אמר\u0004 כי המדובר במי האף, \u0003אפילו בנגררין\u0004 כדרכם \u0003דרך החוטם.\u0004 ומסבירים את דעתו: \u0003אלמא קסבר\u0004 \u0005[הרי סבור הוא]\u0006 כי גם הנוזל מן האף \u0003מעיין הוא, ורחמנא רבייה\u0004 \u0005[והתורה ריבתה אותו]\u0006 בכתוב \"וכי ירוק\", שאף הוא מטמא, כרוק.","ושואלים: \u0003ו\u0004לדעת \u0003רב\u0004 הסבור כי מי האף נטמאים משום שיש בהם שאריות של רוק, מעתה במשנתנו \u0003נחשוב נמי\u0004 \u0005[נמנה גם כן]\u0006 ברשימת הדברים היוצאים מן הזב המטמאים, את \u0003דמעת עינו\u0004 של הזב. שכן \u0003אמר רב: האי מאן דבעי דלסתמיה לעיניה\u0004 \u0005[זה שרוצה לעוור את עינו]\u0006 — \u0003ליכחול\u0004 \u0005[שיכחול,\u0006 ימרח חומר על עיניו\u0005]\u0006 \u0003מגוי,\u0004 שעלול הגוי לתת בתוך חומר זה דבר המעוור עינים. \u0003ולוי אמר: האי מאן דבעי דלימות\u0004 \u0005[זה שרוצה למות]\u0006 — \u0003ליכחול\u0004 \u0005[שיכחול]\u0006 \u0003מגוי,\u0004 שעלול הגוי לתת סם מוות בתוך הכחילה.","ובהסבר דברי רב הללו \u0003אמר רב חייא בר גוריא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 לדברי \u0003רב\u0004 ש\u0003לא אמר\u0004 (כלוי) \u0003הא מאן דבעי דלימות\u0004 \u0005[זה שרוצה למות],\u0006 שיכחול עיניו מגוי, אלא הזכיר רק את סכנת העיוורון — כי לדעת רב אין סכנת מוות בדבר, אף אם יש חומר ממית בכחילה, \u0003הואיל ויכול\u0004 הוא \u0003לגוררן ולהוציאן דרך הפה.\u0004 הרי איפוא שגם נוזלי העין נגררים דרך הפה, ומעתה תטמא גם דמעת עינו של הזב! \u0003ו\u0004מתרצים: לדעת \u0003רב, נהי דזיהרא\u0004 \u0005[\u0006אף כי \u0005אמנם ארס מוות]\u0006 הניתן לעינו של אדם \u0003נפיק\u0004 \u0005[יוצא]\u0006 דרך פיו של האדם, ואולם \u0003דמעתא גופא\u0004 \u0005[דמעה בעצמה]\u0006 — \u0003לא נפיק\u0004 \u0005[אינה יוצאת]\u0006 דרך הפה. ודנים עתה בדעותיהם של רב ור' יוחנן אלה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא: \u0003תשעה משקין\u0004 יוצאים מן \u0003הזב\u0004 ואלו \u0003הן: הזיעה, והליחה סרוחה, והריעי\u0004 (צואה) — \u0003טהורין מכלום\u0004 (שאין בהם כל טומאה). \u0003דמעת עינו, ודם מגפתו\u0004 (פצעו), \u0003וחלב האשה\u0004 — \u0003מטמאין טומאת משקין,\u0004 לטמא אוכלים ומשקים, כשאר המשקים הטמאים, ושיעור טומאתם הוא \u0003ברביעית.\u0004 \u0003אבל זובו, רוקו, ומימי רגליו\u0004 — \u0003מטמאין טומאה חמורה.\u0004 \u0003ואילו מי האף לא קתני\u0004 \u0005[לא שנה].\u0006","\u0003בשלמא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003רב\u0004 הסבור שמי האף מטמאים משום צחצוחי רוק שבהם, מובן מדוע \u0003לא קתני\u0004 \u0005[אין נשנים\u0006 מי האף\u0005]\u0006 — שכן \u0003לא פסיקא ליה למתני\u0004 \u0005[אין זה פסוק,\u0006 חתוך ומוחלט, דין מי האף, \u0005לו,\u0006 לתנא, \u0005שישנה\u0006 אותם\u0005],\u0006 שכן \u0003זימנין דאתי\u0004 \u0005[לפעמים שבאים]\u0006 מי האף \u0003דרך הפה\u0004 — והריהם טמאים, \u0003ו\u0004אולם \u0003זימנין דאתי\u0004 \u0005[פעמים שבאים]\u0006 \u0003דרך החוטם,\u0004 ואינם טמאים. \u0003אלא לר'\u0004 \u0003יוחנן\u0004 האומר כי מי האף נחשבים כמעיין לעצמם, והתרבו מן הכתוב \"וכי ירוק\", \u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא גם את מי האף.","ודוחים: \u0003ולטעמיך ולטעמך,\u0004 לשיטתך\u0005],\u0006 כדעת רב, \u0003כיחו וניעו מי קתני\u0004 \u0005[האם הוא\u0006 התנא \u0005שנה]?\u0006 \u0003אלא\u0004 יש לומר כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003רוק וכל דאתא מרבויא\u0004 \u0005[שבא מריבוי\u0006 הכתוב, ככיחו וניעו\u0005],\u0006 \u0003הכא נמי\u0004 \u0005[כך גם כן]\u0006 יש לומר כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003רוקו, וכל דאתא מרבויא\u0004 \u0005[שבא מריבוי\u0006 הכתוב, כמי האף\u0005].\u0006 שנינו בברייתא כי דמעת עינו ודם מגפתו וחלב האשה נחשבים כמשקים, ולכך הם מטמאים טומאת משקים.","ומביאים מקור לדברים: \u0003דמעת עינו\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ותשקמו בדמעות שליש\"\u0004 (תהלים פ, ו). \u0003ודם מגפתו\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ודם חללים ישתה\"\u0004 (במדבר כג, כד) \u0003מה לי קטליה כוליה\u0004 \u0005[הרג אותו כולו],\u0006 שנחשב דמו כמשקה, הרי שנקרא משקה, \u0003מה לי קטליה פלגיה\u0004 \u0005[הרגו למחצה],\u0006 כדם זה היוצא מן הפצע, שאף הוא נחשב כמשקה. \u0003חלב האשה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ותפתח את נאוד החלב ותשקהו\"\u0004 (שופטים ד, יט).","עוד שנינו בברייתא בין הדברים המטמאים טומאה חמורה את \u0003מימי רגליו.\u0004 ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שכך הוא דינם? \u0003דתניא:\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]\u0006 על האמור בתחילת פרשת הזב \"איש איש כי יהיה זב מבשרו \u0003זובו טמא\u0004 הוא. \u0003וזאת\u0004 תהיה טומאתו בזובו\" (ויקרא טו, א—ב): באה המלה \"וזאת\" \u0003לרבות\u0004 את \u0003מימי רגליו לטומאה\u0004 חמורה, שאף הם הריהם כזוב. ומסבירים: \u0003והלא\u0004 אין צורך בדרשה זו כדי ללמדנו כן, שהרי \u0003דין\u0004 (קל וחומר) \u0003הוא,\u0004 ובאופן זה: \u0003ומה רוק\u0004 של הזב, \u0003הבא ממקום טהרה\u0004 (מן הפה) — הריהו \u0003טמא, מימי רגליו\u0004 של הזב \u0003הבאין\u0004"],["\u0003ממקום טמא\u0004 (מהמקום ממנו יוצאת הזיבה) — \u0003אינו דין שיהו טמאין!\u0004 ופורכים קל וחומר זה: \u0003דם היוצא מפי האמה\u0004 של הזב \u0003יוכיח, ש\u0004 הרי אף שדם זה \u0003בא ממקום טמא, ו\u0004בכל זאת הריהו \u0003טהור.\u0004 ומעתה, \u0003אף אתה אל תתמה על זה\u0004 (במימי רגלים), \u0003שאף על פי ש\u0004הוא \u0003בא ממקום טומאה,\u0004 בכל זאת \u0003יהיה טהור,\u0004 לכך \u0003תלמוד לומר\u0004 האמור בתחילת פרשת הזב \"איש איש כי יהיה זב מבשרו \u0003זובו טמא\u0004 הוא. \u0003וזאת\u0004 תהיה טומאתו בזובו\" (ויקרא טו, א—ב) — ובאה המלה \"וזאת\" \u0003לרבות\u0004 את \u0003מימי רגליו לטומאה\u0004 חמורה, שאף הם דינם כזוב.","למעלה הוזכר כי מי הרגלים של הזב מטמאים טומאה חמורה, ואולם ה\u0003דם היוצא מפי האמה\u0004 של הזב, הריהו טהור, אף שבא ממקום טמא. ומבררים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שדם היוצא מפי האמה של הזב \u0003טהור?\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003יכול יהא דם היוצא מפיו\u0004 של הזב, \u0003ו\u0004כן הדם היוצא \u0003מפי האמה\u0004 שלו, יהיו \u0003טמאין\u0004 כזובו — לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בתחילת פרשת הזב \u0003\"זובו טמא הוא\"\u0004 (ויקרא טו, ב). והיא לשון מיעוט, לומר: דווקא \u0003הוא\u0004 הזוב עצמו \u0003טמא, ואין דם היוצא מפיו ומפי האמה טמא, אלא טהור.\u0004","ושואלים: \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 את הדינים, ותהא טומאת דם היוצא מפי אמתו נלמדת מריבוי הכתוב \"וזאת תהיה טומאתו בזובו\", שאף הוא מטמא, ואילו טהרת מי רגליו ממיעוט הכתוב \"טמא הוא\"! \u0003אמר ר'\u0004 \u0003יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחי:\u0004 ראוי לרבות דווקא את מי הרגלים לטמא, ולא את הדם, שכן מי הרגלים הריהם \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003רוק, מה רוק\u0004 — הריהו דבר \u0003ש\u0004בתחילה הוא \u0003מתעגל\u0004 (נאגר ומצטבר) בתוך הגוף, \u0003ו\u0004אחר כך \u0003יוצא\u0004 ממנו. \u0003אף כל\u0004 דבר היוצא מן הזב \u0003ש\u0004הינו \u0003מתעגל ויוצא,\u0004 כמי הרגלים, הריהו טמא. \u0003יצא\u0004 מכלל זה ה\u0003דם\u0004 — \u0003שאין\u0004 הוא \u0003מתעגל ויוצא.\u0004","ושואלים על כך: \u0003והרי חלב שבאשה, שמתעגל ויוצא,\u0004 והיה ראוי שחלב הזבה יטמא בטומאה חמורה, \u0003ו\u0004בכל זאת \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא כי ה\u0003חלב שבאשה\u0004 הריהו \u0003מטמא טומאת משקין,\u0004 ונדייק בדבריו: \u0003טומאת משקין\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 מטמא חלב האשה, \u0003אבל לא טומאה חמורה!\u0004","\u0003אלא אמר ר'\u0004 \u0003יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחי:\u0004 ראוי לרבות דווקא את מי הרגלים לטמא, ולא את הדם, שכן מי הרגלים הריהם \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003רוק, מה רוק\u0004 — הריהו דבר \u0003ש\u0004בתחילה הוא \u0003מתעגל\u0004 (נאגר ומצטבר) בתוך הגוף, \u0003ו\u0004אחר כך \u0003יצא\u0004 ממנו. \u0003ו\u0004אולם כאשר אין הוא יוצא אל מחוץ לגוף, הריהו \u0003חוזר ונבלע\u0004 בגוף. \u0003אף כל\u0004 דבר שהריהו \u0003מתעגל ויוצא, ו\u0004אם אין הוא יוצא הריהו \u0003חוזר ונבלע\u0004 בגוף, הוא מטמא בטומאת הזב. \u0003יצא\u0004 מכלל זה ה\u0003דם\u0004 — \u0003ש\u0004הוא \u0003אינו מתעגל ויוצא.\u0004 וכן \u0003יצא\u0004 מכלל זה ה\u0003חלב שבאשה\u0004 — \u0003שאף על פי ש\u0004אמנם הוא \u0003מתעגל ויוצא,\u0004 ואולם כאשר לא יצא הוא \u0003אינו חוזר ונבלע\u0004 בגוף.","ושואלים: \u0003ונילף\u0004 \u0005[ונלמד]\u0006 לטמא את דם הזב וחלב הזבה \u0003מזובו\u0004 של הזב, ובאופן זה: \u0003מה זובו, שאין\u0004 הוא \u0003מתעגל ויוצא,\u0004 ובכל זאת הריהו \u0003מטמא, אף כל\u0004 היוצא מהזב הריהו מטמא, אף שאינו מתעגל ויוצא! \u0003אמר רבא\u0004 בתשובה: \u0003מזובו ליכא למילף\u0004 \u0005[אין מקום ללמוד]\u0006 לעניינם של דברים אחרים, \u0003שכן\u0004 מיוחד הוא דינו של הזוב, שהריהו \u0003גורם טומאה לאחרים\u0004 (לאדם הזב שראה את זובו, ונטמא בו).","\u0003ו\u0004עוד שנינו במשנתנו כי \u0003השרץ\u0004 מטמא בלח, ואינו מטמא ביבש. ובענין זה \u0003אמר ריש לקיש: שרץ שיבש ושלדו קיימת,\u0004 שלא נשבר שלד עצמותיו של השרץ — הריהו \u0003טמא.\u0004 ותוהים על דבריו: \u0003והאנן תנן\u0004 \u0005[הורי אנו שונינו\u0006 במשנתנו\u0005]\u0006 ברשימת הטומאות שהשרץ בכללן, כי הריהן \u0003מטמאין\u0004 דווקא כשהם \u0003לחין ואין\u0004 הם \u0003מטמאין\u0004 כשהם \u0003יבשין! אמר ר'\u0004 \u0003זירא\u0004 בתשובה: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן יש להבחין בין האופנים השונים. \u0003הא\u0004 \u0005[זה,\u0006 דברי ריש לקיש\u0005]\u0006 המטמא אף את השרץ שיבש — אמורים דווקא \u0003בכולן,\u0004 כאשר כל השלד כולו שלם, שאז הריהו מטמא אף שהוא יבש. ואילו \u0003הא\u0004 \u0005[זה,\u0006 דברי משנתנו\u0005],\u0006 שאין השרץ היבש מטמא, אמורים כאשר \u0003במקצתן,\u0004 כאשר רק מקצת השלד נותרה קיימת, ובכגון זה שוב אינו מטמא.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003יצחק בר' ביסנא,\u0004 \u0003אמר ר'\u0004 \u0003שמעון בן יוחי:\u0004 ממה שנאמר בטומאת השרצים \"אלה הטמאים לכם בכל השרץ כל הנוגע \u0003\"בהם\"\u0004 במותם יטמא עד הערב\" (ויקרא יא, לא), \u0003יכול\u0004 שנלמד שטומאה זו נוהגת רק בנוגע \u0003בכולן,\u0004 כשהם שלמים, ולא בנוגע במקצתם — לכך \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בפסוק שלאחר מכן \"וכל אשר יפול עליו \u0003מהם\u0004 במותם יטמא\", להורות שהריהם מטמאים אף בחלק מהם.","ואולם יש לחזור ולדון שוב: \u0003אי\u0004 \u0005[אם]\u0006 נלמד מהכתוב \u0003\"מהם\"\u0004 — \u0003יכול\u0004 נלמד מכאן כי הריהם טמאים אף \u0003במקצתן.\u0004 לכך \u0003תלמוד לומר\u0004 \"כל הנוגע \u0003בהם\"\u0004 — להורות שהריהם טמאים דווקא כאשר הם שלמים. ומעתה, \u0003הא\u0004 \u0005[זה]\u0006 \u0003כיצד\u0004 ניישב את הסתירה? \u0003כאן,\u0004 הכתוב המלמד שאף במקצתם הריהם מטמאים — מדובר בו \u0003ב\u0004שרץ ה\u0003לח.\u0004 ואילו \u0003כאן\u0004 בכתוב המלמד שהשרץ מטמא רק כשהוא שלם — מדובר \u0003ב\u0004שרץ ה\u0003יבש.\u0004","ובענין זה הוסיף ו\u0003אמר רבא\u0004 כי \u0003הני זבוגי\u0004 \u0005[אלה הצבים]\u0006 של העיר \u0003מחוזא\u0004 שבבבל, \u0003כי\u0004 \u0005[כאשר,\u0006 כל עוד\u0005]\u0006 \u0003שלדן קיימת\u0004 — הריהם \u0003טמאין.\u0004 \u0003ו\u0004כיוצא בדבר \u0003אמר\u0004 עוד \u0003ריש לקיש:\u0004 ה\u0003שרץ שנשרף ו\u0004אולם \u0003שלדו\u0004 עדיין \u0003קיימת\u0004 — הריהו עדיין \u0003טמא.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דבריו ממה ששנינו: אם \u0003נמצא שרץ שרוף על גבי הזיתים, וכן מטלית\u0004 טמאה \u0003המהוהא\u0004 (בלויה ורקובה) — הזיתים \u0003טהורין.\u0004 \u0003ש\u0004לפי הכלל ש\u0003כל הטמאות\u0004 דנים בהן \u0003כשעת מציאתן.\u0004 שכפי שהן עתה כך הגיעו אל הזיתים הללו, ובמצבם עתה אין הם מטמאים. הרי שאין השרץ השרוף מטמא, ושלא כדברי ריש לקיש! \u0003אמר ר'\u0004 \u0003זירא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שיש להבחין בין המקרים השונים. \u0003הא\u0004 \u0005[זה,\u0006 דברי ריש לקיש\u0005]\u0006 המטמא אף את השרץ השרוף (ושלדו קיים) — אמורים דווקא \u0003בכולן,\u0004 כאשר השלד שלם. ואז הוא מטמא אף שהוא שרוף. ואילו \u0003הא\u0004 \u0005[זה,\u0006 דברי הברייתא\u0005,\u0006 האומרת שאינו מטמא, אמורים \u0003במקצתן,\u0004 כאשר רק מקצת השלד נותרה קיימת.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003יצחק בר' ביסנא\u0004 \u0003משום\u0004 \u0005[בשם]\u0006 \u0003ר' שמעון בן יוחי\u0004 ממה שנאמר בטומאת השרצים \"אלה הטמאים לכם בכל השרץ כל הנוגע \u0003הם\u0004 במותם יטמא עד הערב\", \u0003יכול\u0004 שנלמד שטומאה זו נוהגת רק בנוגע \u0003בכולן,\u0004 כשהם שלמים — \u0003תלמוד לומר\u0004 (מלמדנו הנאמר) בפסוק שלאחר מכן \"וכל אשר יפול עליו \u0003מהם\u0004 במותם יטמא\" — שהם מטמאים אף בנגיעה בחלק מהם.","ואולם יש לחזור ולדון שוב: \u0003אי\u0004 \u0005[אם]\u0006 נלמד מהכתוב \u0003\"מהם\"\u0004 — \u0003יכול\u0004 נלמד מכאן כי הריהם טמאים אף \u0003במקצתן.\u0004 לכך \u0003תלמוד לומר\u0004 בפסוק הקודם \"כל הנוגע \u0003בהם\"\u0004 — דווקא כאשר הם שלמים. \u0003הא\u0004 \u0005[זה]\u0006 \u0003כיצד\u0004 ניישב את הסתירה? \u0003כאן,\u0004 הכתוב המלמד שהם מטמאים רק כשהם שלמים — מדבר \u0003ב\u0004שרץ ה\u0003שרוף.\u0004 ואילו \u0003כאן\u0004 הכתוב המלמד שהשרץ מטמא אף שאינו שלם — מדבר \u0003ב\u0004שרץ \u0003שאינו שרוף.\u0004","שנינו במשנתנו רשימת הדברים הטמאים, ש\u0003מטמאין\u0004 רק כאשר הן \u0003לחין\u0004 ולא כאשר הם יבשים. ומפרטים את מקור הדברים: ה\u0003זב\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בטומאתו \u0003\"רר בשרו\"\u0004 (ויקרא טו, ג), להורות על דבר הלח. \u0003כיחו וניעו ורוקו\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בטומאתם \"ו \u0003כי ירק הזב\"\u0004 (שם ח) — כל שהוא \u0003כעין רוק,\u0004 שהוא לח ולא יבש.","ה\u0003שרץ\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בטומאתו \"כל הנוגע בהם \u0003במותם\"\u0004 (שם לא) \u0003אמר\u0004 \u0005[אמרה]\u0006 \u0003רחמנא\u0004 (התורה), טומאתם לאחר מותם הריהי רק כשהם \u0003כעין\u0004 שעת \u0003מיתה.\u0004 שהגוף לח באותה עת. \u0003שכבת זרע\u0004 — שרק שכבת זרע \u0003הראויה להזריע,\u0004 הלחה ולא היבשה מטמאה. \u0003נבלה\u0004 — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בטומאתה ו\u0003\"כי ימות\u0004 מן הבהמה אשר היא לכם לאוכלה הנוגע בנבלתה יטמא עד הערב\" (שם לט), \u0003כעין מיתה,\u0004 שהגוף לח באותה עת.","שנינו במשנתנו ש\u0003אם יכולין להשרות\u0004 את הטמאים שנמנו בה המטמאים דווקא כשהם לחים, ולהחזירם בכך לכמות שהיו לחים — הריהם מטמאים. ועוד שנינו שהשרייה זו נעשית במים פושרים מעת לעת. ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 האם הכוונה היא שיהיו המים מ\u0003תחילתו\u0004 של ההשרייה \u0003ו\u0004עד סופו בפושרין, א \u0003ו דלמא\u0004 \u0005[שמא]\u0006 די שיהיו המים ב\u0003תחילתו\u0004 פושרים, \u0003אף על פי שאין סופו\u0004 פושרים?","ומציעים פתרון לשאלה: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 ממה ששנינו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כמה\u0004 זמן \u0003היא שרייתן בפושרין? יהודה בן נקוסא אומר: מעת לעת.\u0004 ודי שיהיו המים ב\u0003תחילתו\u0004 פושרים, \u0003אף על פי שאין סופו\u0004 פושרים. \u0003רבן שמעון בן גמליאל אומר: צריכין שיהו\u0004 המים \u0003פושרין\u0004 כל \u0003מעת לעת.\u0004","שנינו במשנתנו כי \u0003ר' יוסי אומר\u0004 ש\u0003בשר המת\u0004 שיבש ואינו יכול לחזור לכמות שהיה לאחר השרייה — הריהו טהור. ובהסבר דברי ר' יוסי \u0003אמר שמואל\u0004 שהכוונה היא שהריהו \u0003טהור מלטמא בכזית, אבל\u0004 הריהו \u0003מטמא טומאת רקב\u0004 (ששיעורה הוא כמלוא התרוד). ומביאים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך,\u0006 כהסברו זה של שמואל\u0005],\u0006 \u0005ר' יוסי אומר: בשר המת שיבש, ואין יכול לשרות ולחזור כמות שהיה —\u0006 \u0003טהור מלטמא בכזית, אבל טמא טומאת רקב.\u0004","\u0003השרץ\u0004 המת \u0003שנמצא במבוי,\u0004 ואין ידוע מתי הגיע למבוי — הריהו \u0003מטמא למפרע\u0004 את כל הטהרות הנמצאות במבוי זה (שמא נגעו בו הטהרות, ונטמאו על ידו). \u0003עד ש\u0004יבוא אדם ו\u0003יאמר\u0004 לפני בית הדין: \u0003\"בדקתי את המבוי הזה, ולא היה בו\u0004 באותה שעה כל \u0003שרץ\".\u0004 ובאופן זה כל הטהרות שהיו במבוי עד לאותה שעה הריהן טהרות. \u0003או\u0004 אופן נוסף שבו הטהרות אינן נטמאות: אלה שהיו במבוי \u0003עד שעת כבוד\u0004 (טאטוא) המבוי אינן טמאות, שהרי בוודאי בשעת הכיבוד היו רואים את השרץ המת (אילו היה שם באותה עת). ולכך ודאי שהגיע השרץ למבוי רק לאחר שכובד המבוי.","\u0003וכן כתם\u0004 בצבע אדום \u0003שנמצא בחלוק\u0004 אשה — הריהו \u0003מטמא למפרע\u0004 את כל הטהרות שנגעה בהן האשה, \u0003עד שיאמר \"בדקתי את החלוק הזה, ולא היה בו כתם\",\u0004 שבאופן זה אין הטהרות שנגעה בהן לפני הבדיקה טמאות. \u0003או\u0004 הטהרות שנגעה בהן \u0003עד שעת הכבוס,\u0004 שחזקה היא שבנות ישראל בודקות חלוקיהן בשעת הכיבוס, ואילו היה שם כתם באותה עת, היתה רואה אותו.","\u0003ומטמא\u0004 השרץ והכתם טומאה למפרע, \u0003בין\u0004 שהוא עתה \u0003לח, בין\u0004 כשהוא עתה \u0003יבש.\u0004 ואילו \u0003ר' שמעון אומר\u0004 כי השרץ או הכתם \u0003היבש\u0004 — אמנם \u0003מטמא למפרע\u0004 (עד שעת כיבוס או שעת כיבוד), ומפני החשש שמא היה שם השרץ במשך פרק זמן זה. \u0003ו\u0004אולם השרץ או הכתם \u0003הלח\u0004 — \u0003אינו מטמא\u0004 למפרע \u0003אלא עד שעת\u0004 (שעה) \u0003ש\u0004אם היה באותה שעה לח \u0003יהא יכול לחזור ולהיות\u0004 בשעת מציאתו עדיין \u0003לח,\u0004 ולא עד שעת כיבוס או שעת כיבוד, המרוחקות משעה זו. שהרי ברור הוא שלא היה השרץ או הכתם באותה עת. שכן, אילו היה אז — לא היה עדיין לח בשעת מציאתו.","שנינו במשנתנו כי אין הטהרות שהיו במבוי לפני שעת הכיבוד נטמאות בשרץ זה. ובדבר זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 שאלה זו: האם כוונת דברי המשנה \u0003\"עד שעת כבוד\u0004 (טאטוא)\" לומר כי משטיאטאו אותו \u0003חזקתו\u0004 של המבוי שהוא \u0003בדוק,\u0004 שמן הסתם בודקים אותו אם יש בו טומאות. ומשום כך הטהרות שהיו עד שעת הכיבוד אינן נטמאות. \u0003או דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא ש\u0003חזקתו\u0004 של המבוי שהוא \u0003מתכבד,\u0004 ואילו היה שם שרץ, היה יוצא מהמבוי באמצעות הכיבוד?","\u0003ו\u0004מסבירים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה,\u0006 אם נאמר כצד זה או כצד זה\u0005]\u0006 — במקרה ש\u0003אמר\u0004 האדם שכיבד את המבוי כי הוא אמנם \u0003כביד\u0004 \u0005[כיבד,\u0006 טאטא\u0005]\u0006 את המבוי, \u0003ו\u0004אולם \u0003לא בדק\u0004 \u0005[לא בדק]\u0006 אותו. ומעתה: \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 בטעם טהרתן של הטהרות שהיו לפני הכיבוד שהוא משום ש\u0003חזקתו\u0004 של המבוי המטואטא שהוא גם \u0003בדוק\u0004 — במקרה זה אין לטהר את הטהרות שהיו לפני הכיבוד, שכן \u0003הא\u0004 \u0005[הרי]\u0006 אומר המכבד כי הוא \u0003לא בדוק\u0004 את המבוי. ואולם \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 בטעם טהרתן של הטהרות שהיו לפני הכיבוד שהוא משום ש\u0003חזקתו\u0004 של מבוי שהוא \u0003מתכבד,\u0004 ובשעה שטואטא המבוי, יצא השרץ עם הטאטוא — \u0003הא\u0004 \u0005[הרי]\u0006 אף במקרה זה המבוי \u0003מתכבד,\u0004 ואין הטהרות שהיו לפני כן נטמאות."],["\u0003אי נמי\u0004 \u0005[אם גם כן]\u0006 עוד אופן שיש בו הבדל הלכתי בין שתי האפשרויות הללו — במקרה \u0003דאשתכח\u0004 \u0005[שנמצא]\u0006 השרץ \u0003בגומא\u0004 (שקע קטן באדמה) שבמבוי. ומעתה: \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 בטעם טהרתן של הטהרות שהיו לפני הכיבוד שהוא משום ש\u0003חזקתו\u0004 של המבוי המטואטא שהוא גם \u0003בדוק\u0004 — יש לטהר את הטהרות שהיו לפני הכיבוד, כי \u0003מאן דבדק\u0004 \u0005[מי שבודק]\u0006 — \u0003בגומא\u0004 \u0003נמי בדיק\u0004 \u0005[גם כן בודק].\u0006 ואולם \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שטעם טהרתן של הטהרות שהיו לפני הכיבוד שהוא משום ש\u0003חזקתו\u0004 של מבוי שהוא \u0003מתכבד,\u0004 ובשעה שטואטא המבוי, יצא השרץ עם הטאטוא — אין הדברים אמורים אלא בדברים הנמצאים על פני הקרקע, ואולם ה\u0003גומא לא מתכבדא\u0004 \u0005[אינה מתכבדת],\u0006 ואין הדבר הנמצא בתוך גומא יוצא עם הטאטוא. ולכך יש לטמא אף את הטהרות שהיו לפני הכיבוד במבוי זה.","שנינו במשנתנו: \u0003וכן הכתם\u0004 הנמצא בחלוק מטמא למפרע את כל הטהרות שנגעה בהן האשה, עד שתאמר \"בדקתי את החלוק הזה, ולא נמצא בו כתם\", או עד שעת הכיבוס. ואף בהלכה זו \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]: האם כוונת דברי המשנה\u0006 \u0003\"עד שעת כבוס\"\u0004 לומר כי \u0003חזקתו\u0004 של החלוק שהוא \u0003בדוק,\u0004 שוודאי הוא שבשעה שמכבסים את החלוק, בודקים אותו היטב אם יש בו כתם. ומשום כך כל הטהרות שנגעה בהן האשה עד שעת הכיבוס, אינן נטמאות. \u0003או דלמא\u0004 \u0005[שמא]\u0006 הכוונה היא ש\u0003חזקתו\u0004 של החלוק שהוא \u0003מתכבס,\u0004 ואילו היה שם כתם, היה יוצא הכתם עם הכביסה?","\u0003ו\u0004מסבירים: \u0003מאי נפקא מינה\u0004 \u0005[מה יוצא מזה,\u0006 אם נאמר כצד זה או כצד זה\u0005]\u0006 — במקרה ש\u0003אמר\u0004 כי אמנם \u0003כיבס\u0004 את החלוק, \u0003ולא בדק\u0004 אם יש בו כתם. ומעתה: \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהוא משום ש\u0003חזקתו\u0004 של החלוק המכובס שהוא גם \u0003בדוק\u0004 — במקרה זה \u0003הא\u0004 \u0005[הרי]\u0006 אומר המכבס כי \u0003לא בדק\u0004 את החלוק. ואולם \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שהוא משום ש\u0003חזקתו\u0004 של חלוק שהוא \u0003מתכבס,\u0004 ובשעה שכובס יצא הכתם עם הכביסה — \u0003הא\u0004 \u0005[הרי]\u0006 אף במקרה זה החלוק \u0003מתכבס.\u0004","\u0003אי נמי\u0004 \u0005[אם גם כן]\u0006 עוד אופן שיש בו הבדל הלכתי בין שתי האפשרויות הללו בהבנת דברי משנתנו — במקרה — \u0003דאשתכחה בסטרא\u0004 \u0005[שנמצא\u0006 הכתם \u0005בצד]\u0006 של החלוק, במקום שיש בו קפלים ותפירות. ומעתה: \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 בטעם טהרתן משום ש\u0003חזקתו\u0004 של החלוק המתכבס שהוא גם \u0003בדוק\u0004 — אף במקרה זה יש לטהר את הטהרות שנגעה בהן לפני הכיבוס, שכן \u0003מאן דבדק\u0004 \u0005[מי שבודק]\u0006 — \u0003בסטרא נמי בדיק\u0004 \u0005[בצד\u0006 הבגד הריהו \u0005גם כן בודק].\u0006 ואולם \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 בטעם טהרתן של הטהרות שנגעה בהן לפני הכיבוס שהוא משום ש\u0003חזקתו\u0004 של חלוק שהוא \u0003מתכבס,\u0004 ובשעה שמתכבס יצא הכתם עם הכיבוס — אין הדברים אמורים אלא בגוף החלוק, ואולם \u0003בסטרא\u0004 \u0005[בצד]\u0006 הבגד \u0003לא מתכבס.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 התשובה לבעיה זו שבדין השרץ ובדין הכתם? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003מאיר: מפני מה אמרו\u0004 חכמים כי \u0003השרץ שנמצא במבוי מטמא למפרע, עד שיאמר\u0004 אדם \u0003\"בדקתי את המבוי הזה, ולא היה בו שרץ\",\u0004 שבכגון זה כל הטהרות שהיו במבוי קודם לשעת הבדיקה טהורות \u0003או עד שעת כיבוד\u0004 — \u0003מפני שחזקת בני ישראל\u0004 שהריהם \u0003בודקין\u0004 את \u0003מבואותיהן בשעת כבודיהם.\u0004 \u0003ו\u0004לכך \u0003אם לא בדקו\u0004 את המבוי בשעה שכיבדוהו — \u0003הפסידוהו\u0004 בטומאת הטהרות שהיו בו \u0003למפרע,\u0004 עד השעה שבה נבדק המבוי.","\u0003ו\u0004כיוצא בדבר, \u0003מפני מה אמרו\u0004 חכמים כי \u0003כתם שנמצא בחלוק מטמא למפרע, עד שיאמר \"בדקתי את החלוק ולא היה בו כתם\", א\u0004 \u0003ו עד שעת הכבוס\u0004 — \u0003מפני שחזקת בנות ישראל\u0004 שהריהן \u0003בודקות\u0004 את \u0003חלוקיהן בשעת כבוסיהן.\u0004 \u0003ואם לא בדקו\u0004 את החלוק בשעה שכבסוהו — \u0003הפסידו\u0004 את הטהרות שנגעה בהן \u0003למפרע\u0004 עד שעה שבדקה.","\u0003ר' אחא אמר:\u0004 אף זו שלא בדקה את חלוקה בשעה שכיבסתו, ולאחר מכן נמצא בו כתם, ואין ידוע אם היה הכתם מלפני הכיבוס, יש לה תקנה — \u0003תחזור ותכבסנו.\u0004 \u0003אם נדחה\u0004 (השתנה) \u0003מראיתו\u0004 של הכתם בעקבות כיבוס זה — \u0003בידוע שלאחר\u0004 ה\u0003כבוס\u0004 הקודם בא הכתם בחלוק. ולכך, הכיבוס הנוכחי שינה את מראיתו. ומשום כך אין נטמאות הטהרות שנגעה בהן לפני הכיבוס הקודם. \u0003ואם לאו\u0004 \u0005[לא]\u0006 השתנה מראיתו של הכתם בעקבות הכיבוס הנוכחי — \u0003בידוע שלפני הכבוס\u0004 הקודם בא הכתם בחלוק, ולכך הטהרות שנגעה בהן לפני הכיבוס הקודם טמאות.","\u0003רבי אומר\u0004 כי ניתן להבחין בכתם עצמו אם הוא מלפני כיבוס או לאחריו. שכן \u0003אינו דומה\u0004 מראהו של \u0003כתם שלאחר הכבוס ל\u0004מראהו של \u0003כתם שלפני הכבוס, שזה\u0004 (הכתם שלאחר כיבוס) הריהו \u0003מקדיר\u0004 (חודר לבגד), \u0003ו\u0004אילו \u0003זה\u0004 (הכתם שלפני כיבוס) הריהו \u0003מגליד\u0004 (נפרד מהבגד). ומעתה \u0003שמע מינה\u0004 \u0005[למד מכאן,\u0006 מדברי הברייתא\u0005]\u0006 שנמצא \u0003כי\u0004 \u0003חזקתו\u0004 של המבוי המתכבד ושל החלוק המתכבס שהוא \u0003בדוק.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]!\u0006","\u0003ו\u0004עוד שנינו במשנתנו כי השרץ הנמצא במבוי או הכתם הנמצא בחלוק \u0003מטמא\u0004 למפרע (עד שעת כיבוד או כיבוס) \u0003בין\u0004 שהוא עתה \u0003לח ו\u0004בין שהוא עתה יבש. ואילו ר' שמעון סבור כי היבש אמנם מטמא למפרע, ואולם הלח אינו מטמא למפרע אלא בשיעור זמן שעדיין יכול להיות לח. ובהסבר דברי ר' שמעון \u0003אמר ר'\u0004 \u0003אלעזר: לא שנו\u0004 — \u0003אלא\u0004 לענין ה\u0003שרץ\u0004 בלבד, \u0003אבל\u0004 ה\u0003כתם\u0004 ה\u0003לח\u0004 — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מטמא למפרע\u0004 לדעת ר' שמעון. שכן \u0003אימר\u0004 \u0005[אמור]\u0006 ש\u0003יבש היה\u0004 לפני כן, \u0003ומיא נפיל עליה\u0004 \u0005[ומים נפלו עליו]\u0006 וגרמו לו להיות עתה לח.","ושואלים על הסבר זה: \u0003שרץ נמי\u0004 \u0005[גם כן],\u0006 מדוע הלח אינו מטמא למפרע עד שעת כיבוד לדעת ר' שמעון, \u0003אימר\u0004 \u0005[אמור]\u0006 בו גם כן כי \u0003יבש היה ומיא נפיל עליה\u0004 \u0005[ומים נפלו עליו]\u0006 וגרמו לו להיות עתה לח. ומתרצים: אין לומר כן בשרץ, משום ש\u0003אם איתא דהכי\u0004 \u0005[יש,\u0006 אכן, \u0005שכך]\u0006 \u0003הוא\u0004 שאירע — היה השרץ \u0003אמרטוטי אימרטט\u0004 \u0005[ממורט],\u0006 ולא כפי שהוא נראה עתה לפנינו.","\u0003כל הכתמין\u0004 הנמצאים על הבגדים \u0003הבאין מ\u0004העיר \u0003רקם\u0004 — \u0003טהורין.\u0004 שהם כתמים של גוים, שאין דמם מטמא. ואילו \u0003ר' יהודה מטמא\u0004 את הכתמים הללו, \u0003מפני שהם\u0004 (אנשי העיר רקם) אינם גוים אלא \u0003גרים,\u0004 והריהם מטמאים כישראל, \u0003ו\u0004אולם הריהם \u0003טועין\u0004 ואין הם מצניעים את כתמיהם. אבל הכתמים \u0003הבאין מבין הגוים\u0004 — \u0003טהורין.\u0004 ואילו הכתמים הבאים \u0003מבין\u0004 בני \u0003ישראל ומבין הכותים\u0004 — ר' \u0003מאיר מטמא\u0004 אותם, ומפני החשש שהם של ישראל, \u0003ו\u0004אילו \u0003חכמים מטהרים\u0004 אותם \u0003מפני שלא נחשדו\u0004 ישראל \u0003על\u0004 שאינם מצניעים את \u0003כתמיהן.\u0004","שנינו במשנתנו כי הכתמים הבאים מבין הגוים טהורים, ו\u0003קפסיק ותני\u0004 \u0005[פוסק,\u0006 התנא, חותך דבריו בהחלט, \u0005ושונה]\u0006 בלא להבחין בין מקומות הגוים השונים. ובכללם, \u0003אפילו\u0004 הכתמים הבאים \u0003מ\u0004הגוים הגרים ב\u0003תרמוד.\u0004 \u0003אמר ר'\u0004 \u0003יוחנן, זאת אומרת\u0004 (מכאן ראיה) כי \u0003מקבלין גרים מתרמוד,\u0004 כיון שהם צאצאי גוים גמורים, ואין לחשוש שמא הם מבני בניהם של בנות עשרת השבטים שגלו בימי בית ראשון.","ותוהים על כך: \u0003איני\u0004 \u0005[האמנם]\u0006 כך היא דעת ר' יוחנן, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר' יוחנן וסביא\u0004 \u0005[והזקנים]\u0006 \u0003דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כי \u0003אין מקבלין גרים מתרמוד!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בתשובה כי ר' יוחנן לא אמר אלא ש\u0003\"זאת\u0004 אומרת\", שכך עולה מדברי משנתנו, \u0003ו\u0004אולם הוא עצמו \u0003לא סבירא ליה\u0004 \u0005[אינו סבור]\u0006 כדברי המשנה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן\u0004 כלל ש\u0003הלכה\u0004 היא \u0003כ\u0004דברי \u0003סתם משנה\u0004 (משנה השנויה באופן סתום, בלא ייחוס ההלכה בה לחכם מסויים), ואף משנתנו הריהי סתם משנה!","ומשיבים: \u0003אמוראי נינהו\u0004 \u0005[אמוראים הם]\u0006 שנחלקו בדבר \u0003ואליבא\u0004 \u0005[ולשיטת]\u0006 \u0003ר' יוחנן.\u0004 שלדעת אמורא אחד ר' יוחנן סבור שאין מקבלים גרים מתרמוד, ואין מדברי משנתנו להביא ראיה שמקבלים גרים מהם. ואמורא אחר סבור שממשנתנו יש להביא ראיה שמקבלים גרים מתרמוד, ולא אמר ר' יוחנן שאין מקבלים מהם גרים.","שנינו במשנתנו כי נחלקו חכמים ור' מאיר בדין הכתמים הבאים \u0003מבין ישראל\u0004 ומבין הכותים. ודנים: בדעת חכמים \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 המטהרים, \u0003אי\u0004 \u0005[אם]\u0006 כתמים של \u0003ישראל\u0004 הם \u0003מטהרי\u0004 \u0005[מטהרים],\u0006 כתמים \u0003דמאן מטמו\u0004 \u0005[של מי\u0006 הם \u0005מטמאים]?\u0006","ומשיבים: \u0003חסורי מחסרא, והכי קתני\u0004 \u0005[חסרים\u0006 הם דברי המשנה, \u0005וכך היא שנויה]:\u0006 כתם הבא \u0003מבין ישראל\u0004 — הריהו \u0003טמא,\u0004 ובכך הושוו כל הדעות. ואילו כתם הבא \u0003מבין הכותים\u0004 — \u0003ר' מאיר מטמא\u0004 אותו. וטעמו: מפני ש\u0003כותים גרי אמת הן,\u0004 ויש להם דין של יהודים שכתמיהם מטמאים. \u0003ו\u0004אילו \u0003חכמים מטהרין\u0004 את הכתם. וטעמם: מפני ש\u0003כותים גרי אריות הן.\u0004 והריהם נחשבים כגוים, שאין כתמיהם מטמאים.","ושואלים על הסבר זה: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, מדוע אמרו חכמים במשנתנו כי הכתמים הללו טהורים מפני \u0003שלא נחשדו\u0004 הכותים \u0003על כתמיהן\u0004 — מפני שהם \u0003גרי אריות מבעי ליה\u0004 \u0005[נצרך להם]\u0006 לומר!","\u0003אלא הכי קאמר\u0004 \u0005[כך\u0006 משנתנו \u0005היא אמורה]:\u0006 כתמים הבאים \u0003מבין ישראל ומבין הכותים\u0004 — \u0003טמאין,\u0004 מפני שה\u0003כותים גרי אמת הן.\u0004 כתמים \u0003הנמצאין בערי ישראל\u0004 — \u0003טהורין,\u0004 מפני \u0003שלא נחשדו\u0004 ישראל \u0003על\u0004 כך שאינם מצניעים את \u0003כתמיהם, ו\u0004בודאי \u0003אצנועי מצנעי להו\u0004 \u0005[מצניעים\u0006 הם \u0005אותם],\u0006 וכתמים אלה ודאי של גוים.","ואילו כתמים \u0003הנמצאין בערי כותים\u0004 — \u0003ר' מאיר מטמא\u0004 אותם, מפני ש\u0003נחשדו\u0004 הכותים \u0003על\u0004 אי הצנעת \u0003כתמיהם, ו\u0004אילו \u0003חכמים מטהרין\u0004 אותם, מפני \u0003ש\u0004אף הכותים \u0003לא נחשדו על\u0004 אי הצנעת \u0003כתמיהן,\u0004 ובודאי כתם זה הוא משל גוים.","\u0003כל הכתמים הנמצאים בכל מקום\u0004 שגרים בו גוים ובני ישראל — \u0003טהורין,\u0004 שאין אלה משל בני ישראל, המצניעים את כתמיהם. \u0003חוץ מן\u0004 הכתמים \u0003הנמצאים בחדרים\u0004 (שהם מקומות מוצנעים בבית), שיש לחשוש שהם מאלה שהצניעום בני ישראל, \u0003ו\u0004כן הכתמים הנמצאים \u0003בסביבות בית הטמאות\u0004 (מקום בו נמצאות הנשים בימי נדותן).","\u0003בית הטמאות של\u0004 ה\u0003כותים מטמאין ב\u0004טומאת \u0003אהל\u0004 (הנוהגת במקום המאהיל על המת), \u0003מפני שהם\u0004 הכותים \u0003קוברין שם את הנפלים.\u0004 \u0003ר'\u0004 \u0003יהודה אומר:\u0004 בית הטומאות של הכותים אינו מטמא באהל מפני ש\u0003לא היו\u0004 הכותים \u0003קוברין\u0004 שם את הנפלים, \u0003אלא משליכין\u0004 אותם החוצה, \u0003ו\u0004ה\u0003חיה\u0004 היתה \u0003גוררתו\u0004 משם.","ועוד בדינם של הכותים: \u0003נאמנים\u0004 הם \u0003לומר \"קברנו שם\u0004 (במקום מסוים) \u0003את הנפלים\",\u0004 והריהו איפוא מטמא בטומאת המת. \u0003או\u0004 שאמרו \u0003\"לא קברנו\u0004 שם את הנפלים\", ומקום זה איפוא טהור. וכן \u0003נאמנים\u0004 הם \u0003לומר על הבהמה אם בכרה\u0004 כבר, ואין לולד שיוולד לה דין בכור. או \u0003אם לא בכרה\u0004 עדיין, והוולד שיוולד לה הריהו בכור. וכן הריהם \u0003נאמנים על ציון קברות,\u0004 המורה שמקום מסויים הוא מקום קבורת אדם.","\u0003ו\u0004אולם \u0003אין\u0004 הם \u0003נאמנין לא על הסככות\u0004 (עצים שענפיהם סוככים על הקרקע, ומאהילים עליה), \u0003ו\u0004כן הם \u0003לא\u0004 נאמנים \u0003על הפרעות\u0004 (בליטה היוצאת מהגדר, ומאהילה על הנמצא תחתיה). שאם יודעים אנו כי נמצא מת מתחת לאחד הענפים שבעץ, או מתחת לאחת הבליטות שבגדר, והנמצא תחתיהם הוא איפוא טמא — אין הכותים נאמנים לומר על ענף או בליטה מסויימים כי הם המאהילים על המת. \u0003ו\u0004כן הכותים \u0003לא\u0004 נאמנים בדבריהם \u0003על בית הפרס\u0004 (מקום שנחרש בו קבר, והריהו מטמא מגזירת חכמים עד מאה אמה מסביב למקום הקבר, מפני החשש שנגררו מעצמות המת על ידי המחרשה והגיעו לאותו מקום).","\u0003זה הכלל\u0004 הקובע לענין נאמנותם של הכותים: בכל \u0003דבר ש\u0004הריהם \u0003חשודים בו\u0004 שאין הם מקיימים אותו — \u0003אין\u0004 הם \u0003נאמנין עליו.\u0004"],["שנינו במשנתנו כי הכותים אינם נוהגים מנהג קבורה בנפליהם. ושואלים: \u0003מאי דרוש\u0004 \u0005[מה דרשו]\u0006 כמקור למנהגם זה? ומשיבים: לדעתם הכתוב \u0003\"לא תסיג גבול רעך אשר גבלו ראשנים בנחלתך\"\u0004 (דברים יט, יד) נדרש על ידי חכמים לענין המוכר את אחוזת קברות אבותיו לאדם זר.","ולמדו מכאן הכותים כי \u0003כל\u0004 מי \u0003שיש לו נחלה,\u0004 קרקע הבאה לו בירושה מאבותיו — \u0003יש לו גבול\u0004 (אחוזת קבר), ואילו \u0003כל\u0004 מי \u0003שאין לו נחלה\u0004 בארץ, כנפלים הללו, שלא באו לכלל חיים — אף \u0003אין לו גבול.\u0004 ומכאן הסיקו שאין נוהגת בהם מצות קבורה.","שנינו במשנתנו כי הכותים \u0003נאמנים לומר\u0004 \u0003\"קברנו\u0004 במקום מסויים את הנפלים\". ותוהים על כך: \u0003והא לית להו\u0004 \u0005[והרי אין להם,\u0006 אין הם מקבלים\u0005]\u0006 את הנאמר בתורה \u0003\"ולפני עור לא תתן מכשל\"\u0004 (ויקרא יט, יד), וכדרך שדרשו חכמים את הכתוב שבמשמעו אף איסור הכשלת אחר בדבר עבירה? ומדוע נאמנים בדבר זה? \u0003אמר ר'\u0004 \u0003אבהו\u0004 בתשובה: מדובר רק \u0003ב\u0004אופן שבו \u0003כהן\u0004 כותי \u0003עומד שם\u0004 באותו מקום, והרי זו ראיה שאכן אין המקום הזה טמא בטומאת המת.","ושואלים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003כהן טמא הוא\u0004 מכבר? ומשיבים: במשנתנו מדובר בכהן כותי טהור העומד שם \u0003דנקיט\u0004 \u0005[שמחזיק]\u0006 הוא \u0003תרומה בידיה\u0004 \u0005[בידו].\u0006 \u0003ו\u0004שואלים: עדיין אין זו ראיה, כי \u0003דילמא\u0004 \u0005[שמא]\u0006 \u0003תרומה טמאה היא?\u0004 ומשיבים: מדובר \u0003דקאכיל מינה\u0004 \u0005[שהוא אוכל ממנה],\u0006 ובודאי אינה תרומה טמאה, האסורה באכילה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 המשנה מדברת דווקא באופן שברור לנו שאין המקום טמא, מעתה \u0003מאי למימרא\u0004 \u0005[מה\u0006 באה המשנה \u0005לומר]\u0006 לנו? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 שתניח\u0005],\u0006 כי הכותים \u0003לא בקיאי\u0004 \u0005[אינם בקיאים,\u0006 יודעים היטב\u0005]\u0006 \u0003ביצירה\u0004 של האדם, וכאשר הם קוברים נפל, אינם יודעים שהוא בן ארבעים יום, שסבורים הם שאין זה אלא כמים בלבד, שאינו מטמא, ולא נסמוך עליהם בדבר זה. לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 התנא \u0005משמיע לנו]\u0006 שהם נאמנים בדבר, שכן הריהם בקיאים ביצירה.","עוד שנינו כי הכותים \u0003נאמנין על הבהמה\u0004 לענין דין בכורה בוולד שיוולד לה מעתה. \u0003ו\u0004תוהים על כך: \u0003והא לית להו\u0004 \u0005[והרי אין להם,\u0006 אין הם מקבלים\u0005]\u0006 את הנאמר בתורה \u0003\"ולפני עור לא תתן מכשל\",\u0004 וכיצד סומכים אנו עליהם לענין דין הבכור? \u0003אמר ר'\u0004 \u0003חייא בר אבא, אמר ר'\u0004 \u0003יוחנן\u0004 בהסבר הדברים: מדובר כאן רק \u0003ב\u0004אופן שבו הכותי עצמו \u0003גוזז ועובד\u0004 בוולד זה. ומכיון שהכותים לעצמם שומרים את דיני התורה, ראיה היא שאין זה בכור.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 פירוש המשנה, שהכותים נאמנים לענין בכור רק באופן שברור לנו שאין זה בכור, מעתה \u0003מאי למימרא\u0004 \u0005[מה\u0006 באה המשנה \u0005לומר]\u0006 לנו? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 שתניח\u0005],\u0006 שהכותים \u0003לא בקיאי\u0004 \u0005[אינם בקיאים,\u0006 יודעים היטב\u0005]\u0006 \u0003בטינוף\u0004 היוצא מן הבהמה שמא בא ממיחוי ולד והריהו פוטר אותה מן הבכורה. ומכיון שאינם בקיאים בו יש לחשוש שמא הם טועים וסבורים שהיה זה טינוף, ופטורה היא מן הבכורה. לכך \u0003קא משמע לן\u0004 \u0005[הוא\u0006 התנא \u0005משמיע לנו]\u0006 שהריהם בקיאים בטינוף, ומשום כך הריהם נאמנים לענין הבכורה.","עוד שנינו כי הכותים \u0003נאמנין על ציון\u0004 קברות. שאף הכותים מציינים את קברותיהם, וכל מקום שאין בו ציון נחשב כמקום טהור, וניתן לעשות בו טהרות. \u0003ו\u0004מסבירים: \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שחובת ציון הקברות רק \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003הוא, כיון דכתיבא\u0004 \u0005[שכתוב]\u0006 כן במקרא, הריהם \u0003מזהר זהירי ביה\u0004 \u0005[נזהרים בו],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בתיאור קבורתם של גוג והנלוים עליו \"ועברו העוברים בארץ \u0003וראה עצם אדם ובנה אצלו ציון\u0004 עד קברו אותו המקברים אל גיא המון גוג\" (יחזקאל לט, טו).","עוד שנינו במשנתנו: \u0003אבל אין\u0004 הכותים \u0003נאמנין לא על הסככות\u0004 ולא על הפרעות. ומבררים עניינן של אלה: \u0003סככות\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו],\u0006 \u0003אלו הן סככות\u0004 — \u0003אילן המיסך\u0004 (המצל) \u0003על\u0004 \u0003הארץ.\u0004 \u0003פרעות\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו],\u0006 \u0003אבנים פרעות\u0004 (חשופות ובולטות) \u0003היוצאות מן הגדר.\u0004","שנינו במשנתנו כי אין הכותים נאמנים אף על \u0003בית הפרס.\u0004 ובענין דינו של בית הפרס \u0003אמר רב, אמר רב שמואל:\u0004 החשש בבית הפרס הוא לעצמות המת שהתפזרו סביב על ידי החרישה, ולא לבשר המת. ואין עצם המת (ששיעורה הוא לפחות כשעורה) מטמאת בטומאת אהל, אלא במגע ובמשא בלבד. ולכך \u0003מנפח\u0004 (נופח רוח, מנפנף) \u0003אדם\u0004 לפני דרכו העוברת בתוך \u0003בית הפרס,\u0004 כדי שלא יגע בעצם, \u0003והולך\u0004 בה. אף שיתכן שהוא מאהיל על עצמות המת.","ועוד בענין בית הפרס, \u0003רב יהודה בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה אמר: בית הפרס שנידש\u0004 ברגלי אדם שהלכו בו לרוב, ומסתבר שנשחקו העצמות — הריהו \u0003טהור.\u0004 \u0003ותנא\u0004 \u0005[ושנה]\u0006 בברייתא עוד בדיני בית הפרס: \u0003החורש\u0004 את \u0003בית הקברות\u0004 — \u0003הרי זה עושה\u0004 אותו בכך ל\u0003בית הפרס.\u0004 \u0003ועד כמה הוא עושה\u0004 אותו לבית הפרס, עד היכן יש לחשוש שהגיעו לשם מן העצמות שהתפזרו? — \u0003מלא מענה\u0004 (שיעור תלם הנחרש בחרישה אחת), וכמה הוא שיעור זה? \u0003מאה אמה\u0004 אורך על מאה אמה רוחב, שהוא \u0003בית\u0004 (שטח המכיל) \u0003ארבעת סאין.\u0004 \u0003רבי יוסי אומר:\u0004 שיעור שטח בית הפרס הריהו \u0003חמש\u0004 סאים. ושואלים על הנאמר במשנתנו שאין הכותים נאמנים להעיד על בית הפרס, ועל הסככות: \u0003ו\u0004האם אכן הם \u0003לא מהימני\u0004 \u0005[לא נאמנים]\u0006 בכך, \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שדה שאבד בה קבר\u0004 (היא בית הפרס) — \u0003נאמן כותי לומר \"אין שם קבר\",\u0004 \u0003לפי ש\u0004הוא \u0003אינו מעיד אלא על גופו של קבר.\u0004 שכיון שאומר הכותי שאין קבר בצד זה של השדה — הריהו כמעיד על גופו של קבר, וטומאת הקבר הריהי מן התורה, ובדבר שהוא מן התורה נאמנים הכותים. וכיוצא בזה ב\u0003אילן שהוא מיסך על הארץ\u0004 (\"סככות\") — \u0003נאמן\u0004 הכותי \u0003לומר \"אין תחתיו קבר\".\u0004 ומאותו הטעם: \u0003לפי ש\u0004הוא \u0003אינו מעיד אלא על גופו של קבר.\u0004 הרי שהכותים נאמנים על הסככות והפרעות! \u0003אמר ר'\u0004 \u0003יוחנן\u0004 בתשובה: אין דברי הברייתא הללו אמורים אלא \u0003במהלך ובא\u0004 הכותי \u0003על פני כולה,\u0004 שבאופן זה ודאי הוא שאם היה בה קבר, נטמא בו. ואם הוא נוהג כן בשדה, ניתן לסמוך על דבריו בטהרתו של המקום. ואילו דברי משנתנו עניינם שאין הכותי מהלך ושב על פני כולה, ובאופן זה אינו נאמן להעיד.","","","","ותוהים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שרק באופן זה הריהו נאמן להעיד, \u0003מאי למימרא\u0004 \u0005[מה\u0006 באה הברייתא \u0005לומר]\u0006 והלא אין כל חידוש בדבר? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 כי מתוך השדה \u0003רצועה\u0004 צרה של אדמה \u0003נפקא\u0004 \u0005[יוצאת]\u0006 לשדה סמוכה (ונקראת אותה שדה נספחת על שם שדה זו), ושם הכותי תולה שנמצאת בה הטומאה, ואילו בשדה זו שלפנינו הוא עובר הלוך ושוב, משום שאין היא אלא ספק טמאה, ולספק אין הוא חושש. לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 התנא שבברייתא \u0005משמיע לנו]\u0006 שאין חוששים לכך, וסומכים על דברי הכותי כשהוא מהלך על פני כולה.","שנינו במשנה: \u0003זה הכלל,\u0004 כל דין שחשודים בו הכותים שאין הם מקיימים אותו, אף אינם נאמנים להעיד עליו. ושואלים: הלשון \u0003\"זה הכלל\",\u0004 שהיא לשון ריבוי, \u0003לאתויי מאי\u0004 \u0005[לרבות\u0006 את \u0005מה]\u0006 היא באה? \u0003לאתויי\u0004 \u0005[לרבות]\u0006 שאין הכותים נאמנים אף לענין \u0003תחומין\u0004 של שבת, להעיד שעד מקום מסויים מגיע תחום שבת (שכן תחומים הם מדברי חכמים), \u0003ו\u0004לענין \u0003יין נסך,\u0004",""],["אשה \u0003הרואה כתם\u0004 דם \u0003על בשרה\u0004 \u0003כנגד\u0004 (מול) \u0003בית התורפה\u0004 (בית הערוה) — הריהי \u0003מטמאה,\u0004 שיש לחשוש שבא דם זה מן המקור, והריהו דם נדה. ואם נראה הכתם \u0003שלא כנגד בית התורפה\u0004 — הריהי \u0003טהורה,\u0004 שודאי לא בא מן המקור. נמצא הכתם \u0003על עקבה\u0004 (אחורי כף רגלה), \u0003ו\u0004כן אם נמצא \u0003על ראש\u0004 אצבע \u0003גודלה\u0004 (אגודל), שהוא בקדמת כף רגלה — אף שאינם מול מקום הערוה, הריהי \u0003טמאה,\u0004 שיכול דם הבא מן המקור להגיע למקומות אלה.","נמצא הכתם \u0003על שוקה\u0004 של האשה, \u0003ו\u0004כן אם נמצא \u0003על פרסותיה,\u0004 דינה משתנה לפי המקום בו בדיוק נמצא הכתם, שאם נמצא \u0003מבפנים\u0004 (מקדמת הגוף) — הריהי \u0003טמאה,\u0004 שכן אפשרי שיגיע למקום זה דם הבא מן המקור. ואולם אם נמצא \u0003מבחוץ\u0004 (לאחורי גופה) — הריהי \u0003טהורה, ו\u0004כן אם נמצא \u0003על הצדדין, מכאן ומכאן\u0004 — הריהי \u0003טהורה,\u0004 שכן אין אפשרות שיגיע דם היוצא מן המקור למקומות הללו.","\u0003ראתה\u0004 כתם דם \u0003על חלוקה,\u0004 אם נמצא הכתם \u0003מן החגור\u0004 של החלוק \u0003ולמטה\u0004 — הריהי \u0003טמאה,\u0004 שיכול הדם היוצא מן המקור להגיע לשם. ואולם אם נמצא \u0003מן החגור ולמעלה\u0004 — הריהי \u0003טהורה,\u0004 שאין הדם היוצא מן המקור יכול להגיע לשם. ואם \u0003ראתה\u0004 כתם דם \u0003על בית יד\u0004 (שרוול) \u0003של\u0004 ה\u0003חלוק, אם מגיע\u0004 אורכו של בית היד עד \u0003כנגד\u0004 (מול) \u0003בית התורפה\u0004 — הריהי \u0003טמאה,\u0004 וכגון שנמצא הכתם בראש בית היד, שכן לפעמים היא מפשילה את השרוול מעל ידה, והריהו מגיע אל מול בית התורפה, ומשם הגיע הדם אליו. \u0003ואם לאו\u0004 \u0005[אין]\u0006 ראש השרוול מגיע עד בית התורפה — הריהי \u0003טהורה,\u0004 שהרי ברור כי אין דם זה בא מן המקור.","וזהו דווקא בחלוק המשמש ללבוש בלבד, ואולם אם \u0003היתה פושטתו ומתכסה בו בלילה,\u0004 שהריהו משמש אף כשמיכה — ב\u0003כל מקום שנמצא בו כתם,\u0004 הריהי \u0003טמאה, מפני ש\u0004בשעה שהיא מתכסה בו \u0003הוא חוזר\u0004 (מסתובב, משנה את מיקומו על גוף השוכב תחתיו), וייתכן שהמקום בו נמצא הכתם היה מול בית התורפה והרי זה דם מן המקור. \u0003וכן\u0004 הוא הדין בכתם הנמצא \u0003בפוליוס\u0004 (סודר הנתון על הראש), שבכל מקום שנמצא בו כתם דם הריהי נטמאת בו, ומשום שהפוליוס עשוי שיסתובב לו.","שנינו במשנתנו אופנים שונים של הכתם הנמצא לענין טומאתה או טהרתה. ועוד בענין זה \u0003אמר שמואל: בדקה\u0004 האשה את \u0003קרקע עולם\u0004 (האדמה שמתחתיה) אם הריהו נקי (מדם, ושאר דברים), ולא מצאה בו דבר. \u0003ו\u0004אחר כך \u0003ישבה עליה, ומצאה דם עליה\u0004 (על הקרקע), אף שלכאורה ממנה בא דם זה — מכל מקום הריהי \u0003טהורה.\u0004 וטעם הדבר: \u0003ש\u0004כן \u0003נאמר\u0004 \"דם יהיה זובה \u0003בבשרה\u0004 שבעת ימים תהיה בנדתה\" (ויקרא טו, יט) — ללמדנו שאין האשה נטמאת כנדה \u0003עד שתרגיש בבשרה\u0004 שיצא דם ממקורה. ואשה זו, מאחר ולא הרגישה כן — אינה טמאה.","ותוהים: כיצד למד כן שמואל מהכתוב \"בבשרה\", והרי \u0003האי\u0004 \u0005[זה]\u0006 הכתוב \u0003\"בבשרה\"\u0004 — \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 לדרשה אחרת: \u0003שמטמאה\u0004 האשה בראיית דם שנמצא \u0003בפנים\u0004 גופה \u0003כ\u0004דם הנמצא \u0003בחוץ\u0004 לגופה. שכיון שיצא הדם מהמקור אל הפרוזדור — הריהי טמאה! ומשיבים: \u0003אם כן\u0004 הוא שהכתוב בא ללמד רק לענין שמטמאה בפנים כבחוץ, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 רק \u0003\"בבשר\", מאי\u0004 \u0005[מה]\u0006 בא ללמד לשון \u0003\"בבשרה\"\u0004 — \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי אין האשה נטמאת \u0003עד שתרגיש בבשרה\u0004 את יציאת הדם מהמקור.","ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 הכתוב הזה לדרשה אחרת. שכן שנינו: \u0003\"בבשרה\"\u0004 — בלשון מיעוט, להורות כי דווקא באופן זה היא נטמאת, \u0003ולא\u0004 נטמאת בדם הנמצא \u0003בשפיר\u0004 (מעטפת העור בה נתון העובר במעי אמו), \u0003ולא\u0004 בדם הנמצא \u0003בחתיכה\u0004 לא מזוהה שיצאה ממנה. ומשיבים: \u0003תרתי שמע מינה\u0004 \u0005[שתי\u0006 דרשות \u0005נלמד מכאן\u0006\u0005].\u0006","ובענין דינו זה של שמואל, מציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ממה ששנינו במשנה שבתחילת הפרק הבא\u0005]:\u0006 \u0003האשה שהיא עושה\u0004 את \u0003צרכיה, ו\u0004בתוך כך \u0003ראתה דם.\u0004 \u0003ר'\u0004 \u0003מאיר אומר: אם\u0004 הטילה את מימיה כשהיא \u0003עומדת\u0004 — הריהי \u0003טמאה,\u0004 שכן באופן זה, ישנה אפשרות שחזרו מי הרגלים אל המקור ונשאו משם דם. \u0003ו\u0004אולם \u0003אם\u0004 הטילה מימיה כשהיא \u0003יושבת\u0004 — הריהי \u0003טהורה,\u0004 שכן במצב שכזה אין אפשרות שיצא דם מהמקור אל מי הרגלים. ובוודאי הרי זה דם פצע שיש לה באיזור הגוף בו היא מטילה את מי רגליה.","ויש לברר את הדבר: \u0003היכי דמי\u0004 \u0005[איך בדיוק]\u0006 היה הדבר? \u0003אי דארגשה\u0004 \u0005[אם\u0006 כשהטילה מימיה \u0005הרגישה]\u0006 האשה ביציאת דם מהמקור — כשהטילה מימיה כשהיא \u0003יושבת אמאי\u0004 \u0005[מדוע]\u0006 היא \u0003טהורה,\u0004 והרי הרגישה שיצא הדם מהמקור! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר באופן \u0003דלא ארגשה\u0004 \u0005[שלא הרגישה]\u0006 ביציאת הדם, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנינו]\u0006 שאם הטילה מימיה כשהיא \u0003עומדת\u0004 — הריהי \u0003טמאה.\u0004 ושלא כדברי שמואל.","ודוחים: אין להביא ראיה מכאן, שכן \u0003לעולם\u0004 נאמר כי מדובר באופן \u0003דארגשה\u0004 \u0005[שהרגישה]\u0006 ביציאת הדם, \u0003ו\u0004אולם כיון שבאה הרגשה זו עם הטלת מים, \u0003אימור\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 כי \u0003הרגשת מי רגלים הואי\u0004 \u0005[היתה\u0006 זו\u0005].\u0006 ומשום כך אם הטילה את מימיה כשהיא \u0003עומדת\u0004 — \u0003הדור\u0004 \u0005[חזרו]\u0006 \u0003מי רגלים למקור ואייתי\u0004 \u0005[והביאו]\u0006 עימם \u0003דם, ו\u0004אם הטילה את מימיה כשהיא \u0003יושבת,\u0004 שאין באופן זה אפשרות שישובו מי הרגלים אל המקור ויביאו משם דם — הריהי \u0003טהורה.\u0004 ואילו את ההרגשה שהרגישה אנו מייחסים למי הרגלים.","ומציעים עוד בבירור דינו של שמואל, \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה אחרת: \u0003עד\u0004 (פיסת בד שבודקת האשה את עצמה לטהרתה בה) \u0003שהיה נתון תחת הכר, ו\u0004לאחר מכן \u0003נמצא עליו דם, אם\u0004 הכתם \u0003עגול\u0004 — הרי זה דם \u0003טהור,\u0004 שאין מקום לחשוש כי דם זה הריהו ממה שנבדק על ידה. שכן הבדיקה נעשית בקינוח, והכתם הבא בעקבות קינוח אינו עגול. \u0003ואם\u0004 הכתם הינו \u0003משוך\u0004 (מארך) — הרי זה דם \u0003טמא,\u0004 שצורה זו יכולה להיווצר בבדיקה.","ועתה יש לברר דברים אלה: \u0003היכי דמי\u0004 \u0005[איך בדיוק]\u0006 המדובר: \u0003אי דארגישה\u0004 \u0005[אם שהרגישה]\u0006 ביציאת דם — כאשר הוא \u0003עגול אמאי\u0004 \u0005[מדוע]\u0006 הוא \u0003טהור? אלא לאו\u0004 \u0005[האם לא]\u0006 נאמר כי מדובר כאן \u0003דלא ארגישה\u0004 \u0005[שלא הרגישה]\u0006 ביציאת דם, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנינו]\u0006 כי כתם הדם שצורתו \u0003משוך\u0004 — הריהו \u0003טמא.\u0004 ושלא כדעת שמואל שאין האשה נטמאת אם לא הרגישה!","ודוחים: \u0003לא,\u0004 אין להביא ראיה מכאן שכן \u0003לעולם\u0004 נאמר כי מדובר באופן \u0003דארגישה\u0004 \u0005[שהרגישה],\u0006 \u0003ו\u0004אולם כיון שבאה הרגשה זו עם הבדיקה, \u0003אימור\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 כי \u0003הרגשת עד הואי\u0004 \u0005[היתה]\u0006 זו. ולכך אם היה הכתם \u0003משוך,\u0004 כצורה הנוצרת בעקבות הקינוח שבבדיקה — \u0003ודאי מגופה אתא\u0004 \u0005[בא]\u0006 דם זה. היה הכתם \u0003עגול,\u0004 שאין זו כצורה הנוצרת על ידי קינוח — הרי זה דם \u0003טהור.\u0004","\u0003ומציעים עוד:\u0004 \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] ראיה אחרת ממה ששנינו במשנה: אם \u0003נמצא\u0004 דם \u0003על\u0004 עד הבדיקה \u0003שלו,\u0004 לאחר התשמיש — האשה והבעל \u0003טמאין\u0004 טומאת שבעה, כדין הבא על הנדה, \u0003וחייבין\u0004 \u0003בקרבן\u0004 חטאת, כדין הבא על הנדה בשוגג. \u0003נמצא\u0004 דם \u0003על\u0004 עד הבדיקה \u0003שלה אתיום\u0004 (מיד) לאחר התשמיש — הבעל והאשה \u0003טמאין\u0004 טומאת שבעה בוודאי, \u0003וחייבין בקרבן\u0004 חטאת. ואולם אם \u0003נמצא\u0004 הדם \u0003על\u0004 עד הבדיקה \u0003שלה לאחר זמן\u0004 — אפשר שדם זה נראה רק לאחר התשמיש ולכן שניהם \u0003טמאים\u0004 טומאת שבעה \u0003מספק, ופטורין מן הקרבן.\u0004","ויש לברר: \u0003היכי דמי\u0004 \u0005[איך בדיוק]\u0006 המדובר: \u0003אי דארגישה\u0004 \u0005[אם שהרגישה]\u0006 ביציאת דם בשעת התשמיש — אף שנמצא \u0003לאחר זמן, אמאי\u0004 \u0005[מדוע]\u0006 שניהם \u0003פטורין מן הקרבן? אלא לאו\u0004 \u0005[האם לא]\u0006 נאמר כי מדובר כאן \u0003דלא ארגישה\u0004 \u0005[שלא הרגישה]\u0006 ביציאת הדם בשעת תשמיש, \u0003ו\u0004בכל זאת \u0003קתני\u0004 \u0005[שנינו]\u0006 כי בזמן ש\u0003נמצא על שלה אתיום\u0004 — הריהם \u0003טמאין וחייבין בקרבן,\u0004 ושלא כדברי שמואל! ודוחים: \u0003לא,\u0004 אין להביא ראיה מכאן, שכן \u0003לעולם\u0004 נאמר כי מדובר באופן \u0003דארגישה\u0004 \u0005[שהרגישה]\u0006 ביציאת הדם בשעת תשמיש, \u0003ו\u0004אולם כיון שבאה הרגשה זו עם כניסתו של איבר התשמיש (\"שמש\"), \u0003אימא\u0004 \u0005[\u0006יש מקום \u0005לומר]\u0006 כי \u0003הרגשת שמש הוה\u0004 \u0005[היתה]\u0006 זו.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת ממה ששנינו: \u0003נמצאת אתה אומר\u0004 כי ישנם \u0003שלשה ספקות באשה\u0004 שמצאה דם בבגדה או בחלוקה, נמצא כתם דם \u0003על בשרה,\u0004 והריהו \u0003ספק טמא ספק טהור\u0004 — הרי זה \u0003טמא,\u0004 ונטמאת היא בו. נמצא \u0003על חלוקה,\u0004 והריהו \u0003ספק טמא ספק טהור\u0004 — הרי זה \u0003טהור,\u0004 והריהי טהורה. \u0003ו\u0004כן אשה המוחזקת כספק נדה ונגעה או הסיטה טהרות, והספק איפוא \u0003במגעות ובהיסטות\u0004 אם טמאה בהן את הטהרות — \u0003הלך\u0004 (לך) \u0003אחר הרוב.\u0004","ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הלשון \u0003\"הלך אחר הרוב\"? לאו\u0004 \u0005[האם אין]\u0006 הכוונה ש\u0003אם\u0004 היו \u0003רוב ימיה\u0004 של אשה זו \u0003טמאין\u0004 שמרבה לראות דם — הריהי \u0003טמאה\u0004 מן הספק. ומתוך שנאמרו הדברים בלא הבחנה בין אם הרגישה ביציאת הדם או לא, נלמד שכך הדין, \u0003ואף על גב דלא ארגשה\u0004 \u0005[ואף על פי שלא הרגישה],\u0006 ושלא כשמואל!","ודוחים: \u0003לא,\u0004 אין להביא ראיה מכאן, שכן כוונת דברי הברייתא לומר ש\u0003אם רוב ימיה\u0004 של אשה זו \u0003בהרגשה\u0004 היא \u0003חזיא\u0004 \u0005[רואה]\u0006 — הריהי \u0003טמאה,\u0004 אף כשהיא מסופקת אם הרגישה וראתה, \u0003דאימור ארגשה ולאו אדעתה\u0004 \u0005[ש\u0006יש מקום \u0005לומר\u0006 כי \u0005הרגישה\u0006 גם במקרה זה, \u0005ו\u0006אולם לא עלה כן \u0005על דעתה\u0006 שהיא מרגישה\u0005].\u0006 ולפני שממשיכים בבירור דברי שמואל, נפנים לבירור דברי הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא כי אם נמצא הדם \u0003על בשרה, ספק טמא ספק טהור\u0004 — הרי זה דם \u0003טמא.\u0004 ואילו אם נמצא \u0003על חלוקה, ספק טמא ספק טהור\u0004 — הרי זה \u0003טהור.\u0004 ומשמע כי באותו אופן שהדם הנמצא בחלוק טהור, הנמצא על בשרה טמא.","ומבררים: \u0003היכי דמי\u0004 \u0005[איך בדיוק]\u0006 היה הדבר? \u0003אי\u0004 \u0005[אם]\u0006 נמצא \u0003מ\u0004מקום ה\u0003חגור ולמטה\u0004 — \u0003על חלוקה אמאי\u0004 \u0005[מדוע]\u0006 \u0003טהור? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006 שאם נמצא \u0003מן החגור ולמטה\u0004 — הריהו \u0003טמא! ואי\u0004 \u0005[ואם]\u0006 נמצא \u0003מ\u0004מקום ה\u0003חגור ולמעלה,\u0004 שאינו מול מקום התורפה. ואם כן כשנמצא הדם מהחגור ולמעלה \u0003על בשרה אמאי\u0004 \u0005[מדוע]\u0006 הוא \u0003טמא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]\u0006 כי אם \u0003ראתה דם על בשרה שלא כנגד בית התורפה\u0004 — הריהי \u0003טהורה.\u0004","ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר בשנמצא הדם \u0003מחגור ולמטה, ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר בשנמצא \u0003מחגור ולמעלה,\u0004 ובשני האופנים הללו ניתן להסביר את דברי הברייתא. ומפרטים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר בשנמצא \u0003מחגור ולמטה.\u0004 והברייתא מדברת באופן שיש לתלות את הימצאות הדם בגורם חיצוני, ו\u0003כגון שעברה\u0004 אותה אשה \u0003בשוק של טבחים\u0004 (קצבים). ולכך, כאשר נמצא הדם \u0003על בשרה\u0004 — מניחים אנו כי \u0003מגופה אתאי\u0004 \u0005[בא]\u0006 הדם, \u0003דאי מעלמא אתאי\u0004 \u0005[שאם מהעולם,\u0006 מבחוץ \u0005בא]\u0006 — גם \u0003על חלוקה מיבעי ליה אשתכוחי\u0004 \u0005[צריך היה לו להימצא].\u0006 וכאשר נמצא הדם \u0003על חלוקה\u0004 — מניחים אנו כי \u0003מעלמא אתא\u0004 \u0005[מהעולם,\u0006 מבחוץ, \u0005בא].\u0006 ומשום, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מגופה אתא\u0004 \u0005[בא]\u0006 דם זה — גם \u0003על בשרה מיבעי ליה אשתכוחי\u0004 \u0005[צריך היה לו להימצא].\u0006","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר באופן שנמצא \u0003מחגור ולמעלה,\u0004 והטעם שהיא טמאה כשנמצא על חלוקה ולא על גופה — הברייתא מדברת באופן שיש להניח שבא הדם מגופה. ו\u0003כגון דאזדקרה\u0004 \u0005[שהזדקרה,\u0006 שזקפה את קומתה לאחור\u0005]\u0006. ולכך כשנמצא הדם \u0003על בשרה\u0004 — הריהי טמאה, כי מניחים אנו ש\u0003ודאי מגופה אתאי\u0004 \u0005[בא]\u0006 הדם לכאן. \u0003דאי מעלמא אתאי\u0004 \u0005[ש\u0006כן \u0005אם מהעולם,\u0006 מבחוץ \u0005בא]\u0006 — \u0003על חלוקה איבעי ליה אשתכוחי\u0004 \u0005[צריך היה לו להימצא].\u0006 וכאשר נמצא הדם \u0003על חלוקה\u0004 — מניחים אנו כי \u0003מעלמא אתא\u0004 \u0005[מהעולם,\u0006 מבחוץ, \u0005בא].\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מגופה אתא\u0004 \u0005[בא]\u0006 — גם \u0003על בשרה מיבעי ליה אשתכוחי\u0004 \u0005[צריך היה לו להימצא].\u0006","ושבים לבירור דינו של שמואל, \u0003קתני מיהת\u0004 \u0005[שנינו על כל פנים]\u0006 בברייתא זו שאם נמצא הדם \u0003על בשרה ספק טמא ספק טהור\u0004 — הרי זה דם \u0003טמא,\u0004 ומשמע שכך הדין \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא הרגישה,\u0004 והרי זה שלא כשמואל! \u0003ועוד\u0004 מביאים מה ש\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 כי \u0003הרואה כתם על בשרה כנגד בית התורפה\u0004 — הריהי \u0003טמאה,\u0004 ומשמע שכך הדין \u0003ואף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא הרגישה,\u0004 ושלא כדברי שמואל! \u0003אמר רב ירמיה מדפתי:\u0004 מה שאמר שמואל שאין האשה נטמאת אם לא הרגישה ביציאת הדם, אינו אלא מדין תורה. ואולם \u0003מודה שמואל שהיא,\u0004 האשה הרואה שלא בהרגשה, \u0003טמאה,\u0004"],["\u0003מדרבנן\u0004 \u0005[מדברי חכמים].\u0006 ובכל המקומות ששנינו בהם שהריהי טמאה אף שלא הרגישה (וכדרך שהקשו על שמואל במהלך הסוגיה) — טומאתה רק מדברי חכמים, ולא מדין תורה. ולכן אף לדעתו אשה שבדקה את הקרקע ומצאתה נקיה, והתישבה עליה ולאחר מכן מצאה בה דם, הריהי טמאה (מדברי חכמים), אף שלא הרגישה ביציאת הדם.","\u0003רב אשי אומר:\u0004 לדעת שמואל אשה זו טהורה אף מדברי חכמים. \u0003שמואל הוא\u0004 שאמר כר' נחמיה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 ש\u0003ר' נחמיה אומר: כל דבר שאינו מקבל טומאה\u0004 וכגון קרקע — אם נמצאו בו כתמי דם, \u0003אינו מקבל\u0004 טומאת \u0003כתמים.\u0004 שלא גזרו חכמים על הכתמים הנמצאים על דבר שאינו מקבל טומאה. ובכל המקומות ששנינו שהריהי טמאה אף שלא הרגישה — מדובר שנמצא כתם הדם על דבר המקבל טומאה.","ומקשים: \u0003בשלמא\u0004 \u0005[זה נוח]\u0006 להסברו של \u0003רב אשי\u0004 בשיטת שמואל — \u0003היינו דקאמר\u0004 \u0005[זהו שאמר]\u0006 שמואל את דינו דווקא כשנמצא הכתם על \u0003קרקע.\u0004 \u0003אלא ל\u0004הסברו של \u0003רב ירמיה\u0004 בשיטת שמואל — \u0003מאי איריא\u0004 \u0005[מה המכוון]\u0006 בדברי שמואל שהזכיר דווקא \u0003קרקע?\u0004 והלא \u0003אפילו\u0004 בנמצא הכתם על \u0003גלימא נמי\u0004 \u0005[גם כן]\u0006 כך הוא הדין, שהריהי טהורה (מדין תורה) אם לא הרגישה ביציאת הדם! ומתרצים: בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[לא נצרכה אמר].\u0006","ובאופן זה: \u0003לא מיבעיא\u0004 \u0005[לא נצרך]\u0006 לומר כי האשה שבדקה \u0003גלימא\u0004 ומצאתה טהורה, וישבה עליה, ולאחר מכן ראתה בה כתם דם, שאין היא נטמאת בכך— \u0003דלא מבדק שפיר\u0004 \u0005[ש\u0006הרי \u0005אין הגלימה נבדקת יפה,\u0006 היטב\u0005],\u0006 \u0003ו\u0004לכן \u0003איכא למימר\u0004 \u0005[יש\u0006 מקום \u0005לומר]\u0006 כי הכתם הזה שבגלימה \u0003מעלמא אתא\u0004 \u0005[מהעולם,\u0006 מבחוץ \u0005בא].\u0006 \u0003אלא אפילו\u0004 במקרה של \u0003קרקע, דמבדק שפיר\u0004 \u0005[שנבדקת\u0006 היא \u0005יפה],\u0006 \u0003דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 כי הכתם הזה שבקרקע \u0003מגופה אתיא\u0004 \u0005[בא],\u0006 ותטמא בו — לכך השמיענו שמואל כי אף באופן זה הרי זה דם \u0003טהור.\u0004","שנינו במשנתנו כי אם נמצא כתם הדם \u0003על עקבה ו\u0004כן אם נמצא \u0003על ראש גודלה\u0004 הריהי \u0003טמאה.\u0004 ודנים בדבר: \u0003בשלמא\u0004 \u0005[זה נוח,\u0006 מובן\u0005]\u0006 שכך הדין בנמצא הדם על \u0003עקבה\u0004 — שכן \u0003עביד\u0004 \u0005[עשוי,\u0006 אפשרי\u0005]\u0006 הדבר ש\u0003נגע\u0004 העקב \u0003באותו מקום\u0004 (כינוי לבית הערוה), ומשם בא הדם אליו. \u0003אלא\u0004 אם נמצא הדם ב\u0003ראש גודלה, מאי טעמא\u0004 \u0005[מה טעם]\u0006 נטמאת היא בו? \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 בטעם הדבר כי \u0003זימנין\u0004 \u0005[פעמים]\u0006 קורה שראש האגודל של רגל אחת \u0003נגע בעקבה\u0004 של הרגל השניה כשעל העקב יש דם נידות, ומן העקב עבר הדם אל ראש האגודל — \u0003ומי מחזקינן\u0004 \u0005[והאם מחזיקים,\u0006 משייכים \u0005אנו]\u0006 בדיני \u0003טומאה\u0004 דבר ש\u0003ממקום\u0004 זה \u0003למקום\u0004 אחר, ואיך אם כן נשייך את הכתם הנמצא בראש האגודל של רגל אחת לדם שהיה בעקב הרגל השניה?","\u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא בדין המוצאת כתם דם כנגד בית התורפה: אם \u0003היתה לה\u0004 לאשה \u0003מכה\u0004 (פצע) \u0003בצוארה,\u0004 והרי זה מקום \u0003שתוכל לתלות\u0004 בו את מקורו של הדם שנמצא כנגד בית התורפה — הריהי \u0003תולה\u0004 בו את הדם, וטהורה היא. ואולם אם היה הפצע \u0003על כתפה,\u0004 והרי זה מקום \u0003שאינה יכולה לתלות\u0004 בו את הדם שנמצא כנגד בית התורפה — \u0003אינה תולה,\u0004 והריהי טמאה.","\u0003ו\u0004מכאן נסיק כי \u0003אין אומרים שמא בידה נטלתו\u0004 את הדם מהפצע שבכתפה \u0003והביאתו לשם,\u0004 אל מול בית התורפה, ונטהר אותה, והרי שאין מחזיקים בדיני טהרה וטומאה ממקום למקום! \u0003אלא\u0004 כך יש להסביר: \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחד\u0005]\u0006 הוא \u0003ראש גודלה, דבהדי דפסעה עביד דמתרמי\u0004 \u0005[שאגב ש\u0006היא \u0005פוסעת, עשוי שיזדמן]\u0006 ראש האגודל מתחת לבית התורפה, ומשם נטף הדם עליו. ולכך הריהי טמאה בכתם זה.","ומקשים: \u0003ו\u0004האם \u0003לא מחזקינן\u0004 \u0005[אין אנו מחזיקים]\u0006 \u0003טומאה ממקום למקום? והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003נמצאת\u0004 כתם דם \u0003על קשרי אצבעותיה\u0004 (גב כף היד) — הריהי \u0003טמאה.\u0004 ואף שאין דם בית התורפה מגיע כרגיל אל גב היד, הריהי טמאה \u0003מפני שידים עסקניות\u0004 (מרבות להתעסק, לעשות פעולות שונות) \u0003הן,\u0004 ובא דם מהמקור אל גב היד.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שהריהי נטמאת בשל היות הידים עסקניות — \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 כי היא \u0003בדקה בחד ידא\u0004 \u0005[ביד אחת]\u0006 וכך הגיע הדם מן המקור אל אותה כף יד, \u0003ו\u0004לאחר מכן היא \u0003נגעה באידך ידא\u0004 \u0005[ביד האחרת,\u0006 בגבה\u0005],\u0006 וכך הגיע הדם אל גב היד. הרי איפוא שמחזיקים אנו טומאה ממקום למקום! ודוחים: \u0003לא,\u0004 אין מחזיקים טומאה ממקום למקום, וטעם הדבר שהריהי טמאה בדם הנמצא בגב ידה: שכן \u0003שאני\u0004 \u0005[שונה,\u0006 מיוחדת\u0005]\u0006 היא \u0003ידה\u0004 — ש\u0003כולה עבידא דנגעה\u0004 \u0005[עשויה לגעת]\u0006 במקום התורפה, ובכלל זה גם גב ידה.","שנינו במשנתנו כי אם נמצא הדם \u0003על שוקה ו\u0004כן אם נמצא \u0003על פרסותיה,\u0004 אם היה זה \u0003מבפנים\u0004 — הרי זה דם טמא, ואם היה זה מבחוץ — הרי זה דם טהור. ומבררים הלכה זו: מקום זה בגוף הנקרא במשנה \u0003\"מבפנים\" עד היכא\u0004 \u0005[היכן]\u0006 הוא? \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 החכמים \u0005של בית]\u0006 מדרשו של \u0003ר' ינאי: עד מקום חבק\u0004 (מפגש הירך והשוק, וחביקתם זה בזה באמצעות גידים הנמתחים).","ובענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 האם \u0003מקום\u0004 ה\u0003חבק\u0004 עצמו, נחשב כלפנים או כלחוץ? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] פתרון לבעיה זו ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב קטינא\u0004 במפורש: \u0003עד מקום חבק, וחבק עצמו\u0004 נחשב \u0003כלפנים.\u0004 ומוסיפים כי \u0003רב חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא מתני לה בהדיא\u0004 \u0005[היה שונה אותה\u0006 הלכה בדין מקום החבק עצמו, במפורש, בגוף דברי חכמים\u0005],\u0006 שכך \u0003אמרי דבי\u0004 \u0005[אומרים\u0006 החכמים \u0005של בית]\u0006 מדרשו של \u0003ר' ינאי: עד מקום חבק, וחבק עצמו\u0004 נחשב \u0003כלפנים.\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה:\u0004 כתם דם שנמצא על גוף האשה, והיתה צורתו \u0003כשיר\u0004 (צמיד) \u0003מהו\u0004 דינו? וכן אם היתה צורתו של כתם הדם הזה \u0003כשורה\u0004 (קו ישר) \u0003מהו\u0004 דינו? או שלא היה בעל צורה מגובשת (עגול או ישר) אלא מקבץ של \u0003טיפין טיפין מהו\u0004 דינו? וכן אם נמצא הדם \u0003לרוחב ירכה\u0004 של האשה, \u0003מהו\u0004 דינו? האם אף בכל אלה הריהי טמאה, שכן יש להסתפק בהם שמא הרי זה דם מן המקור.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלות אלה ממה ששנינו בברייתא: נמצא הדם \u0003על בשרה, ספק טמא ספק טהור\u0004 — הרי זה דם \u0003טמא.\u0004 ויש לדייק באמור בצורה כוללת שכל שנמצא \u0003על בשרה\u0004 והריהו ספק טמא ספק טהור — הרי זה דם טמא: \u0003מאי לאו כי האי גוונא\u0004 \u0005[האם אין\u0006 כוונת הדברים לאופני ספק \u0005כעין אלה\u0006 שהעלה ר' ירמיה\u0005],\u0006 ונלמד מכאן כי כל אלה מטמאים. ודוחים את הראיה: \u0003לא,\u0004 אין להוכיח מכאן, שכן \u0003דלמא דעביד\u0004 \u0005[שמא\u0006 מדובר באופן \u0005שנעשית\u0006 צורתו\u0005]\u0006 של הכתם \u0003כרצועה\u0004 הנמשכת לאורך הירך. והרי זה מכלל דרכן של נשים כשהריהן שותתות דם מן המקור, הריהו נעשה כרצועה.","ועוד בעניינם של ספק בכתמי דם הנמצאים, מסופר: \u0003ההיא איתתא דאשתכח\u0004 \u0005[אשה אחת שנמצא]\u0006 \u0003לה דמא במשתיתא\u0004 \u0005[דם בחוטי השתי\u0006 שבמסכת האריג\u0005] שארגה. והרי זה ספק אם תוך כדי מעשה הטוויה מגיעים חוטי השתי אל בין רגליה, מתחת לבית התורפה, ודם זה הגיע מהמקור אל חוטי השתי, והריהי איפוא טמאה בו.\u0006 \u0003אתאי לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003ר' ינאי\u0004 לשאול על דינו של דם זה. \u0003אמר לה\u0004 ר' ינאי: \u0003תיזיל ותיתי\u0004 \u0005[תלך ותבוא],\u0006 שתשוב ותעסוק במלאכה זו של הטויה, וכיון שדרך מעשה האריגה בתנועה קבועה, ודאי כך יתברר אם מגיעים חוטי השתי אל מקום זה אם לא.","ותוהים על הכרעת דין זו: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 כי \u0003אין שונין\u0004 (משחזרים) דבר שאירע כדי לבדוק בכך מה אירע בפעם הקודמת, \u0003ב\u0004דיני \u0003טהרות\u0004 וטומאות! ומשיבים: \u0003כי אמרינן\u0004 \u0005[כאשר אומרים אנו]\u0006 ש\u0003אין שונין\u0004 בטהרות — אין זה אלא \u0003לקולא\u0004 \u0005[להקל\u0006 בדין\u0005],\u0006 \u0003אבל לחומרא\u0004 \u0005[להחמיר\u0006 בדין\u0005],\u0006 וכגון במקרה זה, שמעיקרו של דבר, בלא בדיקה זו, אשה זו טהורה (שהרי לא נמצא כתם הדם לא על בשרה ולא על חלוקה) — \u0003שונין\u0004 אף בטהרות, ואם יתברר שחוטי השתי מגיעים אל מתחת למקום התורפה בשעת הטוויה, הריהי טמאה.","עוד שנינו במשנתנו כי אם \u0003היתה פושטתו\u0004 את חלוקה, ומתכסה בו כשמיכה בלילה — הריהי טמאה בכל אופן בו נמצא כתם הדם בחלוק זה, שכן עשוי החלוק לנוע ממקום למקום תוך כדי שינה. ומביאים עוד בענין זה, \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003אליעזר בר' יוסי:\u0004 ב\u0003דבר זה\u0004 (דינו של דם הנמצא בחלוק המשמש כשמיכה לשינת הלילה) \u0003הוריתי בעיר רומי לאיסור, וכשבאתי אצל חכמים שבדרום, אמרו לי: יפה\u0004 (כראוי) \u0003הוריתה.\u0004","ועוד בענין כתם דם הנמצא בחלוק, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אשה \u0003ארוכה\u0004 (גבוהה) \u0003שלבשה\u0004 את \u0003חלוקה של\u0004 אשה \u0003קצרה\u0004 (נמוכה), ובלא שבדקה לפני כן את החלוק אם נקי הוא מכתם. \u0003ו\u0004כן אשה \u0003קצרה שלבשה\u0004 את \u0003חלוקה של\u0004 אשה \u0003ארוכה,\u0004 ונמצא עתה כתם בחלוק, ואין ידוע ממי בא הכתם, אם מהגבוהה או מהנמוכה, מה דינו? \u0003אם מגיע\u0004 מקום כתם הדם אל \u0003כנגד\u0004 (מול) \u0003בית התורפה של ארוכה\u0004 — \u0003שתיהן טמאות.\u0004 שכן אם הוא מגיע אצל האשה הגבוהה כנגד בית התורפה, בודאי שהרי הוא מגיע כך גם אצל האשה הנמוכה. ולכך שתיהן טמאות מן הספק. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאין הוא מגיע כנגד מקום התורפה אצל האשה הגבוהה: ה\u0003ארוכה\u0004 — \u0003טהורה,\u0004 שודאי הוא שלא ממנה בא כתם זה. \u0003וקצרה\u0004 — \u0003טמאה.\u0004","ועוד \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת],\u0006 בענין כתם הנמצא בחלוק שאול: \u0003בדקה\u0004 האשה את \u0003חלוקה\u0004 ונמצא שאין בו כתם דם, \u0003והשאילתו לחבירתה,\u0004 ולאחר מכן נמצא כתם דם בחלוק זה. מה דינן? \u0003היא,\u0004 האשה שהשאילה את החלוק — הריהי \u0003טהורה, וחבירתה\u0004 זו ששאלה את החלוק — הריהי \u0003תולה בה,\u0004 באשה שהשאילה את מקור הכתם. שיכולה היא לומר שאין היא סומכת עליה שבדקה כראוי את החלוק שהשאילה. \u0003אמר רב ששת\u0004 בהסבר דברי הברייתא הללו: \u0003ו\u0004רק \u0003לענין דינא\u0004 \u0005[דין]\u0006 על מי חלה חובת כיבוס הבגד, \u0003תנן\u0004 \u0005[שנינו]\u0006 בברייתא שיכולה האשה ששאלה לטעון שאין היא סומכת על חברתה שאכן בדקה כראוי את החלוק. \u0003אבל לענין\u0004 הלכות \u0003טומאה\u0004 — \u0003היא\u0004 (המשאילה) \u0003טהורה וחבירתה\u0004 (השואלת) \u0003טמאה.\u0004"],["ושואלים על דברי רב ששת: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 נבדל\u0005]\u0006 דין זה שהאשה השניה (ששאלה את החלוק) טמאה, אך הראשונה (שבדקה את חלוקה, והשאילתו) טהורה, \u0003מהא דתניא\u0004 \u0005[מ\u0006הלכה זו \u0005ששנויה\u0006 בברייתא\u0005]\u0006 בדין \u0003שתי נשים שנתעסקו בצפור אחד\u0004 שחוט, \u0003ואין בו\u0004 בצפור זה \u0003אלא כ\u0004שיעור \u0003סלע דם, ונמצא\u0004 דם ששיעורו כשני סלעים, \u0003כסלע על זו וכסלע על זו\u0004 — \u0003שתיהן טמאות,\u0004 אף שיש מקום לתלות את דמה של אחת מהן בצפור שהתעסקו עמו. ואף במקרה זה של רב ששת, יש לומר שהגם שבדקה עצמה — תטמא, שמא לא בדקה היטב! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 — \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003סלע יתירה.\u0004","ועוד מדברי חכמים בכתם שלא בא מן הציפור אלא מקורו בשתים מן הנשים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לבשה\u0004 האשה \u0003שלשה חלוקות\u0004 זה על גבי זה, ואלה \u0003ה\u0004חלוקים היו \u0003בדוקין לה\u0004 שאין בהם כתם דם. ולאחר מכן מצאה על אחד החלוקים כתם דם, מה דינה? \u0003אם\u0004 היא \u0003יכולה\u0004 (אם יש מקום) \u0003לתלות\u0004 את הימצאותו של הדם בחלוק בגורם חיצוני — הריהי \u0003תולה\u0004 בו, והריהי טהורה. \u0003ואפילו\u0004 אם נמצא כתם הדם \u0003ב\u0004חלוק ה\u0003תחתון\u0004 הקרוב לגופה. ואם \u0003אין\u0004 היא \u0003יכולה לתלות\u0004 את הדם בגורם חיצוני — \u0003אינה תולה,\u0004 והריהי טמאה. \u0003ואפילו\u0004 אם נמצא הכתם \u0003ב\u0004חלוק ה\u0003עליון.\u0004","ומפרטים: \u0003כיצד?\u0004 אם \u0003עברה בשוק של טבחים,\u0004 מאחר שמצויים בו דמים, ויש אפשרות שניתז דם על בגדיה — הריהי \u0003תולה\u0004 את הימצאות הדם על חלוקה כמי שבא משוק של טבחים, והריהי טהורה, ו\u0003אפילו\u0004 אם נמצא הדם \u0003ב\u0004חלוק ה\u0003תחתון.\u0004 ואם \u0003לא עברה בשוק של טבחים,\u0004 ולא במקום אחר בו מצויים דמים, \u0003אף\u0004 כשנמצא כתם הדם \u0003ב\u0004חלוק ה\u0003עליון\u0004 — \u0003אינה תולה\u0004 את הדם בגורם חיצוני, והריהי טמאה.","\u0003ותולה\u0004 האשה המוצאת כתם דם (על גופה או על בגדה) את הימצאותו \u0003בכל דבר שהיא יכולה לתלות.\u0004 ומפרטים: \u0003שחטה\u0004 האשה \u0003בהמה\u0004 או \u0003חיה ו\u0004כן \u0003עוף,\u0004 או ש\u0003נתעסקה ב\u0004הסרתם של \u0003כתמים\u0004 של דם שהיו על בגדי נשים אחרות, או בניקוי כתם דם שמקורו בפצע שבמקום אחר בגופה. \u0003או שישבה בצד\u0004 אנשים \u0003העסוקין בהן,\u0004 או ש\u0003הרגה\u0004 \u0003מאכולת\u0004 (כינה) — \u0003הרי זו תולה בה\u0004 את הדם שנמצא.","ו\u0003עד כמה\u0004 (עד איזה גודל) יהא הכתם ותהא \u0003תולה\u0004 אותו בדם המאכולת? \u0003ר' חנינא בן אנטיגנוס אומר: עד\u0004 שיהא שיעור שטחו \u0003כגריס של פול.\u0004 \u0003ו\u0004מוסיף ר' חנינא בן אנטיגנוס: והריהי תולה בדם מאכולת, \u0003אף על פי שלא\u0004 זכור לה ש\u0003הרגה\u0004 מאכולת. \u0003ו\u0004כן הריהי \u0003תולה\u0004 את הופעת הדם עליה \u0003בבנה או בבעלה\u0004 המצויים אצלה, ויש בהם פצע. וכן \u0003אם יש בה\u0004 באשה עצמה \u0003מכה\u0004 (פצע). \u0003ו\u0004אף כשהגלידה המכה ושוב אינה מדממת, אם עדיין \u0003היא יכולה להגלע\u0004 (להיפתח) \u0003ולהוציא דם\u0004 — \u0003הרי זו תולה\u0004 במכה זו את הדם, וטהורה היא.","ומספרים: \u0003מעשה באשה אחת שבאת\u0004 (שבאה) \u0003לפני ר'\u0004 \u0003עקיבא\u0004 לברר מה דינה לענין טומאת הנדה. \u0003אמרה לו: ראיתי כתם.\u0004 \u0003אמר לה: שמא מכה היתה ביך\u0004 (בך)? \u0003אמרה לו: הן, ו\u0004אולם המכה כבר \u0003חיתה\u0004 (נרפאה), ואין היא מדממת. \u0003אמר לה: שמא יכולה\u0004 המכה עדיין \u0003להגלע ולהוציא דם? אמרה לו: הן.\u0004 \u0003ו\u0004על סמך דברים אלה טהרה ר' עקיבא.","\u0003ראה\u0004 ר' עקיבא את \u0003תלמידיו\u0004 שהם \u0003מסתכלין זה בזה\u0004 בתמהון על שהורה רבם להקל בדבר זה. \u0003אמר להם: מה הדבר קשה בעיניכם\u0004 על שאני מקל בהוראת כתמים? אין הטעם אלא מפני \u0003שלא אמרו חכמים\u0004 את \u0003הדבר\u0004 (שגזרו על הכתמים הנמצאים באשה שיטמאוה) כדי \u0003להחמיר\u0004 — \u0003אלא להקל\u0004 בה, ולכך אף במקרה שיש בו כשהסיכוי שבא הדם מגורם חיצוני מועט, תולים אנו את הופעת הדם בו, והריהי טהורה. שמן התורה האשה אינה נטמאת בכתמים, \u0003ש\u0004כן \u0003נאמר\u0004 בדין טומאת האשה בנדה \u0003\"ואשה כי תהיה זבה דם יהיה זבה בבשרה\"\u0004 (ויקרא טו, יט). הדגיש הכתוב — דווקא ב\u0003דם\u0004 הריהי נטמאת \u0003ולא\u0004 ב\u0003כתם.\u0004 \u0003וחכמים הם שגזרו טומאה בכתם הנמצא.\u0004","\u0003ודין נוסף:\u0004 \u0003עד\u0004 (פיסת בד המשמשת את האשה לבדיקה אם יצא דם מהמקור) \u0003שהוא נתון\u0004 \u0003תחת הכר\u0004 עליו מניחה האשה את ראשה בשעת שינה, \u0003ו\u0004בבוקר \u0003נמצא עליו\u0004 כתם \u0003דם,\u0004 ואין ידוע אם דם בדיקה הוא, וטמא. או שמא דם מאכולת שנמעכה תחתיו הוא, וטהור — אם הכתם \u0003עגול,\u0004 הרי זה דם \u0003טהור,\u0004 שאין זה כתם שנוצר על ידי הבדיקה, שאין כתם בדיקה בא בצורה שכזו. ואולם אם הריהו \u0003משוך\u0004 (צורה מארכת) — הרי זה \u0003טמא,\u0004 אלו \u0003דברי ר'\u0004 \u0003אליעזר בר' צדוק.\u0004","שנינו במשנתנו כי האשה המוצאת כתם דם תולה כתם זה בכל דבר שניתן לתלות בו. ומעירים: \u0003תנינא להא\u0004 \u0005[\u0006\u0005שנינו את זה]\u0006 בדברי הברייתא, שכך נהגו חכמים הלכה למעשה, \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]:\u0006 \u0003מעשה\u0004 שבא כתם דם לפני ר' מאיר לדון בו אם לטמאו או לטהרו, \u0003ותלה ר'\u0004 \u0003מאיר\u0004 את הופעת הכתם הזה \u0003בקילור\u0004 (משחת תרופה) שהתעסקה בה האשה לפני כן, וטיהרה. \u0003ו\u0004כן בא כתם דם לפני ר' יהודה הנשיא (רבי) לדון בו, וטיהרו \u0003רבי,\u0004 אחר ש\u0003תלה\u0004 את הופעתו \u0003בשרף\u0004 עץ ה\u0003שקמה\u0004 שנגעה בו האשה לפני כן.","דשנינו במשנתנו שאם התעסקה האשה בכתמים לפני שנמצא הכתם עליה \u0003או שישבה\u0004 בצדם של אלה שמתעסקים בכתמים — הרי זה דם טהור, שכן תולה היא בהם את הופעת כתם זה. ומדייקים בדברים: דווקא כאשר היא יודעת בבירור ש\u0003ישבה\u0004 בצדם של המתעסקים בכתמים — \u0003אין\u0004 \u0005[כן],\u0006 כך הוא דינה. ואולם אם היא \u0003לא\u0004 יודעת בבירור ש\u0003ישבה\u0004 בצדם, אלא רק עברה שם — הריהי \u0003לא\u0004 תולה בהם, ואין אנו אומרים שמא באותה עת היא גם ישבה לצדם (בלא לשים לב לכך).","ומעירים: \u0003תנינא להא\u0004 \u0005[\u0006\u0005כן\u0006 \u0005שנינו את זה]\u0006 בדברי הברייתא. \u0003דתנו רבנן\u0004 \u0005[ש\u0006כן \u0005שנו חכמים]:\u0006 \u0003עברה בשוק של טבחים, ספק ניתז עליה ספק לא ניתז עליה\u0004 — הריהי \u0003תולה.\u0004 ואולם אם יש לה \u0003ספק\u0004 אם \u0003עברה\u0004 בשוק של טבחים \u0003ספק לא עברה\u0004 — הריהי \u0003טמאה.\u0004","שנינו במשנתנו שאם לפני הבדיקה \u0003הרגה\u0004 האשה \u0003מאכולת,\u0004 הריהי תולה את הכתם בדם המאכולת, וטהורה היא. ומדייקים: דווקא כאשר \u0003הרגה\u0004 מאכולת לפני כן — \u0003אין\u0004 \u0005[כן],\u0006 כך הם הדברים. ואולם אם \u0003לא הרגה\u0004 מאכולת לפני כן — הריהי \u0003לא,\u0004 תולה את הכתם בדם מאכולת. ומעירים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003רבן שמעון בן גמליאל היא.\u0004 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003הרגה\u0004 מאכולת קודם למציאת הכתם — \u0003תולה, לא הרגה\u0004 — \u0003אינה תולה,\u0004 אלו \u0003דברי רבן שמעון בן גמליאל.\u0004 \u0003ו\u0004אילו \u0003חכמים אומרים:\u0004 \u0003בין כך ובין כך\u0004 הריהי \u0003תולה.\u0004","\u0003אמר רבן שמעון בן גמליאל\u0004 על הקושי שבשיטתו ובשיטת חבריו החכמים: \u0003לדברי\u0004 (לשיטתי המחמירה בדין כתם, שאין תולה בדם בעל חיים אלא רק כשהרגתו) — \u0003אין קץ, ולדברי חברי\u0004 (לשיטתם המקילה בדין מציאת כתם, שהריהי תולה בדם בעלי חיים, בכל אופן) — \u0003אין סוף.\u0004","ומסביר את דבריו: \u0003לדברי\u0004 — נמצא ש\u0003אין קץ\u0004 (אין שיעור, אין מידה קצוצה וקבועה) לגודלו של הכתם הנמצא. שאפילו היה זה כתם קטן ביותר, וכגודלו של גרגר צמח החרדל, הריהי טמאה. ומעתה, נמצא \u0003שאין לך אשה\u0004 בישראל \u0003ש\u0004תהא \u0003טהורה לבעלה, ש\u0004הרי \u0003אין לך כל מטה ומטה\u0004 של הנשים \u0003שאין בה כמה טיפי דם מאכולת.\u0004 וכיון שלשיטתי אינה תולה בדם מאכולת אלא רק כאשר היא יודעת שהרגה מאכולת לפני כן — תהיינה כל הנשים טמאות.","ומן הצד האחר, \u0003לדברי חברי\u0004 — \u0003אין סוף\u0004 (דבר המגביל) את היתרן של הנשים, \u0003ש\u0004כן לשיטת חכמים, \u0003אין לך אשה\u0004 בישראל \u0003שאינה טהורה לבעלה, ש\u0004הרי \u0003אין לך כל סדין וסדין שאין בו כמה טיפי דם.\u0004 ותבוא האשה ותתלה את טיפות הדם הללו בדם המאכולת (הגם שהיא לא הרגה מאכולת לפני כן).","\u0003אבל נראין דברי ר'\u0004 \u0003חנינא בן אנטיגנוס\u0004 יותר \u0003מדברי ומדבריהם\u0004 של חכמים. \u0003ש\u0004כך \u0003היה\u0004 ר' חנינא בן אנטיגנוס \u0003אומר: עד כמה\u0004 (עד איזה גודל) של כתם דם הריהי \u0003תולה\u0004 שהרי זה דם המאכולת, שכן דמה של המאכולת הוא דם מועט? \u0003עד כגריס של פול, ולדבריו\u0004 של ר' חנינא בן אנטיגנוס \u0003אנו מודים.\u0004 \u0003ו\u0004מבררים: \u0003לרבנן, דאמרי\u0004 \u0005[ל\u0006דעת \u0005חכמים, שאומרים]\u0006 כי בכל אופן הריהי \u0003תולה\u0004 את הכתם הנמצא בדם מאכולת, \u0003עד כמה\u0004 יהא גודל כתם הדם ותהא תולה, והרי יש כתמים הנמצאים ששיעורם גדול בהרבה משיעור דמה של מאכולת? \u0003אמר רב נחמן בר יצחק:\u0004 בכתמי דם ששיעורם גדול יותר, הריהי \u0003תולה ב\u0004דם \u0003פשפש\u0004 (שדמו מרובה משל מאכולת), \u0003ו\u0004אמורים הדברים בכל כתם ששיעור שטחו הוא \u0003עד כ\u0004רוחב ה\u0003תורמוס.\u0004","מאחר והוזכר הפשפש ושיעור דמו, מביאים עוד בעניינו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פשפש זה,\u0004 שיעור \u0003ארכו\u0004 הריהו \u0003כ\u0004שיעור \u0003רחבו, וטעמו\u0004 של הפשפש הריהו \u0003כריחו\u0004 הרע. ולענין ריחו מסרו כי \u0003ברית כרותה לו\u0004 (חוק בל יעבור החל עליו) — \u0003שכל המוללו (ממעכו)\u0004 הריהו \u0003מריח בו\u0004 את ריחו הרע. ומסבירים לאיזה ענין שבהלכה נזכרו מאפייני הפשפש: \u0003ארכו כרחבו\u0004 — \u0003לענין כתמים,\u0004 שאם נמצא כתם ששיעור אורכו כשיעור רוחבו, אף שהריהו גדול משיעור כגריס של פול, תולים אותו בדם הפשפש.","\u0003טעמו כריחו\u0004 — \u0003לענין\u0004 אכילת \u0003תרומה, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בדין האוכל תרומה, שיש והריהו נדרש לפלוט מפיו את התרומה: \u0003או שטעם טעם פשפש בפיו,\u0004 והרי הפשפש אסור באכילה — \u0003הרי זה יפלוט\u0004 את כל שבפיו, אף שתרומה בפיו, ומפסידה בכך. ו\u0003מנא ידע\u0004 \u0005[מנין\u0006 הוא \u0005יודע]\u0006 שאכן פשפש הוא זה שבפיו? שכן \u0003טעמו כריחו.\u0004 \u0003ואכתי מנא ידע\u0004 \u0005[ועדיין מנין\u0006 הוא \u0005יודע]\u0006 שזה הוא ריחו של הפשפש? ומשיבים: אין אדם טועה בריחו של הפשפש, כי \u0003ברית כרותה לו\u0004 לפשפש, \u0003שכל המוללו\u0004 הריהו \u0003מריח בו\u0004 את ריחו הרע, והרי זה איפוא ריח מוכר היטב.","שנינו במשנתנו כי המוצאת כתם הריהי תולה אותו (במקום שניתן לתלות) בדם בעלי חיים, וטהורה היא. ובענין זה \u0003אמר רב אשי: עיר שיש בה חזירים,\u0004 והרי אלה נטבחים לאכילתם בידי הגוים, ודמם מרובה. ואף סביבת גידול החזירים מרובה בפשפשים ובשאר רמשים — \u0003אין חוששין לכתמים\u0004 הנמצאים על גופה או על בגדה של אשה הדרה בעיר זו. שכן תולים את הכתם בדם הבא מבחוץ לה. \u0003אמר רב נחמן בר יצחק: והא\u0004 \u0005[וזו]\u0006 העיר \u0003דדוקרת,\u0004 שמצוים בה הרבה משחטות ואשפות ושקצים ורמשים — \u0003כעיר שיש בה חזירים דמיא\u0004 \u0005[\u0006הריהי \u0005נחשבת].\u0006","שנינו במשנתנו: \u0003עד כמה\u0004 יהא שיעור הכתם ויכולה \u0003היא תולה\u0004 את כתם הדם במאכולת? ותשובתו של ר' חנינא בן אנטיגנוס שהוא עד כשיעור גריס של פול. ומביאים מחלוקת חכמים בהסבר דברי ר' חנינא בן אנטיגנוס. \u0003אמר רב הונא:\u0004 אם היה שיעור הכתם \u0003כגריס\u0004 — שוב \u0003אינה תולה\u0004 בדם מאכולת. היה שיעורו \u0003פחות מכגריס\u0004 — הריהי \u0003תולה\u0004 בדם מאכולת. \u0003ו\u0004אילו \u0003רב חסדא אמר:\u0004 אם היה גודל הכתם \u0003כגריס\u0004 — הריהי עדיין \u0003תולה\u0004 בדם מאכולת, ורק אם גודל הכתם \u0003יתר מכגריס\u0004 — שוב \u0003אינה תולה\u0004 בדם מאכולת.","ומציעים: \u0003לימא\u0004 \u0005[האם נאמר]\u0006 כי \u0003ב\u0004שאלת \u0003\"עד ועד בכלל קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006 והרי זו מחלוקת הנוגעת ללשון חכמים, שכל מקום שהזכירו בו שיעור מסויים שהוא \"עד\" משהו מסויים — האם הכוונה שאף ה\"עד\" הריהו בכלל המדובר, או שאין הוא בכלל המדובר. \u0003רב הונא סבר\u0004 \u0005[סבור]:\u0006 \u0003עד\u0004 — \u0003ולא עד בכלל,\u0004 ור' חנינא בן אנטיגנוס אמר את דבריו עד לכגריס של פול, ואין הם כוללים שיעור גריס של פול עצמו. \u0003ו\u0004אילו \u0003רב חסדא סבר\u0004 \u0005[סבור]:\u0006 \u0003עד\u0004 — \u0003ועד בכלל.\u0004 ודוחים: אין צורך להעמיד כן את מחלוקתם.","כי \u0003אמר לך\u0004 \u0005[יכול לומר לך]\u0006 \u0003רב הונא\u0004 שאף הוא סבור לפעמים שעד ועד בכלל. שכן \u0003איכא\u0004 \u0005[יש]\u0006 מקומות שבהם אנו אומרים \u0003עד ועד בכלל, ואיכא\u0004 \u0005[יש]\u0006 מקומות שבהם אנו אומרים \u0003עד ולא עד בכלל, והכא לחומרא\u0004 \u0005[וכאן,\u0006 במקום שאומרים בו עד ועד בכלל, הרי זה \u0005להחמיר,\u0006 וכמו בדברי ר' חנינא בן אנטיגנוס הללו\u0005],\u0006 \u0003והכא לחומרא\u0004 \u0005[וכאן,\u0006 במקום שאין אומרים בו עד ועד בכלל, הרי זה \u0005להחמיר],\u0006","\u0003ורב חסדא אמר לך\u0004 \u0005[יכול לומר לך]:\u0006 \u0003בעלמא אימא לך\u0004 \u0005[בסתם,\u0006 במקרים רגילים, \u0005אומר אני לך]\u0006 כדברי רב הונא שההכרעה שעד ועד בכלל — \u0003לחומרא אמרינן, לקולא לא אמרינן\u0004 \u0005[להחמיר אנו אומרים\u0006 כן, \u0005להקל אין אנו אומרים\u0006 כן\u0005].\u0006 \u0003ו\u0004אולם \u0003הכא\u0004 \u0005[כאן,\u0006 בדין כתמים\u0005],\u0006 שאומרים אנו להקל (ולכך אף הרואה בשיעור כגריס אינה טמאה) — הרי זה \u0003כ\u0004שיטתו של \u0003ר' אבהו,\u0004 שכן \u0003אמר ר'\u0004 \u0003אבהו: כל שעורי חכמים\u0004 — הריהם \u0003להחמיר, ח\u0004 \u0003וץ מכגריס של כתמים\u0004 — שהריהו \u0003להקל.\u0004","ומביאים עוד את מחלוקתם זו של רב הונא ורב חסדא, \u0003איכא דאמרי לה להא שמעתא באפי נפשה\u0004 \u0005[יש שאומרים,\u0006 ששונים, \u0005אותה, את זו ההלכה בפני עצמה],\u0006 כהלכה עקרונית כללית, ולא כמוסבת דווקא על השנוי במשנתנו בדין הכתמים. ש\u0003רב הונא אמר\u0004 כי כל מקום שבו נקבע שיעור זה של עד כגריס — הרי שיעור מדוייק של \u0003כגריס\u0004 נחשב \u0003כיתר מכגריס.\u0004 \u0003ו\u0004אילו \u0003רב חסדא אמר\u0004 כי \u0003כגריס\u0004 מדוייק נחשב \u0003כפחות מכגריס.\u0004 \u0003וקמיפלגי\u0004 \u0005[והריהם חלוקים]\u0006 \u0003ב\u0004שאלת \u0003\"עד ועד\u0004 בכלל\" במקרה זה של כתמים \u0003דהכא\u0004 \u0005[שבכאן],\u0006 ו\u0003כדאמרינן\u0004 \u0005[כפי שאמרנו],\u0006 שלדעת רב הונא דין הגריס בכתמים כלמעלה מכגריס, שהיא הכרעת הדין להחמיר. ואילו רב חסדא אמר שדין הגריס כפחות מכגריס, כיון שבכתמים יש להקל, וכשיטת ר' אבהו. \u0003מיתיבי\u0004 \u0005[מקשים],\u0006"],["ממה ששנינו: \u0003היו עליה\u0004 על גוף האשה או על חלוקה \u0003טיפי דמים\u0004 ששיעורן \u0003למטה\u0004 (קטן), \u0003ו\u0004כן \u0003טיפי דמים\u0004 ששיעורן \u0003למעלה\u0004 (גדול) — הריהי \u0003תולה\u0004 את טיפות הדם הללו כמי שבאו אליה מבחוץ, ואף \u0003ב\u0004טיפת דם ה\u0003עליון\u0004 (בשיעור הגדול ביותר) שהוא \u0003עד כגריס.\u0004 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא שאף \u0003כגריס\u0004 עצמו נחשב כ\u0003מלמטה\u0004 (קטן), שאין הוא נחשב כיותר מכגריס, והרי זו קושיה על דברי רב הונא. ודוחים: \u0003לא,\u0004 כוונת הדברים ש\u0003כגריס\u0004 עצמו נחשב כ\u0003מלמעלה\u0004 (כגדול), כיתר מכגריס.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 אם \u0003נמצא עליה\u0004 כתם ששיעורו הוא \u0003כגריס ועוד\u0004 משהו (שכיון ששיעורו יותר מכגריס אינה תולה אותו בדם מאכולת) \u0003ו\u0004ב\u0003אותו עוד\u0004 היתה \u0003רצופה\u0004 (מרוחה) \u0003בו מאכולת\u0004 מעוכה. מה דינה של אשה זו? \u0003ר' חנינא אומר:\u0004 הריהי \u0003טמאה,\u0004 שאין תולים שבא מדם מאכולת. ואילו \u0003ר' ינאי אומר:\u0004 הריהי \u0003טהורה,\u0004 שתולים שבא מדם מאכולת. ומסבירים את שיטותיהם: טעמו של \u0003ר' חנינא\u0004 ה\u0003אומר\u0004 שהריהי \u0003טמאה: כי תליא\u0004 \u0005[כאשר תולה]\u0006 האשה כתם בדם מאכולת — הרי זה דווקא \u0003ב\u0004כתם ששיעורו הוא עד \u0003כגריס,\u0004 ואילו \u0003ב\u0004כתם ששיעורו הוא \u0003כגריס ועוד\u0004 — \u0003לא תליא\u0004 \u0005[אין תולה].\u0006 וטעמו של \u0003ר' ינאי\u0004 ה\u0003אומר\u0004 שהריהי \u0003טהורה:\u0004 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאין תולה בכתם ששיעורו כיתר מכגריס הריהם דווקא \u0003היכא\u0004 \u0005[היכן,\u0006 במקרה\u0005]\u0006 ש\u0003לא רצופה בו\u0004 בכתם הזה \u0003מאכולת, אבל היכא\u0004 \u0005[היכן]\u0006 ש\u0003רצופה בו מאכולת\u0004 — \u0003מוכחא מילתא דהאי\u0004 \u0005[מוכח הדבר שזה]\u0006 ה\u0003ועוד דם מאכולת הוא,\u0004 שהרי רואים אנו את המאכולת מרוחה עליו. ולגביו אין ספק מה מקורו. מעתה, \u0003פש ליה\u0004 \u0005[נשאר לו]\u0006 בכתם זה שיש ספק באשר למקורו, רק שיעור \u0003כגריס,\u0004 ובזה נאמר: \u0003כיון דבעלמא\u0004 \u0005[שבסתם]\u0006 כתם ששיעורו הוא כגריס — הריהי \u0003תליא\u0004 \u0005[תולה]\u0006 במאכולת, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 — הריהי \u0003תליא\u0004 \u0005[תולה]\u0006 באחרת.","","למעלה הובאה מחלוקת ר' חנינא ור' ינאי בדין אשה שנמצא עליה כתם ששיעורו הוא כגריס ועוד, ועל אותו חלק הנוסף לכגריס היתה מרוחה מאכולת. ולענין מחלוקת זו מביאים עוד. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: נתעסקה\u0004 האשה \u0003ב\u0004דבר ששיעורו הוא \u0003כגריס,\u0004 וכגון בדם צפור או בקילור, \u0003ו\u0004אחר כך \u0003נמצא עליה\u0004 כתם ששיעורו הוא \u0003בכגריס ועוד\u0004 משהו, \u0003מהו\u0004 דינה של אשה זו? ומפרט ר' ירמיה את שאלתו: \u0003תבעי\u0004 \u0005[תישאל]\u0006 השאלה \u0003לר' חנינא\u0004 שאמר במקרה המדובר למעלה כי הריהי טמאה, וכן \u0003תבעי\u0004 \u0005[תישאל]\u0006 השאלה \u0003לר' ינאי\u0004 שאמר במקרה המדובר למעלה כי הריהי טהורה. ומסביר את דבריו: \u0003תבעי\u0004 \u0005[תישאל]\u0006 השאלה \u0003לר' חנינא\u0004 — \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' חנינא התם\u0004 \u0005[שם,\u0006 במקרה המדובר למעלה\u0005]\u0006 שהריהי \u0003טמאה\u0004 — \u0003אלא\u0004 משום ש\u0003לא נתעסקה\u0004 האשה במאכולת. שאין מקום לתלות במאכולת את הכתם. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003נתעסקה\u0004 בדבר שיש לתלות בו — הריהי \u0003תליא\u0004 \u0005[תולה]?\u0006 ונמצא לפי צד זה של הבעיה, שהכל מודים במקרה זה שהריהי טהורה. ומן הצד האחר יש לומר: \u0003או דלמא\u0004 \u0005[שמא],\u0006 \u0003אפילו לר' ינאי\u0004 ש\u0003אמר\u0004 במקרה המדובר למעלה שהריהי \u0003טהורה\u0004 — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים רק \u0003היכא\u0004 \u0005[היכן,\u0006 במקרה ש\u0003רצופה בו מאכולת, אבל היכא\u0004 \u0005[היכן]\u0006 ש\u0003אין רצופה בו מאכולת\u0004 — \u0003לא תליא\u0004 \u0005[אינה תולה],\u0006 ונמצא לפי צד זה, שהכל מודים במקרה זה שהריהי טמאה.","","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ושמע] פתרון לבעיה ממה ששנינו: אם \u0003נתעסקה\u0004 האשה \u0003ב\u0004דבר שיש בו מהצבע ה\u0003אדום\u0004 — \u0003אין\u0004 היא \u0003תולה בה\u0004 כתם שצבעו \u0003שחור\u0004 לומר שמאותו דבר אדום בא כתם זה. וכן אם התעסקה \u0003ב\u0004דבר ששיעורו \u0003מועט\u0004 — \u0003אין\u0004 היא \u0003תולה בו\u0004 כתם ששיעורו הוא \u0003מרובה.\u0004 ויש לברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק]\u0006 מדובר במקרה זה שהתעסקה בדבר ששיעורו הוא מועט ומצאה כתם ששיעורו מרובה? \u0003לאו כי האי גוונא\u0004 \u0005[האם לא כעין זה],\u0006 כבעייתו של ר' ירמיה, שהתעסקה בדבר ששיעור דמו כגריס ונמצא עליה כגריס ועוד?! ושנינו שבאופן זה אין היא תולה בדבר שהתעסקה בו.","ודוחים את הפתרון המוצע: \u0003לא,\u0004 מדובר באופן אחר: \u0003כגון\u0004 ש\u0003נתעסקה בכגריס, ונמצא עליה\u0004 לאחר מכן כתם ששיעורו \u0003שני גריסין ועוד.\u0004 שבאופן זה, אין היא תולה את הכתם בדבר שהתעסקה בו. ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מדובר, \u0003מאי למימרא\u0004 \u0005[מה\u0006 חידוש בא זה \u0005לומר]?\u0006 והרי ברור שאין מקום לתלות בדבר שהתעסקה בו קודם לכן, שהרי שיעורו כגריס בלבד, ועדיין יש כתם בשיעור כגריס ועוד שאין במה לתלות אותו!","ומשיבים: חידוש יש בדבר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 היה מקום לומר\u0005],\u0006 \u0003שקול\u0004 \u0005[קח]\u0006 \u0003כגריס\u0004 דם \u0003צפור\u0004 שהתעסקה בו קודם — \u0003שדי בי מצעי\u0004 \u0005[השלך\u0006 אותו \u0005תוך האמצע,\u0006 של שני גריסי הכתם הנמצא\u0005].\u0006 ומעתה נאמר: \u0003זיל הכא\u0004 \u0005[לך לכאן,\u0006 לכגריס כתם שבצד זה\u0005]\u0006 — \u0003ליכא שיעורא\u0004 \u0005[אין כאן שיעור]\u0006 המטמא (שהרי כשיעור זה הריהי תולה), וכמו כן לענין כגריס כתם שבצד האחר, \u0003זיל הכא\u0004 \u0005[לך לכאן,\u0006 לכגריס הכתם השני\u0005]\u0006 — \u0003ליכא שיעורא\u0004 \u0005[אין כאן שיעור]\u0006 המטמא. לכך \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 שאין אומרים כן, והריהי טמאה באופן זה.","ומביאים עוד מענין זה, \u0003אמר רבא: נמצא עליה\u0004 כתם מדבר הבא מ\u0003מין אחד\u0004 (כגון שרף של שקמה, או קילור). ואחר כך מצאה על חלוקה כתם — אף שאין מראהו של הכתם דומה לאותו המין, הריהי \u0003תולה בו.\u0004 וכך הוא הדין, אפילו היו אלה כתמים של \u0003כמה מינין\u0004 השונים בצבעם מצבע הכתם שבא מאותו מין. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רבא ממה ששנינו: \u0003נתעסקה באדום\u0004 — \u0003אין תולה בו שחור!\u0004 ומשיבים: מקרה זה ש\u0003נתעסקה\u0004 הריהו \u0003שאני\u0004 \u0005[שונה]\u0006 מדינו של רבא. שכיון שהתעסקה בדבר שצבעו אדום — אין מקום לתלות בו את כתם הצבע השחור שמצאה, ואולם בענייננו אין מדובר באופן שהתעסקה במין האחר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 באופן זה את דברי הסוגיה הזו. ובאופן זה, \u0003אמר רבא: נתעסקה במין אחד\u0004 — הריהי \u0003תולה בו,\u0004 אפילו היו אלה כתמים של \u0003כמה מינין\u0004 השונים בצבעם מצבעו של אותו מין. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רבא ממה ששנינו: \u0003נתעסקה באדום\u0004 — \u0003אין תולה בו שחור!\u0004 ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רבא\u0004 את דבריו, הרי זה רק באופן \u0003דאתעסקה\u0004 \u0005[שהתעסקה]\u0006 לפני כן \u0003בתרנגולת\u0004 שנשחטה, \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה\u0004 בתרנגולת \u0003כמה מיני דמא\u0004 \u0005[דם],\u0006 ולכך הריהי תולה בו כתמים ממינים שונים.","שנינו במשנתנו \u0003מעשה באשה\u0004 שטיהרה ר' עקיבא, לפליאת תלמידיו, וטעמו: משום שלא גזרו חכמים את גזירתם בטומאת הכתם להחמיר אלא להקל. ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לא אמרו חכמים את הדבר\u0004 (גזירת כתמים) \u0003להקל, אלא להחמיר!\u0004","\u0003אמר רבינא:\u0004 אין להקשות מכאן על דברי ר' עקיבא, שכן כך היא כוונת דברי הברייתא: זה שגזרו חכמים על טומאת הכתמים להחמיר על דין תורה (שאין אשה נטמאת אלא בדם היוצא בהרגשת הגוף) — הרי זה נועד כדי ש\u0003לא\u0004 יבואו אנשים \u0003להקל על דברי תורה\u0004 (בדינה של נדה מדין תורה), \u0003אלא להחמיר על דברי תורה\u0004 באה גזירת חכמים זו. \u0003ו\u0004אולם טומאת \u0003כתמים עצמן\u0004 הריהי \u0003דרבנן\u0004 \u0005[מדברי חכמים],\u0006 ולכך מקלים בה, לתלות את הכתם בכל דבר, וכדרך שנהג ר' עקיבא.","עוד שנינו במשנתנו: \u0003עד\u0004 (מטלית בדיקה) \u0003שהוא נתון\u0004 תחת הכר, ובבוקר נמצא עליו כתם דם, שאמר ר' אליעזר בר' צדוק כי אם הכתם עגול — הריהי טהורה, ואם מוארך — הריהי טמאה. ובענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]:\u0006 \u0003מי פליגי רבנן עליה\u0004 \u0005[האם חלוקים חכמים עליו],\u0006 על \u0003ר' אליעזר בר' צדוק\u0004 בדין הזה, \u0003או לא?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה ששנינו בברייתא: \u0003כתם\u0004 שמראהו \u0003ארוך\u0004 — \u0003מצטרף\u0004 לכשיעור כגריס ועוד, והריהי טמאה. ואילו \u0003טפין טפין\u0004 — \u0003אין מצטרפין.\u0004 ויש לברר: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 ברייתא זו? \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' אליעזר בר' צדוק\u0004 — \u0003למה לי צירוף\u0004 לכגריס ועוד כדי לטמא בכתם הארוך, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 ר' אליעזר בר' צדוק כי כתם \u0003משוך כל שהוא\u0004 — הריהו \u0003טמא!\u0004","\u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הרי זו כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 ו\u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003פליגי\u0004 \u0005[חלוקים]\u0006 חכמים על ר' אליעזר בר' צדוק. ודוחים את הראיה: \u0003לא,\u0004 אין ללמוד כך, שכן יש מקום לומר כי \u0003לעולם\u0004 ברייתא זו הריהי כשיטת \u0003ר' אליעזר בר' צדוק, ו\u0004אשר לשאלה מדוע נצרכים אנו לענין הצירוף, שהרי ר' אליעזר בר' צדוק אמר שכתם המשוך כל שהוא הריהו טמא — \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר'\u0004 \u0003אליעזר בר' צדוק\u0004 את שיטתו זו, אין זה אלא דווקא \u0003ב\u0004כתם הנמצא על \u0003עד\u0004 בדיקה. \u0003אבל ב\u0004סתם \u0003כתם\u0004 — \u0003לא\u0004 אמר כן שיהא הכתם המשוך טמא, אלא באופן שהוא מצטרף לכגריס ויותר. ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ש\u0003אמר רב יהודה\u0004 \u0003אמר שמואל\u0004 כי \u0003הלכה\u0004 היא \u0003כר' אליעזר בר' צדוק.\u0004 ומתוך שאמר בלשונו ש\u0003הלכה\u0004 כמותו — \u0003מכלל\u0004 הדברים נלמד \u0003דפליגי\u0004 \u0005[שחלוקים]\u0006 עליו חכמים בדבר זה. ומסכמים: אכן \u0003שמע מינה\u0004","",""],["\u0003האשה שהיא עושה\u0004 את \u0003צרכיה\u0004 (בהטלת מי רגלים), \u0003וראתה\u0004 בתוך מי הרגלים \u0003דם,\u0004 ואין זה ברור אם בא הדם מן המקור והריהי טמאה בו, או מפצע המצוי בה באותו המקום, ואין היא נטמאת בו. מה דינה? \u0003ר' מאיר אומר:\u0004 תלוי הדבר באופן בו היא הטילה את מימיה, ש\u0003אם\u0004 הטילתם כשהיא \u0003עומדת\u0004 — הריהי \u0003טמאה,\u0004 שכן באופן זה יתכן שבא הדם מן המקור. \u0003ו\u0004אולם \u0003אם\u0004 הטילתם כשהיא \u0003יושבת\u0004 — הריהי \u0003טהורה,\u0004 שכן ברור לנו שלא בא הדם מן המקור, אלא מפצע שיש בה. \u0003ר' יוסי אומר: בין כך ובין כך,\u0004 בכל האופנים בהם הטילה את מימיה רגליה, ומצאה בהם דם — הריהי \u0003טהורה,\u0004 שאין דם זה בא מן המקור.","ועוד הלכה בדומה לכך: \u0003איש ואשה שעשו\u0004 שניהם את \u0003צרכיהן\u0004 (בהטלת מי רגלים) \u0003לתוך הספל, ונמצא דם על המים\u0004 שבספל זה. מה דינם? \u0003ר' יוסי מטהר\u0004 את האשה. שהרי כפי ששנינו מקודם סבור ר' יוסי שאף באשה העושה את צרכיה לבדה, ומצאה דם, שהריהי טהורה בכל דרך בה הטילה את מימיה. והגם שאין זה אלא ספק אחד: אם בא הדם מן המקור או מפצע. ומעתה, ודאי שכך הוא הדין כששניהם הטילו את מימיהם, שהרי זה ספק כפול: שמא בא הדם מן האיש או מן האשה. ואף אם נאמר שבא הדם מן האשה, ספק הוא אם בא הדם מן המקור או מפצע שבה. \u0003ו\u0004אילו \u0003ר' שמעון מטמא\u0004 את האשה. וטעמו: \u0003שאין דרך האיש להוציא דם, אלא שחזקת דמים\u0004 שהריהם באים \u0003מן האשה,\u0004 ואף כאן ודאי שבא הדם מן האשה. ומעתה, אין לפנינו אלא ספק אחד, אם בא הדם מן המקור או מפצע שבה. ובספק שכזה מטמא ר' שמעון (וכשיטת ר' מאיר הנזכרת למעלה).","שנינו במשנתנו כי ר' מאיר מבחין בדין האשה שמצאה דם במי רגליה בין כשעשתה האשה צרכיה בעמידה לבין כשעשתה צרכיה בישיבה. ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 נבדל\u0005]\u0006 הדין כשעשתה צרכיה כשהיא \u0003עומדת,\u0004 שהדם טמא — משום \u0003דאמרינן\u0004 \u0005[שאומרים אנו]\u0006 כי באופן שכזה, \u0003מי\u0004 ה\u0003רגלים הדור\u0004 \u0005[חזרו,\u0006 חדרו\u0005]\u0006 \u0003למקור,\u0004 ומשם הם שבו \u0003ואייתי\u0004 \u0005[והביאו]\u0006 אתם \u0003דם.\u0004 מעתה, אף כשעשתה צרכיה כשהיא \u0003יושבת נמי נימא\u0004 \u0005[גם כן נאמר]\u0006 כי \u0003מי רגלים הדור\u0004 \u0005[חזרו]\u0006 \u0003למקור ואייתי\u0004 \u0005[והביאו]\u0006 \u0003דם,\u0004 ותיטמא האשה גם באופן זה!","\u0003אמר שמואל\u0004 בהסבר הדברים: מדובר במשנתנו כשעושה צרכיה \u0003ב\u0004ישיבה, ואת מי רגליה הריהי \u0003מזנקת\u0004 (מזרימה בקילוח רצוף בלא לחץ), ובאופן שכזה אין אפשרות שיחזרו מי הרגלים אל המקור. ואולם העושה צרכיה בעמידה, אין היא מזנקת את מימי רגליה, אלא הריהם שותתים ממנה, תוך התאמצותה, ובאופן זה יש אפשרות שיחזרו מימי הרגלים אל המקור. ומקשים: ב\u0003מזנקת נמי\u0004 \u0005[גם כן]\u0006 מדוע מטהר אותה ר' מאיר כשעושה צרכיה בישיבה, והרי קיים החשש \u0003דלמא בתר\u0004 \u0005[שמא אחר]\u0006 ש\u0003תמו מיא אתא\u0004 \u0005[המים, בא]\u0006 \u0003דם\u0004 מהמקור מכח עצמו, ולא כנישא על מימי הרגלים, וזרם הדם אל תוך מי הרגלים, והרי זה דם טמא?","\u0003אמר ר'\u0004 \u0003אבא\u0004 בתשובה: אין מקום לחשש זה, שכן במשנתנו מדובר \u0003ב\u0004מקרה ש\u0003יושבת\u0004 האשה \u0003על שפת הספל, ומזנקת\u0004 (ומטילה מימיה בקילוח) הישר \u0003בתוך הספל, ונמצא דם בתוך הספל.\u0004 ש\u0003אם איתא דבתר\u0004 \u0005[יש\u0006 מקום לומר \u0005שלאחר]\u0006 ש\u0003תמו מיא אתא\u0004 \u0005[המים בא\u0006 הדם\u0005] —\u0006 \u0003על שפת הספל איבעי ליה לאשתכוחי\u0004 \u0005[צריך היה לו,\u0006 לדם \u0005להימצא].\u0006 ומאחר ונמצא הדם בתוך הספל, הרי זו ראיה שהגיע אל תוך הספל על ידי מימי הרגלים. ומאחר שהיו אלה מימי רגלים שבקילוח — לא מן המקור בא דם זה.","ובסיכום הדברים, \u0003אמר שמואל, ואמרי לה\u0004 \u0005[ויש האומרים אותה]\u0006 שנמסרה הלכה זו כך, \u0003אמר רב יהודה,\u0004 שכך אמר שמואל: הלכה כר' יוסי. \u0003וכן אורי ליה\u0004 \u0005[הורה לו]\u0006 \u0003ר' אבא ל\u0004חכם הנקרא \u0003קלא\u0004 שברר אצלו הכרעת הדין מהי, והשיבו כי \u0003הלכה כר' יוסי.\u0004","שנינו עוד במשנתנו כי בזמן ש\u0003איש ואשה\u0004 עשו שניהם את צרכיהם אל תוך הספל, ונמצא בו דם, לדעת ר' יוסי הריהי טהורה ולדעת ר' שמעון הריהי טמאה. ובענין זה \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 שאלה זו: \u0003איש ואשה\u0004 שעשו צרכיהם אל תוך ספל אחד כשהם \u0003עומדין,\u0004 ונמצא דם בתוך הספל, \u0003מה לי\u0004 ההלכה במקרה זה לפי השיטה ש\u0003אמר ר'\u0004 \u0003מאיר\u0004 בענין דומה במשנתנו?","וצדדי השאלה: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר'\u0004 \u0003מאיר\u0004 את דינו אמר זאת רק באשה העושה צרכיה בעמידה, שכן אין זה אלא \u0003בחד ספקא\u0004 \u0005[בספק אחד],\u0006 אם בא הדם מהמקור או מפצע שבה. שהרי ברור הוא הדבר שבא הדם ממנה. \u0003אבל ב\u0004מקרה שיש בו \u0003ספק ספקא\u0004 \u0005[ספק שבספק],\u0006 וכגון במקרה זה הנדון בשאלתם של חכמים, שהרי ספק הוא אם בא הדם מן האיש או מן האשה. ואף אם נאמר שבא הדם מן האשה, ספק נוסף הוא אם בא הדם מהמקור או מפצע. ובמקרה שכזה — \u0003לא מטמא\u0004 ר' מאיר. \u0003או דלמא לא שנא\u0004 \u0005[או שמא אין\u0006 זה \u0005שונה],\u0006 ואף במקרה זה מטמא ר' מאיר?","\u0003אמר ריש לקיש: היא\u0004 ההלכה שאמר ר' מאיר במקרה של ספק אחד, שהריהי טמאה, \u0003היא\u0004 ההלכה שאמר ר' מאיר אף במקרה של ספק ספיקא, שאף בזה הריהי טמאה. ומסביר ריש לקיש את דבריו: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 שכך הוא — \u0003מ\u0004זה \u0003דלא קתני\u0004 \u0005[ש\u0006התנא במשנתנו \u0005אין הוא שונה]\u0006 בסוף משנתנו, בדין האיש והאשה שעשו צרכיהם אל תוך הספל כי \u0003\"ר' מאיר ור' יוסי מטהרין\",\u0004 אלא \"ר' יוסי מטהר\", ומכאן שלדעת ר' מאיר גם באופן זה הריהי טמאה.","ומקשים על דעת ריש לקיש: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 הוא, שלשיטת ר' מאיר, הריהי טמאה אף במקרה שיש בו ספק ספיקא, \u0003השתא\u0004 \u0005[מעתה],\u0006 אם \u0003ר' מאיר\u0004 אף \u0003בספק ספקא מטמא,\u0004 \u0003בחד ספקא מיבעיא\u0004 \u0005[בספק אחד נצרך]\u0006 להשמיענו שהריהי טמאה? ומדוע שנה התנא במשנתנו את דינו של ר' מאיר שהריהי טמאה במקרה של ספק אחד? ומשיבים: השמיע כן התנא כדי \u0003להודיעך כחו\u0004 של \u0003ר' יוסי\u0004 החולק על ר' מאיר, ו\u0003אפילו בחד ספקא\u0004 \u0005[בספק אחד]\u0006 הריהו \u0003מטהר.\u0004","ומקשים על כך: \u0003ואדמיפלגי בחד ספק\u0004 \u0005[ועד\u0006 שהתנא במשנתנו שונה \u0005ש\u0006הם \u0005חולקים בספק אחד],\u0006 וכהסברך כדי \u0003להודיעך\u0004 את \u0003כחו\u0004 של \u0003ר' יוסי\u0004 המטהר אפילו בספק אחד, \u0003ליפלגו\u0004 \u0005[\u0006שישנה \u0005ש\u0006הם \u0005חולקים]\u0006 \u0003בספק ספקא,\u0004 וכדי \u0003להודיעך\u0004 את \u0003כחו\u0004 של \u0003ר' מאיר,\u0004 המטמא אפילו בספק ספיקא! ומשיבים: מעדיף התנא לשנות את מחלוקתם במקרה של ספק אחד, ולהשמיע את החידוש שבדעת ר' יוסי, שכן \u0003כח דהיתרא\u0004 \u0005[של היתר]\u0006 \u0003עדיף ליה\u0004 \u0005[לו].\u0006","\u0003ו\u0004אילו \u0003ר' יוחנן אמר: כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' מאיר\u0004 את דינו שהריהי טמאה — הרי זה רק \u0003ב\u0004מקרה של \u0003חד ספקא\u0004 \u0005[ספק אחד],\u0006 \u0003אבל ב\u0004מקרה של \u0003ספק ספקא\u0004 — \u0003לא אמר\u0004 ר' מאיר שהריהי טמאה. ומקשים: \u0003אם כן,\u0004 שאף ר' מאיר מטהר במקרה זה שבסוף המשנה, \u0003ליתני\u0004 \u0005[שישנה]\u0006 התנא \u0003\"ר' מאיר ור' יוסי מטהרין\",\u0004 ומדוע לא שנה אלא שר' יוסי מטהר? ומשיבים: \u0003אין הכי נמי\u0004 \u0005[אכן כך גם כן]\u0006 ראוי היה לשנות, \u0003ו\u0004אולם \u0003איידי דסליק\u0004 \u0005[מתוך שעלה,\u0006 שיצא התנא\u0005]\u0006 \u0003מ\u0004דברי \u0003ר' יוסי\u0004 בהלכה המובאת בתחילת המשנה, \u0003פתח\u0004 בסופה \u0003ב\u0004דברי ר' יוסי.","\u0003ו\u0004מקשים: מדוע יש צורך לשנות בסוף המשנה שלדעת \u0003ר' יוסי\u0004 הריהי טהורה במקרה זה שיש בו ספק ספיקא, והלא אפילו \u0003ב\u0004מקרה שאין בו אלא \u0003חד ספקא\u0004 \u0005[ספק אחד]\u0006 ר' יוסי \u0003מטהר,\u0004 ואם כן \u0003ב\u0004מקרה של \u0003ספק ספקא מיבעיא\u0004 \u0005[נצרך]\u0006 לומר שר' יוסי מטהר? ומשיבים: נצרך התנא לומר דין זה שבסוף משנתנו, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שר' יוסי מטהר, אינם אלא ב\u0003דיעבד,\u0004 כאשר כבר נגעה האשה (שהטילה מימיה עם איש לתוך ספל, ונמצא לאחר מכן דם בספל) בטהרות, שאין אנו מטמאים את הטהרות הללו. \u0003אבל לכתחלה לא\u0004 תגע האשה בטהרות. לכך \u0003קא משמע לן הוא,\u0004 התנא משמיע לנו] ממשנה יתירה, שלדעת ר' יוסי הריהי מותרת אף לכתחילה לגעת בטהרות.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן,\u0004 ושלא כשיטת ריש לקיש: \u0003איש ואשה שעשו צרכיהן לתוך הספל, ונמצא דם על המים\u0004 — \u0003ר' מאיר ור' יוסי מטהרין, ור' שמעון מטמא.\u0004 הרי איפוא ששיטת ר' מאיר היא שבאופן זה של ספק ספיקא הריהי טהורה.","שנינו במשנתנו כי כאשר עשו איש ואשה את צרכיהם לתוך ספל אחד ונמצא דם בתוכו, שר' שמעון מטמא את האשה. שכן אין זה דרכו של האיש להוציא דם, וחזקת דמים שהריהם באים מן האשה. ובבירור שיטתו של ר' שמעון \u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]:\u0006 במקרה שבו \u0003אשה\u0004 בלבד היא שעושה את צרכיה, כשהיא \u0003יושבת, מה לי\u0004 ההלכה במקרה זה לפי השיטה ש\u0003אמר ר'\u0004 \u0003שמעון\u0004 בענין דומה במשנתנו? וצדדי השאלה: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר'\u0004 \u0003שמעון\u0004 את דינו — הרי זה דווקא \u0003בעומדת,\u0004 ומשום \u0003דדחיק\u0004 \u0005[שדחוקה,\u0006 לחוצה\u0005]\u0006 \u0003לה עלמא\u0004 \u0005[בכלל]\u0006 האשה הנדרשת להטיל מימיה באופן זה. וכיון שהיא פועלת מתוך מצוקה, יש מקום להניח שבא הדם מהמקור (ואפילו הטיל יחד אתה איש את מימיו). \u0003אבל\u0004 כאשר היא מטילה את מימיה כשהיא \u0003יושבת,\u0004 וכדרכה, שלא טימא אותה ר' מאיר באופן זה — גם לשיטת ר' שמעון היא \u0003לא\u0004 טמאה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 לשיטת ר' שמעון \u0003לא שנא\u0004 \u0005[שונה]\u0006 דינה של היושבת מדינה של העומדת, ואף ביושבת מטמא ר' שמעון.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 מפורשת בדעתו של ר' שמעון: האשה שהטילה מימיה ומצאה בהם דם, אם הטילתם כשהיא \u0003יושבת\u0004 — הריהי \u0003תולה\u0004 את הדם בפצע שיש בה, והינה טהורה. ואם הטילתם כשהיא \u0003עומדת\u0004 — \u0003אינה תולה\u0004 את הדם בפצע, והינה טמאה. אלו \u0003דברי ר'\u0004 \u0003מאיר, ר'\u0004 \u0003יוסי אומר: בין כך\u0004 שהטילתם כשהיא יושבת, \u0003ובין כך\u0004 כשהטילתם כשהיא עומדת — הריהי \u0003תולה\u0004 את הדם בפצע שיש בה, והינה טהורה. ואילו \u0003ר' שמעון אומר: בין כך ובין כך\u0004 — היא \u0003אינה תולה,\u0004 ואף כשהטילתם כשהיא יושבת הריהי טמאה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם,\u0006 לחכמים\u0005]\u0006 עוד בבירור שיטתו של ר' שמעון: \u0003איש ואשה יושבין\u0004 ועושים צרכיהם לתוך ספל אחד, ונמצא בו דם, \u0003מה לי\u0004 ההלכה במקרה זה לפי השיטה ש\u0003אמר ר'\u0004 \u0003שמעון\u0004 במשנתנו? וצדדי השאלה: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר'\u0004 \u0003שמעון\u0004 את דינו, שהריהי טמאה — דווקא ב\u0003עומדת\u0004 — ומשום \u0003דדחיק\u0004 \u0005[שדחוקה,\u0006 לחוצה\u0005]\u0006 \u0003לה עלמא\u0004 \u0005[בכלל]\u0006 האשה הנדרשת להטיל מימיה באופן זה. ולכך אף שיש כאן ספק ספיקא (ספק בא הדם מן האישה, ספק בא מן האיש. ואף אם נאמר שבא הדם ממנה: ספק בא הדם מהמקור, ספק בא מפצע) — הריהי טמאה, שכן יש להניח שבאו מימי רגליה אל המקור, ומשם נישא אתם דם המקור. \u0003ו\u0004כן מטמא ר' שמעון אף ב\u0003יושבת\u0004 (כשהטילה רק האשה לבדה את מימיה לתוך הספל) — משום \u0003דחד ספק\u0004 \u0005[שספק אחד]\u0006 יש כאן (שהרי ברור שבא הדם ממנה, וכל הספק אם בא מהמקור או מפצע), \u0003אבל ב\u0004מקרה של איש ואשה שהטילו את מימיהם בישיבה לתוך ספל אחד, שהרי זה \u0003ספק ספקא\u0004 — \u0003לא אמר\u0004 ר' שמעון את דינו, והריהי טהורה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 לשיטת ר' שמעון \u0003לא שנא\u0004 \u0005[אין\u0006 זה \u0005שונה],\u0006 ואף באיש ואשה שהטילו מימיהם בישיבה מטמא ר' שמעון?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו ממה ששנינו: \u0003כיון\u0004 ש\u0003אמר ר'\u0004 \u0003שמעון\u0004 בטעם טומאתה של האשה שהוא משום ש\u0003חזקת דמים\u0004 שהם \u0003מן האשה\u0004 — \u0003לא שנא\u0004 \u0005[אין\u0006 זה \u0005משנה]\u0006 אם הטילו את מימיהם האיש והאשה כשהם \u0003עומדין ולא שנא\u0004 \u0005[ואין\u0006 זה \u0005משנה]\u0006 אם הטילו את מימיהם כשהם \u0003יושבין,\u0004 שבזה ובזה הריהי טמאה.","אשה ש\u0003השאילה\u0004 את \u0003חלוקה ל\u0004אשה \u0003נכרית או ל\u0004אשה ישראלית \u0003נדה,\u0004 ואחר כך לבשה האשה המשאילה את חלוקה ומצאה בו דם — \u0003הרי זו תולה\u0004 את כתם הדם \u0003בה,\u0004 בנכרית או באשה הנדה.","\u0003שלש נשים שלבשו\u0004 זו אחר זו \u0003חלוק אחד,\u0004 ולפני שלבשוהו שלושתן נבדק החלוק ונמצא שהוא נקי, ולאחר שלבשוהו נמצא עליו כתם דם, \u0003או שישבו\u0004 שלוש נשים בזו אחר זו \u0003על ספסל אחד, ו\u0004לאחר מכן \u0003נמצא עליו דם\u0004 — \u0003כולן טמאות.\u0004","\u0003ישבו על ספסל של אבן,\u0004 שאין הוא מקבל טומאה, \u0003או על האיצטבא של\u0004 בית ה\u0003מרחץ,\u0004 שאין זו מקבלת טומאה. ונמצא לאחר מכן דם על הספסל או על האיצטבא — \u0003ר' נחמיה מטהר\u0004 את שלושתן. \u0003ש\u0004כן \u0003היה ר'\u0004 \u0003נחמיה אומר: כל דבר שאינו מקבל טומאה\u0004 — \u0003אינו מקבל כתמים.\u0004 שלא גזרו חכמים את גזירת כתמים אלא בכתם הנמצא בדבר המקבל טומאה.","שנינו במשנתנו כי האשה שהשאילה את חלוקה לנכרית, ונמצא בו כתם לאחר מכן, הריהי תולה את הכתם בנכרית. ובענין זה \u0003אמר רב:\u0004 לא אמרה משנתנו את דינה זה אלא \u0003בנכרית\u0004"],["\u0003ה\u0004גדולה, שיודעים אנו בה שהיא כבר \u0003רואה\u0004 דם.","ומסבירים: \u0003ממאי\u0004 \u0005[ממה,\u0006 מנין לנו שהוא כן\u0005]?\u0006 — שהרי במשנתנו במקרה הנדון בה שנויה הנכרית \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003נדה,\u0004 שהושוו זו לזו: \u0003מה נדה\u0004 — מדובר במי \u0003דקחזיא\u0004 \u0005[שהיא\u0006 כבר רואה], שהרי אלמלא ראתה, לא היתה נטמאת בטומאת הנדה. \u0003אף נכרית\u0004 — מדובר במי \u0003דקא חזיא\u0004 \u0005[שהיא רואה,\u0006 בגדולה, הראויה לראות\u0005].\u0006","\u0003אמר רב ששת\u0004 בהתייחסו לדברים אלה של רב: \u0003כי ניים ושכיב\u0004 \u0005[כאשר נמנם ושכב]\u0006 \u0003רב\u0004 על מטתו \u0003אמרה להא שמעתא\u0004 \u0005[את זו ההלכה],\u0006 שאין היא הלכה שנאמרה ביישוב הדעת. \u0003דתניא\u0004 \u0005[שכן\u0006 \u0005שנויה\u0006 ברייתא\u0005]\u0006 באשה שהשאילה חלוקה ולאחר מכן מצאה בו כתם דם, שהריהי \u0003תולה\u0004 את הכתם \u0003בנכרית\u0004 לה השאילה את החלוק. ובכל נכרית הריהי תולה, אף זו שאינה גדולה, ושאינה רואה עדיין. ואילו \u0003ר' מאיר אומר\u0004 שאין היא תולה אלא \u0003בנכרית הראויה לראות.\u0004 \u0003ו\u0004אולם \u0003אפילו ר' מאיר\u0004 החולק על חכמים, \u0003לא קאמר\u0004 \u0005[אין הוא אומר]\u0006 \u0003אלא\u0004 שתולה \u0003ב\u0004נכרית ה\u0003רואה לראות, אבל\u0004 לומר שהריהי תולה רק בנכרית שכבר \u0003רואה\u0004 — \u0003לא איצטריך\u0004 \u0005[אין נצרך\u0006 לומר\u0005],\u0006 והרי זה שלא כרב האומר שאין תולים אלא בנכרית הרואה!","\u0003אמר רבא\u0004 בדחיית קושיית רב ששת: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 ש\u0003ר' מאיר לחומרא\u0004 אמר את דבריו. שלדעת חכמים תולים בכל נכרית (ואף זו שטרם ראויה לראות), ואילו לדעת ר' מאיר אין תולים אלא במי שראויה לראות? — אינו כן, אלא \u0003ר' מאיר\u0004 אמר את דבריו \u0003לקולא.\u0004 שלדעת חכמים (המחמירים) אין היא תולה אלא בנכרית גדולה שכבר ראתה, ואילו לדעת ר' מאיר (המקל) הריהי תולה אף בנכרית שראויה לראות. ונמצא שדעת רב הריהי כדעת חכמים.","ומביאים ראיה שר' מאיר מקל ביחס לדעתם של חכמים, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 אשה שהשאילה חלוקה לנכרית ונמצא בו דם, לדעת חכמים היא \u0003אינה תולה בנכרית,\u0004 ואילו \u0003ר' מאיר אומר\u0004 שהריהי \u0003תולה\u0004 בנכרית. ומעירים: \u0003ואלא קשיא הך\u0004 \u0005[קשה\u0006 ברייתא \u0005זו]\u0006 ששנינו בה שלדעת חכמים אין היא תולה בנכרית, בעוד שבברייתא הקודמת שנינו שלדעת חכמים הריהי תולה בנכרית — \u0003תריץ הכי\u0004 \u0005[תרץ כך]:\u0006 את השנוי בברייתא זו שלדעת חכמים הריהי תולה בנכרית, \u0003ו\u0004בלבד ש\u0003היא\u0004 הנכרית הריהי גדולה \u0003ש\u0004כבר \u0003רואה.\u0004 \u0003ר'\u0004 \u0003מאיר אומר\u0004 — הריהי תולה אף \u0003ב\u0004נכרית ש\u0003רואה לראות, ואף על פי ש\u0004עדיין \u0003אינה רואה.\u0004","ועוד בדינה של האשה המשאילה חלוקה לאשה טמאה, ולאחר שהוחזר החלוק נמצא בו כתם, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 השאילה אשה חלוקה לחברתה הטמאה בטומאת זבה קטנה (השומרת יום כנגד יום), ולאחר שלבשתו חברתה החזירתו לה ולאחר שלבשתו היא נמצא בו כתם דם, האשה המשאילה \u0003תולה\u0004 את הכתם \u0003ב\u0004אשה ה\u0003שומרת יום כנגד יום,\u0004 אם השאילה לה את החלוק \u0003ב\u0004יום ה\u0003שני\u0004 לזיבה \u0003שלה.\u0004 ואף שלא הוחזקה השואלת לראות ביום הזה, אלא שראתה אתמול — מאחר שמקורה פתוח (שכן ראתה דם אתמול), הריהי תולה בה את הכתם, הגם שבכך היא מקלקלת לה מעט, שהרי מעתה צריכה השואלת לשמור אף את יום המחרת, כיון שנטמאה עתה משעה שתלו בה את הכתם.","\u0003ו\u0004כן האשה המשאילה תולה את הכתם \u0003ב\u0004אשה ששאלה את החלוק בעודה \u0003סופרת שבעה\u0004 ימים של נקיות \u0003ש\u0004עדיין \u0003לא טבלה\u0004 ומעתה, שתולים בה את הכתם, הריהי צריכה לשוב ולמנות שבעה נקיים ולטבול אחריהם. \u0003לפיכך, היא\u0004 המשאילה — \u0003מתוקנת,\u0004 \u0003ו\u0004אילו \u0003חברתה\u0004 — \u0003מקולקלת,\u0004 אלה הם \u0003דברי רבן שמעון בן גמליאל.\u0004 \u0003רבי אומר:\u0004 האשה המשאילה \u0003אינה תולה\u0004 במקרים אלה באשה השואלת, שכן בכך היא מקלקלת לה (בדחיית זמן טבילתה), \u0003לפיכך שתיהן מקולקלות,\u0004 ששתיהן טמאות מפני הספק ממי בא כתם דם זה.","\u0003ו\u0004אולם \u0003שוין\u0004 (משתווים, מוסכם על שניהם), ואף רבי מודה בכך לרבן שמעון בן גמליאל, \u0003ש\u0004האשה המשאילה \u0003תולה ב\u0004שואלת ה\u0003שומרת יום כנגד יום\u0004 כשנמצא הכתם \u0003ב\u0004יום ה\u0003ראשון\u0004 לזיבה \u0003שלה,\u0004 שהרי אין בדבר זה כדי לקלקל לאשה השואלת, שכן אף בלא תלייה זו הריהי טמאה למחרת.","\u0003ו\u0004כן הריהי תולה \u0003ב\u0004אשה השואלת ה\u0003יושבת על דם טוהר\u0004 (שהם ארבעים ימים לאחר לידת זכר ושמונים ימים לאחר לידת נקבה). שכן בימים הללו אין האשה נטמאת בראיית דם, ולכך גם לא תיטמא אם נייחס את הכתם לה. \u0003ו\u0004כן הריהי תולה \u0003ב\u0004אשה השואלת שהינה \u0003בתולה\u0004 הנבעלת, \u0003ש\u0004כן \u0003דמיה\u0004 של זו \u0003טהורין,\u0004 כיון שמייחסים אנו את כתם הדם לדם הבתולים.","ושואלים: \u0003\"לפיכך\"\u0004 זה האמור בדברי \u0003רבן שמעון בן גמליאל למה לי,\u0004 מה בא ללמדנו, שהרי מובן הדבר שכך הוא לשיטת רבן שמעון בן גמליאל? ומשיבים: לא נאמר \"לפיכך\" בדברי רבן שמעון בן גמליאל אלא \u0003משום\u0004 שנאמר לאחר מכן \"לפיכך\" בדברי \u0003רבי.\u0004","ושואלים: אף \u0003\"לפיכך\"\u0004 האמור בדברי \u0003רבי למה לי,\u0004 שהרי גם זה מובן מאליו? ומשיבים: נצרך לומר כך, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 היה מקום לומר\u0005]\u0006 כי \u0003ההיא דאשתכח\u0004 \u0005[אותה שנמצא]\u0006 ה\u0003כתם גבה\u0004 \u0005[אצלה]\u0006 — היא אמנם \u0003תתקלקל\u0004 (תיטמא), ואולם \u0003אידך\u0004 \u0005[האחרת],\u0006 שלא נמצא הכתם אצלה — \u0003לא תתקלקל,\u0004 לכך \u0003קמשמע לן\u0004 \u0005[הוא משמיע לנו],\u0006 בשימוש הלשון \"לפיכך\" (המורה שהרי זו תוצאה המתבקשת) ששתיהן טמאות.","ועוד בענין מחלוקת רבן שמעון בן גמליאל ורבי מביאים מה ש\u0003אמר רב חסדא:\u0004 שני אנשים, שהיה אחד מהם \u0003טמא ו\u0004השני \u0003טהור שהלכו בשני שבילין\u0004 שונים, והיה \u0003אחד\u0004 מהשבילים \u0003טהור ואחד\u0004 מהשבילים \u0003טמא.\u0004 ואין אנו יודעים מי משני הנשים הללו הוא זה שהלך בשביל הטמא ונטמא בו, ומי מהם הלך בשביל הטהור — בהכרעת הדין במקרה זה \u0003באנו למחלוקת רבי ורבן שמעון בן גמליאל.\u0004 שכן לדעת רבן שמעון בן גמליאל התולה את הכתם הנמצא ואת טומאתו באשה שהיא כבר טמאה, אף במקרה זה תולים אנו שהאדם הטמא הוא זה שהלך בשביל הטמא, והאדם הטהור הוא זה שהלך בשביל הטהור. ואילו לדעת רבי שאין אנו תולים את הכתם הנמצא באשה הטמאה, אף במקרה זה אין תולים שהלך האדם הטמא בשביל הטמא, שכן אפשר הוא שהאדם הטהור הוא שהלך בשביל הטמא, ולפיכך שניהם טמאים.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על השוואה זו\u0005]\u0006 \u0003רב אדא: עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבי התם\u0004 \u0005[שם,\u0006 באשה המשאלת חלוק\u0005]\u0006 את דינו, שאין תולים את הכתם באשה הטמאה — \u0003אלא\u0004 משום \u0003דתרוייהו כי הדדי נינהו\u0004 \u0005[ששתיהן שוות הן],\u0006 ששתיהן היו בחזקת טהרה (שהרי אף השומרת יום כנגד יום, הריהי בכלל חזקת טהרה, שכן היא ראויה לטבול בכל שעה שתרצה. שכן היום היא לא ראתה אלא אתמול). ואולם \u0003הכא\u0004 \u0005[כאן,\u0006 בשני אנשים שהלכו בשני שבילים\u0005]\u0006 \u0003מאי נפקא לן מינה\u0004 \u0005[מה יוצא לנו ממנה,\u0006 מה זה משנה\u0005]\u0006 לאדם הטמא, אם נחליט שהוא זה שהלך בשביל הטמא, והרי אף בלא זה הינו טמא? ולכך, במקרה זה אף רבי מודה שתולים אנו שהאדם הטמא הוא זה שהלך בשביל הטמא, ואין האדם הטהור נטמא.","ומסבירים: \u0003ו\u0004אילו \u0003רב חסדא\u0004 האומר שאף במקרה זה של שני שבילים שיטת רבי שמטמאים את שני האנשים, מה טעמו? גם במקרה של האשה המשאלת חלוק, זו השומרת יום כנגד יום אינה בחזקת טהרה, שהרי \u0003סוף סוף\u0004 (אחרי הכל) \u0003איהי\u0004 \u0005[הריהי]\u0006 \u0003טבילה בעיא\u0004 \u0005[צריכה].\u0006 ובכל זאת טימא רבי את שתיהן, מעתה נאמר שגם במקרה זה של שני שבילים, לדעת רבי שני האנשים טמאים.","ומביאים: \u0003איתמר\u0004 \u0005[נאמר] ש\u0006\u0003אמר ר'\u0004 \u0003יוסי בר' חנינא: טמא וטהור, ו\u0004אין המדובר רק בשני אנשים שאחד מהם טהור ואחד מהם טמא אלא \u0003אפילו\u0004 שאחד מהם \u0003טהור ו\u0004אחד מהם \u0003תלוי\u0004 (ספק טמא), \u0003שהלכו בשני שבילין\u0004 שונים, שהיה \u0003אחד\u0004 מהם \u0003טמא ואחד\u0004 מהם \u0003טהור\u0004 — \u0003תולה\u0004 את האדם שהלך בשביל ה\u0003טמא ב\u0004אדם זה שהוא \u0003תלוי, ו\u0004את האדם שהלך בשביל ה\u0003טהור ב\u0004אדם זה שהוא \u0003טהור\u0004 — והלכה זו הריהי \u0003לדברי הכל,\u0004 שאף רבי סבור במקרה זה כרבן שמעון בן גמליאל. והרי זה איפוא כשיטת הסברו של רב אדא, ושלא כשיטת רב חסדא.","ועוד בענין מחלוקת זו של רבן שמעון בן גמליאל ורבי, \u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' יוחנן מר' יהודה בר ליואי: מהו\u0004 הדין לענין \u0003לתלות כתם\u0004 הנמצא בחלוק שהשאילה אשה לחברתה, \u0003בכתם\u0004 שהיתה זו השואלת טמאה משום שמצאה בחלוקה שלה כתם, ולאחר שהחזירה השואלת את החלוק, לבשתו המשאלת (בלא שבדקה אותו), ונמצא בו לאחר מכן כתם. והסביר ר' יוחנן את שאלתו: \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003רבי\u0004 המטמא את שתיהן בנמצא כתם בחלוק מושאל — \u0003לא תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, שהרי","\u0003השתא\u0004 \u0005[מעתה]\u0006 יש לומר בשיטת רבי: \u0003ומה התם\u0004 \u0005[שם,\u0006 במשאלת חלוקה לשומרת יום כנגד יום\u0005],\u0006 \u0003דקא חזיא\u0004 \u0005[שהיא רואה]\u0006 \u0003מגופה\u0004 — \u0003אמרת\u0004 שהאשה המשאלת \u0003אינה תולה\u0004 בה את הכתם, ושתיהן טמאות. \u0003הכא\u0004 \u0005[כאן,\u0006 במשאלת חלוק לבעלת כתם\u0005],\u0006 והרי בכתם שנטמאה בו השואלת יש מקום לומר \u0003דמעלמא קא אתי\u0004 \u0005[שמבחוץ הוא,\u0006 הכתם \u0005בא]\u0006 ולא ממנה — \u0003לא כל שכן\u0004 שאין המשאלת תולה את הכתם בבעלת כתם, ושתיהן טמאות.","ואולם \u0003כי תבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 שאלה זו, הרי זה \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003רבן שמעון בן גמליאל.\u0004 וצדדי השאלה: דווקא \u0003התם\u0004 \u0005[שם,\u0006 במשאלת חלוקה לשומרת יום כנגד יום\u0005],\u0006 \u0003הוא\u0004 שכיון \u0003דקא חזיא\u0004 \u0005[שהיא רואה]\u0006 \u0003מגופה\u0004 — לכך הריהי \u0003תליא\u0004 \u0005[תולה]\u0006 בה את הכתם. אבל \u0003הכא\u0004 \u0005[כאן,\u0006 במשאלת חלוק לבעלת הכתם\u0005],\u0006 שיש מקום לומר \u0003דמעלמא קאתי\u0004 \u0005[שמבחוץ הוא,\u0006 הכתם שטימא אותה, \u0005בא]\u0006 — היא \u0003לא תליא\u0004 \u0005[אינה תולה]\u0006 בה, ושתיהן טמאות. \u0003או דלמא, לא שנא\u0004 \u0005[או שמא, אין\u0006 זה \u0005משנה],\u0006 ואף במקרה זה לדעת רבן שמעון בן גמליאל האשה המשאלת את החלוק תולה את הכתם באשה השואלת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יהודה בר ליואי לר' יוחנן בתשובה: לדעת רבן שמעון בן גמליאל, במקרה זה \u0003אין תולין\u0004 את הכתם באשה השואלת. שאלו ר' יוחנן: ו\u0003מה טעם\u0004 אין תולים במקרה זה? השיבו ר' יהודה בר ליואי: \u0003לפי שאין\u0004 בעלת הכתם טמאה בודאי שבכגון זה אנו \u0003תולין\u0004 בה, שכן ייתכן שהכתם שטימא אותה בא מבחוץ.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' יוחנן על דברי ר' יהודה בר ליואי ממה ששנינו בברייתא: \u0003אין תולין\u0004 את ה\u0003כתם\u0004 הנמצא בחלוק שהושאל \u0003ב\u0004בעלת ה\u0003כתם.\u0004 ואם \u0003השאילה חלוקה ל\u0004אשה \u0003נכרית או ל\u0004ישראלית ה\u0003יושבת על הכתם\u0004 (הטמאה כבעלת כתם) — \u0003הרי זו תולה בה.\u0004","ובתחילה יש לברר את דברי הברייתא, שכן \u0003הא גופה קשיא\u0004 \u0005[זו\u0006 הברייתא \u0005עצמה קשה]\u0006 שהרי \u0003רישא\u0004 \u0005[בהתחלה]\u0006 \u0003אמרת\u0004 ש\u0003אין תולין\u0004 בבעלת הכתם, ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף]\u0006 \u0003אמרת\u0004 ש\u0003תולין!\u0004 אלא יש לתרץ כי \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 שכן \u0003הא\u0004 \u0005[זה,\u0006 תחילת דברי הברייתא\u0005]\u0006 — הריהם כשיטת \u0003רבי,\u0004 הסבור שאין תולים בבעלת הכתם. \u0003ו\u0004אילו \u0003הא\u0004 \u0005[זה,\u0006 סוף דברי הברייתא\u0005]\u0006 — הריהם כשיטת \u0003רבן שמעון בן גמליאל,\u0004 הסבור שתולים בבעלת הכתם.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ביישוב דברי הברייתא כי \u0003הא והא\u0004 \u0005[זה וזה,\u0006 תחילת וסוף דבריה\u0005]\u0006 הריהם כשיטת \u0003רבי,\u0004 ואין זו סתירה, שכן \u0003הא\u0004 \u0005[זה,\u0006 בסוף דברי הברייתא\u0005]\u0006 מדובר בכתם הנמצא בחלוק ששאלה \u0003ב\u0004יום ה\u0003ראשון שלה,\u0004 ביום בו נמצא הכתם בחלוק שלה שבשלו היא טמאה. והרי באותו יום הריהי טמאה כשלעצמה, ואף בלא שנתלה בה את הכתם בחלוק ששאלה. ולכך אין סיבה שלא נתלה בה את הכתם הזה, שהרי אין מקלקלים אותה יותר בכך. ואילו \u0003הא\u0004 \u0005[זה,\u0006 בתחילת דברי הברייתא\u0005] — מדובר בכתם הנמצא\u0006 \u0003ב\u0004יום ה\u0003שני שלה,\u0004 שראתה את הכתם אתמול, ואין היא צריכה אלא טבילה היום, וטהורה היא. ואם נייחס לה את הכתם הנמצא עתה, הרינו מקלקלים אותה, בכך שהריהי נטמאת יום נוסף.","\u0003רב אשי אמר\u0004 ביישוב דברי הברייתא: \u0003הא והא\u0004 \u0005[זה וזה,\u0006 תחילת וסוף דברי הברייתא\u0005]\u0006 הם כשיטת \u0003רבן שמעון בן גמליאל, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006"],["שכן \u0003כאן\u0004 (סוף דברי הברייתא), שתולים בבעלת הכתם — מדובר לענין \u0003למפרע,\u0004 לקביעת דין הטהרות שנגעה בהן בעלת הכתם לפני שנמצא הכתם בחלוק שהושאל לה. שהרי בכך שתולים אנו בה את הכתם הנמצא בחלוק, אין אנו מקלקלים אותה על יותר ממה שהיא כבר מקולקלת בו. שכן הטהרות שנגעה בהן למפרע הריהן טמאות בשל היותה בעלת כתם. ואילו \u0003כאן\u0004 (תחילת דברי הברייתא), שאין תולים בבעלת הכתם — מדובר לענין \u0003להבא,\u0004 בדין הטהרות שעתידה לגעת בהן. שלענין זה אין אנו מטמאים אותה עתה בשל ייחוס כתם זה שבחלוק כמי שבא ממנה.","ומסכמים את הקושיה על שיטת ר' יהודה בר ליואי: אכן הוצעו דרכי פירוש שונות ביישוב דברי הברייתא, ואולם \u0003מכל מקום\u0004 מוסכם על הכל כי לדעת רבן שמעון בן גמליאל תולים את הכתם בבעלת הכתם, והרי זו איפוא \u0003קשיא\u0004 \u0005[קשה]\u0006! \u0003אמר רבינא\u0004 ביישוב קושיית ר' יוחנן: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 שכן \u0003הכי קאמר\u0004 \u0005[כך היא\u0006 הברייתא \u0005אומרת],\u0006 בסופה, ובאופן זה שוב אין סתירה בין תחילת דבריה לסופם: אבל אם \u0003השאילה חלוקה לנכרית\u0004 הרואה דם — \u0003בעלת כתם\u0004 (כלומר, לענין הגדרת האשה כבעלת כתם זה) \u0003הרי זו תולה בה\u0004 בנכרית, ואין היא נחשבת כבעלת הכתם. ושוב לא נלמד מברייתא זו שדעת רבן שמעון בן גמליאל היא שתולים כתם בכתם.","ותוהים על הסבר זה: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"או ליושבת על הכתם\" קתני\u0004 \u0005[שונה הוא\u0006 התנא\u0005].\u0006 והרי שמדובר במי שהיא טמאה זה מכבר, ויושבת ומונה שבעת ימי נקיות, ולא בזו שעתה נמצא בה כתם! ומסביר רבינא, \u0003הכי קאמר\u0004 \u0005[כך הוא,\u0006 התנא \u0005אומר]:\u0006 השאילה חלוקה לנכרית, \u0003או ל\u0004ישראלית ה\u0003יושבת על דם טוהר\u0004 (בתוך ארבעים הימים ללידת הזכר או שמונים הימים ללידת נקבה, שטהורים הם דמיה) — \u0003בעלת כתם\u0004 (כלומר, לענין הגדרתה של האשה שהיא בעלת כתם זה), \u0003תולה בה.\u0004","שנינו במשנתנו: \u0003שלש\u0004 נשים \u0003שלבשו\u0004 בזו אחר זו חלוק אחד, שנבדק קודם שלבשוהו אלה, ולא היה בו כתם דם. ולאחר שלבשוהו שלוש הנשים נמצא בו כתם דם. לדעת חכמים שלוש הנשים טמאות, ואילו ר' נחמיה מטהר את שלושתן. \u0003ש\u0004כן \u0003היה ר'\u0004 \u0003נחמיה\u0004 אומר שלא גזרו חכמים טומאה אלא על כתם הנמצא בדבר המקבל טומאה. ובהסבר שיטתו זו של ר' נחמיה \u0003אמר רב מתנה: מאי טעמא\u0004 \u0005[מה הטעם,\u0006 המקור\u0005]\u0006 לשיטתו זו של ר' נחמיה? \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"ונקתה לארץ תשב\"\u0004 (ישעיה ג, כו) — \u0003כיון שישבה לארץ,\u0004 שהריהי דבר שאינו מקבל טומאה, \u0003נקתה\u0004 (נטהרה) בכך, שאם תראה כתם על הקרקע — אין היא נטמאת בו.","ועוד בהגדרת שיטתו של ר' נחמיה \u0003אמר רב הונא, אמר ר'\u0004 \u0003חנינא: מטהר היה ר'\u0004 \u0003נחמיה אפילו\u0004 אם נמצא כתם הדם \u0003באחורי\u0004 (גבו) של \u0003כלי חרס.\u0004 שכן כלי חרס מקבל טומאה רק מתוכו, ולא מגבו. והרי זה ככל כתם הנמצא במקום שאינו מקבל טומאה. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא שכך הוא הדין לשיטת ר' נחמיה, ואין צורך להשמיענו כן!","ומשיבים: נצרך ר' חנינא להשמיענו כך, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר,\u0006 היה מקום לומר\u0005]:\u0006 \u0003ליגזור\u0004 \u0005[שנגזור]\u0006 טומאה על כתם הנמצא ב\u0003גבו\u0004 של כלי חרס \u0003אטו\u0004 \u0005[משום]\u0006 זה הנמצא ב\u0003תוכו\u0004 (המקבל טומאה). לכך \u0003קא משמע לן\u0004 \u0005[הוא,\u0006 ר' חנינא, \u0005משמיע לנו]\u0006 שאין גוזרים גזירה שכזו, ולכן כתם הנמצא על גבו של כלי חרס אינו מטמא.","ועוד בהגדרת שיטתו של ר' נחמיה \u0003אמר אביי: מטהר היה ר'\u0004 \u0003נחמיה במטלניות\u0004 (מטליות של בד) \u0003שאין בהן\u0004 שיעור \u0003שלש\u0004 אצבעות \u0003על שלש\u0004 אצבעות, \u0003דלא חזיין\u0004 \u0005[שאין\u0006 הן \u0005ראויות]\u0006 \u0003לא ל\u0004שימושם של \u0003עניים ולא ל\u0004שימושם של \u0003עשירים.\u0004","ולענין קביעת הלכה במחלוקת חכמים ור' נחמיה, \u0003דרש רב חייא בר רב מתנה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: הלכה כרבי נחמיה.\u0004 \u0003אמר ליה\u0004 \u0005[לו,\u0006 לרב חייא בר רב מתנה\u0005]\u0006 \u0003רב נחמן: אבא תני\u0004 \u0005[שנה]\u0006 ברייתא האומרת כי \u0003מעשה\u0004 בכתם שנמצא בדבר שאינו מקבל טומאה \u0003בא לפני חכמים\u0004 שיורו בו את דינו, \u0003וטמאום\u0004 חכמים, וכשיטת חכמים במשנתנו החולקים על ר' נחמיה, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 ש\u0003הלכה כר' נחמיה?\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותו מעשה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שתי נשים שהיו טוחנות ברחיים של יד\u0004 כשהן עומדות זו אחר זו, \u0003ונמצא דם תחת הפנימית\u0004 (הקרובה יותר) לריחיים — \u0003שתיהן טמאות.\u0004 שכן דרך הטוחנות בריחיים, שיש והמרוחקת יותר דוחפת את עצמה להתקרב אל הריחיים, ובתוך כך הריהי חודרת למקומה של הסמוכה יותר לריחיים. ויש אפשרות שדם זה בא מכל אחת משתיהן, ולכך שתיהן טמאות. ואולם אם נמצא הדם \u0003תחת החיצונה\u0004 (המרוחקת יותר מן הריחיים) — \u0003החיצונה טמאה, ו\u0004אילו \u0003הפנימית טהורה.\u0004 ואם נמצא הדם \u0003בינתים\u0004 (ביניהן) — \u0003שתיהן טמאות.\u0004","\u0003היה מעשה ונמצא דם על שפתה של אמבטי\u0004 שבו רוחצות נשים, \u0003ו\u0004כן נמצא דם \u0003על עלה של זית בשעה ש\u0004הנשים \u0003מסיקות את התנור, ובא מעשה לפני חכמים\u0004 — \u0003וטמאום.\u0004 והרי עלה של זית הריהו דבר שאינו מקבל טומאה, ובכל זאת שונים אנו כי הורו חכמים שכתם הדם הנמצא בו מטמא, ושלא כשיטת ר' נחמיה!","ומשיבים: אין זו קושיה, שכן \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בהכרעת הדין הלכה למעשה במחלוקת חכמים ור' נחמיה. והתנא של ברייתא זו סבור שהוכרעה הלכה כחכמים, ואולם יש תנא אחר הסבור שהוכרעה הלכה כר' נחמיה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יעקב מטמא\u0004 כתם הנמצא במקום שאינו מקבל טומאה, \u0003ו\u0004אילו \u0003ר' נחמיה מטהר\u0004 כתם זה. \u0003והורו חכמים כר' נחמיה.\u0004","\u0003שלש נשים שהיו ישנות\u0004 יחד \u0003במטה אחת, ונמצא דם תחת אחת מהן\u0004 — \u0003כולן טמאות.\u0004 ואם כשנמצא דם זה עמדה ו\u0003בדקה אחת מהן\u0004 את עצמה \u0003ונמצאת\u0004 שהיא \u0003טמאה\u0004 בטומאת הנדה — \u0003היא טמאה, ושתיהן,\u0004 האחרות, \u0003טהורות.\u0004 \u0003ו\u0004אם לא בדקה אחת מהן את עצמה ונמצאה טמאה, או ששלושתן בדקו את עצמן ונמצאו טהורות — הריהן \u0003תולות זו בזו,\u0004 שזו שאינה ראויה לראות דם (כגון שהיא מעוברת) תולה בחברתה הראויה לראות דם (שאין היא מעוברת), שמחברתה בא הדם, והריהי טהורה. \u0003ואם\u0004 כל שלוש הנשים הללו \u0003לא היו ראוין לראות\u0004 — \u0003רואין אותן כאילו הן ראויות\u0004 לראות דם, ושלושתן טמאות, שהרי יצא דם זה מביניהן.","שנינו במשנתנו דינן של שלוש נשים שהיו ישנות במיטה אחת, ונמצא דם תחת אחת מהן. \u0003אמר רב יהודה,\u0004 \u0003אמר רב: ו\u0004דין זה \u0003הוא\u0004 אמור רק כ\u0003שבדקה\u0004 את \u0003עצמה\u0004 לאחר מציאת הדם במיטה \u0003ב\u0004תוך פרק זמן קצר המוגדר כ\u0003\"שיעור וסת\".\u0004 ואולם אם בדקה את עצמה לאחר זמן זה, אף שנמצא שהיא טמאה — אין אנו מייחסים את הדם דווקא לה, ואין שתי הנשים האחרות טהורות.","ומסבירים את שיטת רב: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעתו של \u0003בר פדא.\u0004 שכן \u0003אמר\u0004 בר פדא ששלושה פרקי זמן הם לענין הגדרת הזמן בו נטמאת האשה שמצאה דם לאחר תשמיש: שיעור הזמן הקצר ביותר — כשיעור וסת; אחריו כמשך הזמן הנדרש כדי שתרד האישה מהמיטה (לאחר תשמיש) ותדיח את פניה (שלמטה, כלומר בית הערוה); שיעור הזמן הארוך ביותר — משך זמן יותר מכדי ירידתה מן המיטה והדחת פניה: \u0003כל\u0004 שעבר פרק זמן של \"כשיעור וסת\" בין התשמיש למציאת הדם, \u0003ש\u0004מניחים שהיתה טמאה בוודאי בזמן התשמיש, ו\u0003בעלה\u0004 חייב \u0003בחטאת\u0004 ודאי על תשמיש זה, וכן \u0003טהרותיה\u0004 שהתעסקה בהן בתוך שיעור זמן כזה לפני שנמצא הדם, הריהן \u0003טמאות\u0004 ודאי, ויוצאות לשריפה.","וכל שעבר פרק זמן של \"כדי שתרד מן המיטה ותדיח פניה\", שהריהי נחשבת כטמאה מן הספק (שספק הוא אם היה הדם בשעת התשמיש) ולכך \u0003בעלה\u0004 חייב על התשמיש \u0003ב\u0004קרבן \u0003אשם תלוי,\u0004 הבא על הספק — ו\u0003טהרותיה\u0004 שהתעסקה בהן בתוך שיעור זמן זה, \u0003תלויות\u0004 (מסופקות) בטומאה ואינן יוצאות לשריפה אף שאינן נאכלות. וכל שעבר פרק זמן ארוך יותר מן הקודם, הריהי נחשבת כמי שהיתה טהורה בזמן התשמיש, ולכך \u0003בעלה פטור\u0004 מן הקרבן — ו\u0003טהרותיה\u0004 שהתעסקה בהן בשיעור זמן כזה \u0003טהורות.\u0004","\u0003ו\u0004אילו \u0003ר' אושעיא אימר\u0004 שאין אנו משווים חיוב קרבן לבעלה לדין טומאת הטהרות שהתעסקה בהן. ולכך \u0003אפילו\u0004 כשעבר פרק זמן קצר והיא נחשבת כטמאה ודאית ו\u0003בעלה\u0004 חייב \u0003ב\u0004קרבן \u0003חטאת\u0004 הבא על הודאי — \u0003טהרותיה\u0004 שהתעסקה בהן בתוך שיעור זמן קצר כזה אינן טמאות ודאי, אלא \u0003תלויות.\u0004","וטעם ההבדל: \u0003בשלמא התם\u0004 \u0005[זה נוח,\u0006 מובן, \u0005שם],\u0006 שנחשבת כטמאה ודאית בזמן התשמיש, אף שראתה את הדם רק לאחר התשמיש — שכן \u0003אימר\u0004 \u0005[אמור,\u0006 יש מקום לומר\u0005]\u0006 שאכן ראתה דם בשעת התשמיש, ואולם ה\u0003שמש\u0004 (כינוי בלשון נקיה לאיבר התשמיש של בעלה) \u0003עכביה\u0004 \u0005[עיכבו]\u0006 \u0003לדם\u0004 מלצאת בשעת התשמיש, ולא יצא אלא לאחר מכן. \u0003[אבל] הכא\u0004 \u0005[כאן,\u0006 במתעסקת בטהרות\u0005] —\u0006 \u0003אם איתא דהוי\u0004 \u0005[אם יש\u0006 מקום לומר \u0005שהיה]\u0006 \u0003דם\u0004 בשעה שהתעסקה בטהרות, \u0003מאן עכביה\u0004 \u0005[מי עכב אותו]\u0006 מלצאת עד עכשיו?","ובהסבר דעתו של ר' אושעיא \u0003אמר ר'\u0004 \u0003ירמיה: משל\u0004 לדעתו זו של \u0003ר' אושעיא למה הדבר דומה?\u0004 — \u0003לילד וזקן\u0004 (צעיר ומבוגר) \u0003שהיו מהלכין\u0004 יחד \u0003בדרך, כל זמן שהיו\u0004 שניהם יחד \u0003בדרך\u0004 — ה\u0003ילד שוהא לבא.\u0004 שאינו ממהר בדרכו, משום שהוא קשור למבוגר הנמצא אתו. ואולם משעה ש\u0003נכנסו\u0004 השניים \u0003לעיר,\u0004 ונפרדו זה מזה — הילד ממהר לבא, וכיוצא בזה יש הבדל בין דרכו של הדם בשעה שאיבר התשמיש נמצא אתו בבית הערוה, ובין בשעה שנפרד מאיבר התשמיש. \u0003ו\u0004כן \u0003אמר אביי משל\u0004 לדעתו של \u0003ר' אושעיא: למה הדבר דומה?\u0004 — \u0003לאדם שנותן אצבע ב\u0004תוך ה\u0003עין, כל זמן ש\u0004ה\u0003אצבע\u0004 נתונה \u0003ב\u0004תוך ה\u0003עין\u0004 — ה\u0003דמעה שוהא לבא\u0004 (לצאת, שהרי נחסמת היא על ידי האצבע), ואולם משעה ש\u0003נטל האצבע\u0004 מן העין — ה\u0003דמעה ממהרת לבא.\u0004","\u0003ו\u0004עוד שנינו במשנתנו בדין שלוש הנשים שישנו במיטה אחת, ונמצא דם לאחר מכן תחת אחת מהן, ובין הנשים הללו יש מי שדרכה לראות ויש מי שאין דרכה לראות — הריהן \u0003תולות\u0004 (מייחסות את הדם הנמצא) \u0003זו\u0004 שאין דרכה לראות \u0003בזו\u0004 שדרכה לראות, ונטמאת רק זו שדרכה לראות. ומביאים עוד בענין זה, ממה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003כיצד\u0004 (באיזה אופן) הריהן \u0003תולות זו בזו?\u0004 שתי נשים שישנו במיטה אחת, ונמצא דם לאחר מכן תחת אחת מהן, והיתה אחת מהן \u0003עוברה\u0004 (מעוברת, שחזקתה שהיא מסולקת דמים), \u0003ו\u0004האחרת \u0003שאינה עוברה,\u0004 ודרכה לראות — \u0003תולה\u0004 ה\u0003עוברה\u0004 את הדם \u0003ב\u0004זו \u0003שאינה עוברה.\u0004","וכן כשהיתה אחת מהן \u0003מניקה\u0004 (שחזקתה שאין היא רואה דמים), \u0003ו\u0004האחרת \u0003שאינה מניקה,\u0004 ודרכה לראות — \u0003תולה\u0004 ה\u0003מניקה\u0004 את הדם הנמצא \u0003ב\u0004זו \u0003שאינה מניקה.\u0004 וכן כשהיתה אחת מהן \u0003זקנה\u0004 (שאין דרכה לראות דם), \u0003ו\u0004האחרת היתה מי \u0003שאינה זקנה,\u0004 ודרכה לראות — \u0003תולה\u0004 ה\u0003זקנה\u0004 את הדם שנמצא \u0003ב\u0004זו \u0003שאינה זקנה.\u0004 וכיוצא בזה, אם היתה אחת מהן \u0003בתולה\u0004 (\"בתולת דמים\", שמימיה עדיין לא ראתה דם), \u0003ו\u0004האחרת \u0003שאינה בתולה,\u0004 ודרכה לראות — \u0003תולה\u0004 ה\u0003בתולה\u0004 את הדם הנמצא \u0003ב\u0004זו \u0003שאינה בתולה.\u0004 שכן ארבע נשים אלה (מעוברת, מניקה, זקנה ובתולת דמים) הריהן בחזקת שאינן רואות דם.","אכן אם \u0003היו\u0004 הנשים הללו שישנו במיטה אחת, \u0003שתיהן עוברות,\u0004 או שהיו \u0003שתיהן מניקות,\u0004 או \u0003שתיהן זקנות,\u0004 או \u0003שתיהן בתולות,\u0004 ונמצא דם תחת אחת מהן — \u0003זו היא ששנינו:\u0004 אם \u0003לא היו\u0004 הנשים הללו שישנו במיטה אחת \u0003ראויות לראות,\u0004 ונמצא דם במיטה — \u0003רואין\u0004"],["\u0003כאילו\u0004 שלושתן \u0003הן ראויות\u0004 לראות, וכולן טמאות.","\u0003שלש נשים שהיו ישנות\u0004 יחד \u0003במטה אחת,\u0004 והרי המיטה נתונה בסמוך לקיר. \u0003ונמצא דם\u0004 תחת אחת מהן, שאם הדם נמצא \u0003תחת האמצעית\u0004 שבין שלושתן — \u0003כולן טמאות,\u0004 שכן ספק הוא אם בא הדם מן האמצעית או מאחת מחברותיה ששכבו לצידה. ואם נמצא הדם \u0003תחת הפנימית\u0004 שבכולן, זו השוכבת על המיטה בסמוך לקיר — \u0003שתים הפנימיות\u0004 (כלומר, זו השוכבת בסמוך לקיר, והשוכבת באמצע שהן פנימיות ביחס לשוכבת החיצונה), הריהן טמאות, שאפשר שבא הדם מזו ששכבה לצידה, \u0003ו\u0004אולם \u0003החיצונה\u0004 (השוכבת בסמוך לפנים החדר) \u0003טהורה,\u0004 שכן היא מרוחקת מזו שנמצא הדם תחתיה, ומפרידה ביניהן אשה אחרת. נמצא הדם \u0003תחת החיצונה\u0004 שבכולן — ה\u0003שתים החיצונות\u0004 (החיצונית מכולן, והאמצעית) \u0005טמאות,\u0006 שיתכן שבא הדם מזו ששכבה באמצע, \u0003ו\u0004אולם \u0003הפנימית טהורה,\u0004 שכן הריהי רחוקה ביותר מזו שנמצא הדם תחתיה. ומסייגים: \u0003אימתי\u0004 נאמר דין זה —","\u0003בזמן שעברו\u0004 שלוש הנשים הללו כשנכנסו למיטה \u0005דרך מרגלות המטה\u0006 (צד הרוחב התחתון של המיטה), שבדרך זו אין האחת עוברת על פני חברתה בדרכה לשכב במיטה. \u0003אבל אם עברו\u0004 (נכנסו למיטה) שלוש הנשים הללו \u0003דרך עליה,\u0004 הפנימית עברה מעל המקום בו נמצא הדם — \u0003כולן\u0004 ואף הפנימית טמאות, שיש לחשוש גם שממנה בא דם זה. ואם מיד לאחר שנמצא הדם, עמדה ו\u0003בדקה אחת מהן\u0004 את עצמה, \u0003ונמצאת טהורה\u0004 — \u0003היא טהורה,\u0004 שאין לייחס לה את הדם, \u0003ו\u0004ה\u0003שתים\u0004 האחרות \u0003טמאות,\u0004 שהרי בא הדם מאחת מהן. ואם מיד לאחר שנמצא הדם עמדו ו\u0003בדקו\u0004 את עצמן \u0003שתים\u0004 מהן, \u0003ומצאו\u0004 שהן \u0003טהורות\u0004 — \u0003הן טהורות,\u0004 \u0003ו\u0004אילו ה\u0003שלישית טמאה.\u0004 ואם לאחר שנמצא הדם, עמדו \u0003שלשתן\u0004 ובדקו את עצמן, \u0003ומצאו\u0004 שהן \u0003טהורות\u0004 — \u0003כולן טמאות,\u0004 שהרי ברור הדבר שבא הדם מאחת מהן.","משל \u0003למה הדבר דומה?\u0004 — \u0003לגל\u0004 (ערימת אבנים) ה\u0003טמא\u0004 (שידוע שיש תחתיו כזית מן המת) \u0003שנתערב בין שני גלים טהורים,\u0004 ואין יודעים איזהו הטמא. ועמדו \u0003ובדקו אחת מהן\u0004 (מהגלים הללו) \u0003ומצאו\u0004 שהוא \u0003טהור\u0004 — \u0003הוא טהור, ו\u0004ה\u0003שנים\u0004 האחרים \u0003טמאים\u0004 מספק. ואם בדקו \u0003שנים\u0004 משלושת הגלים הללו, \u0003ומצאו\u0004 שהם \u0003טהורין\u0004 — \u0003הם טהורין ו\u0004ה\u0003שלישי טמא.\u0004","ואם עמדו ובדקו את \u0003שלשתן, ומצאו\u0004 ששלושתם \u0003טהורין\u0004 — \u0003כולן טמאים\u0004 מספק, שהרי ברור שאחד מהם טמא, אף שאין אנו יודעים איזהו. אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004 \u0003ש\u0004היה \u0003ר' מאיר אומר: כל דבר שהוא בחזקת טומאה\u0004 (כגון אחד מגלי האבנים הללו) — \u0003לעולם הוא\u0004 עומד \u0003בטומאתו\u0004 זו, \u0003עד שיודע לך טומאה היכן היא.\u0004 וכיון שלא נמצאה הטומאה כולם טמאים. ובדומה לזה בענייננו, כיון שאחת הנשים הללו טמאה בוודאי, ואין אנו יודעים מי היא זו, לכך שלושתן טמאות.","\u0003ו\u0004אילו \u0003חכמים אומרים\u0004 בדינם של הגלים הללו, שהריהו חופר ו\u0003בודק\u0004 תחת כל אחד מהגלים הללו, \u0003עד שמגיע ל\u0004שכבת ה\u0003סלע\u0004 בתחתיתו של גל זה, שברור הוא שאין נמצא דבר תחת הסלע, \u0003או\u0004 עד שמגיע \u0003ל\u0004קרקע \u0003בתולה\u0004 (אדמה שלא נעבדה מעולם), וברור לו שאין המת נמצא תחת גל זה. וכך הריהו בודק את כל שלושת הגלים, ואם נמצאו טהורים — טהורים הם, ומניחים אנו כי בשר המת נגרר משם.","שנינו במשנה הקודמת את דינן של שלוש נשים שישנו במיטה אחת, ונמצא דם תחת אחת מהן, שכולן טמאות. ואף במשנתנו שנינו דינן של שלוש נשים שישנו במיטה אחת, ונמצא דם תחת אחת מהן, ואולם במשנתנו מבחינים במצבים השונים, היכן נמצא הדם, ושלפעמים השוכבת הפנימית או החיצונית טהורה. ושואלים: \u0003מאי שנא רישא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מיוחדת, \u0005תחילת\u0006 המשנה, כלומר, המשנה הקודמת\u0005]\u0006 — \u0003דלא מפליג\u0004 \u0005[שאין\u0006 התנא \u0005מחלק]\u0006 בין מקרים שונים, שתמיד שלושתן טמאות, \u0003ומאי שנא\u0004 \u0005[ו\u0006ב\u0005מה שונה,\u0006 מיוחדת, \u0005סוף\u0006 המשנה, כלומר, משנתנו זו\u0005]\u0006 — \u0003דקמפליג\u0004 \u0005[ש\u0006התנא \u0005מחלק\u0006 בין המצבים השונים\u0005],\u0006 שלפעמים אחת מהן טהורה? \u0003אמר ר'\u0004 \u0003אמי: ב\u0004משנה הקודמת מדובר כששלוש הנשים הללו שוכבות כשהן \u0003משולבות\u0004 (דבוקות זו בתוך זו), שאין כאן אחת המוגדרת כ\"פנימית\" או \"אמצעית\" ו\"חיצונית\", שכן כל אחת מהן חלק מגופה נמצא במקום אחר במיטה. ואילו במשנתנו מדובר כשכל אחת מהן שוכבת במקום לעצמה במיטה, ולכך יש מקום להגדירן כ\"פנימית\", \"אמצעית\" ו\"חיצונית\".","שנינו במשנתנו בשלוש נשים אלה שישנו במיטה אחת ונמצא דם תחת אחת מהן, שאם מייד לאחר מציאת הדם עמדה ו\u0003בדקה אחת\u0004 מהן את עצמה ונמצאה טהורה — היא טהורה, וחברותיה טמאות. ואם בדקו שתים ונמצאו טהורות — השלישית טמאה. ואולם אם בדקו שלושתן את עצמן, ונמצאו טהורות — שלושתן טמאות. ועל הלכה זו הביאו משל מגלי אבנים. ותוהים: \u0003למה ליה למתני\u0004 \u0005[לו,\u0006 לתנא, \u0005לשנות]\u0006 \u0003\"למה זה דומה\",\u0004 הרי הלכה זו מובנת כשלעצמה, אף בלא משל?","ומשיבים: \u0003הכי קאמר להו\u0004 \u0005[כך הוא אומר להם]\u0006 \u0003ר' מאיר לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003ב\u0004מקרה של \u0003דם\u0004 הנמצא במיטה שישנו בה שלוש נשים, \u0003דלא פליגיתו\u0004 \u0005[שאין אתם חולקים]\u0006 עלי, ואף לדעתכם שלושתן טמאות. \u0003ומאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003ב\u0004מקרה של \u0003גל דפליגיתו\u0004 \u0005[שחולקים אתם],\u0006 ולדעתכם אם נבדקו כל שלושת הגלים ונמצאו טהורים — שלושתם טהורים?","\u0003ו\u0004אילו לדעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 אין להשוות בין דין גלי אבנים לדין הנשים. שכן \u0003בשלמא התם\u0004 \u0005[זה נוח שם,\u0006 בגלי אבנים, שפסקו ששלושתם טהורים\u0005]\u0006 — \u0003אימא\u0004 \u0005[אמור,\u0006 יש מקום לומר\u0005]\u0006 כי אמנם בתחילה היה כזית מן המת מונח תחת אחד הגלים, ואולם לאחר מכן \u0003עורב נטלה\u0004 משם, ולכך כולם טהורים. \u0003אלא הכא\u0004 \u0005[כאן,\u0006 בשלוש נשים שבדקו עצמן ונמצאו טהורות\u0005]\u0006 — ברור הוא ש\u0003האי\u0004 \u0005[זה]\u0006 ה\u0003דם\u0004 בא מאחת מהן. שאם לא כן, \u0003מהיכא אתא\u0004 \u0005[מהיכן בא]\u0006 הדם? אלא בהכרח יש לומר שאחת מהן טעתה בבדיקתה, והריהי טמאה. וכיון שאין אנו יודעים מי היא, יש לטמא את שלושתן מן הספק.","ומביאים עוד מדברי חכמים בטעות אפשרית בבדיקה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003מאיר: מעשה\u0004 היה \u0003ב\u0004עץ \u0003שקמה של\u0004 הישוב \u0003כפר סבא, שהיו\u0004 בני המקום \u0003מחזיקין בה\u0004 שיש תחתיה \u0003טומאה.\u0004 \u0003ובדקו\u0004 באותו מקום, \u0003ולא מצאו\u0004 כל טומאה. \u0003לימים נשבה בו הרוח, ועקרתו\u0004 לעץ זה ממקומו, \u0003ונמצא גולגולת של מת תחובה לו בעיקרו\u0004 (בשורשו). והרי זו ראיה, שיש וטועים בבדיקה. \u0003אמרו לו: משם\u0004 מביא אתה \u0003ראיה\u0004 שאין לסמוך על הבדיקה? \u0003אימר\u0004 \u0005[אמור,\u0006 יש לומר\u0005]\u0006 כי כשבדקו \u0003לא בדקו כל צרכו.\u0004","ועוד \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003יוסי: מעשה במערה של\u0004 היישוב \u0003שיחין, שהיו מחזיקין בה טומאה.\u0004 \u0003ובדקו, עד שהגיעו לקרקע שהיתה חלקה כצפורן, ולא מצאו\u0004 כל טומאה. ואולם \u0003לימים נכנסו בה פועלים\u0004 כדי למצוא בה מחסה \u0003מפני הגשמים.\u0004 \u0003ונתזו\u0004 (הכו, לשם שעשוע) \u0003בקרדומותיהן, ומצאו\u0004 בה \u0003מכתשת מלאה עצמות.\u0004 \u0003אמרו לו: משם ראיה? אימר\u0004 \u0005[אמור]\u0006 כי כשבדקו \u0003לא בדקו כל צרכו.\u0004","\u0003ועוד\u0004 \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אבא שאול אומר: מעשה בסלע\u0004 ביישוב \u0003בית חורון, שהיו מחזיקין בה טומאה.\u0004 \u0003ולא יכלו חכמים לבדוק\u0004 את הדבר, \u0003מפני שהיתה\u0004 הסלע \u0003מרובה\u0004 (גדול ביותר). \u0003והיה שם זקן אחד, ור' יהושע בן חנניא שמו, אמר להן: הביאו לי סדינים! הביאו לו סדינים, ושראן במים, ופרסן עליהם\u0004 (מעל המקום שהיה חשד שיש תחתיו כזית מן המת). ונמצא כי \u0003מקום\u0004 ה\u0003טהרה\u0004 שבסלע — נותר \u0003יבש,\u0004 ואילו ה\u0003מקום\u0004 בסלע שהיתה בו \u0003טומאה\u0004 — נהיה \u0003לח\u0004 מאותו סדין רטוב. הבינו שאין זה סלע מוצק אלא אדמה תחוחה ועמדו \u0003ובדקו\u0004 אותו מקום, \u0003ו\u0004אכן \u0003מצאו\u0004 שם \u0003בור גדול מלא עצמות.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]\u0006 בעניינו של אותו בור: \u0003הוא הבור ש\u0004אותו \u0003מילא ישמעאל בן נתניה חללים, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"והבור אשר השליך שם ישמעאל את כל פגרי\u0004 ה\u0003אנשים אשר הכה ביד גדליה\u0004 הוא אשר עשה המלך אסא מפני בעשא מלך ישראל אותו מלא ישמעאל בן נתניהו חללים\" (ירמיה מא, ט).","ודנים בפירוש הפסוק: \u0003וכי גדליה\u0004 בן אחיקם הוא זה ש\u0003הרגן? והלא ישמעאל\u0004 בן נתניה הוא זה ש\u0003הרגן,\u0004 וכמסופר בספר ירמיה שם! \u0003אלא מתוך שהיה לו\u0004 לגדליה בן אחיקם \u0003לחוש לעצת יוחנן בן קרח\u0004 שגילה לו כי ישמעאל זומם להורגו, \u0003ולא חש\u0004 גדליה לדבר זה, ולא שמע לו מפני איסור שמיעת לשון הרע — \u0003מעלה עליו הכתוב כאילו\u0004 גדליה בן אחיקם הוא ש\u0003הרגן.\u0004","ומתוך שהוזכר לשון הרע (שראוי היה לשומע להיזהר), מביאים עוד בענין זה. \u0003אמר רבא: האי לישנא בישא\u0004 \u0005[לשון הרע הזה],\u0006 \u0003אף על פי דלקבולי לא מבעי\u0004 \u0005[שלקבלו,\u0006 להאמין למסופר, \u0005לא צריך]\u0006 — מכל מקום \u0003מיחש ליה מבעי\u0004 \u0005[לחשוש לו צריך].\u0006","ומסופר: \u0003הנהו בני גלילא, דנפק עלייהו קלא דקטול נפשא\u0004 \u0005[אותם בני גליל, שיצא עליהם קול שהרגו נפש].\u0006 \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003ר' טרפון, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003לטמרינן מר\u0004 \u0005[יחביא אותנו אדוננו]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003היכי נעביד\u0004 \u0005[איך נעשה]\u0006 לכם? שהרי \u0003אי לא אטמרינכו\u0004 \u0005[אם לא אחביא אתכם]\u0006 — \u0003חזו יתייכו\u0004 \u0005[יראו אתכם]\u0006 הרודפים אתכם, ויהרגוכם. ואם \u0003אטמרינכו\u0004 \u0005[אחביא אתכם]\u0006 — \u0003הא אמור רבנן\u0004 \u0005[הרי אמרו חכמים]\u0006 כי \u0003האי לישנא בישא, אף על גב דלקבולי לא מבעי\u0004 \u0005[לשון הרע הזה, אף על פי שלקבלו אין צריך],\u0006 מכל מקום \u0003מיחש ליה מבעי\u0004 \u0005[לחשוש לו צריך],\u0006 ועליכם נאמר לשון הרע שהרגתם נפש. לכך \u0003זילו אתון, טמרו נפשייכו\u0004 \u0005[לכו אתם, החביאו עצמכם].\u0006","ומביאים עוד בענין זה של שמיעת דברים שיש לחוש להם. שכן נאמר קודם למלחמה עם עוג מלך הבשן \u0003\"ויאמר ה'\u0004 \u0003אל משה אל תירא\u0004 אותו כי בידך נתתי אותו ואת כל עמו ואת ארצו ועשית לו כאשר עשית לסיחון מלך האמורי אשר יושב בחשבון\" (במדבר כא, לד). ויש לברר: \u0003מכדי\u0004 \u0005[מאחר]\u0006 ו\u0003סיחון ועוג אחי הוו\u0004 \u0005[אחים היו],\u0006 שכן \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003סיחון ועוג בני אחיה בר שמחזאי הוו\u0004 \u0005[היו],\u0006 \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מיוחד\u0005]\u0006 ש\u0003מעוג דקמסתפי\u0004 \u0005[שהוא,\u0006 משה רבינו, \u0005פחד]\u0006 ממנו, \u0003ומאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה],\u0006 \u0003מסיחון דלא קמסתפי\u0004 \u0005[שהוא,\u0006 משה רבינו, \u0005לא פחד]\u0006 ממנו?","\u0003אמר ר'\u0004 \u0003יוחנן, אמר ר'\u0004 \u0003שמעון בן יוחי: מ\u0004תוך \u0003תשובתו\u0004 (המענה) \u0003של\u0004 הקדוש ברוך הוא ל\u0003אותו צדיק\u0004 (משה רבינו), \u0003אתה יודע מה היה בלבו\u0004 וממה חשש. שכך \u0003אמר\u0004 משה רבינו בלבו: \u0003שמא תעמוד לו\u0004 לעוג \u0003זכות של אברהם אבינו,\u0004 ששמע לדבריו של עוג כי לוט בן אחי אברהם נשבה במלחמת ארבעת המלכים את החמישה, וחשש להם.","\u0003ש\u0004כן \u0003נאמר \"ויבא הפליט ויגד לאברם העברי...\u0004 וישמע אברם כי נשבה אחיו\" (בראשית יד, יג—יד), \u0003ואמר ר'\u0004 \u0003יוחנן: זה\u0004 המכונה בכתוב \"הפליט\" הינו \u0003עוג,\u0004 הריהו מכונה כך משום \u0003שפלט\u0004 (ששרד) \u0003מדור המבול.\u0004","ומתוך שהוזכר ענין גלי אבנים שאבדה בהם טומאה, מביאים עוד בכיוצא בזה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בגד ש\u0004היה בו כתם דם של נדה (המטמא במגע), ונפל הבגד לתוך מים או שנכנס בו מדם הבהמה, וכתוצאה מכך, \u0003אבד בו הכתם,\u0004 ואין אנו יודעים היכן הוא מקומו. מה עושים? — \u0003מעביר עליו שבעה סממנין, ו\u0004בכך הריהו \u0003מבטלו\u0004 לדם זה. ושוב אינו מטמא (והבגד עצמו נטהר בטבילה). \u0003ר' שמעון בן אלעזר אומר:\u0004"],["\u0003בודקו\u0004 לבגד זה \u0003שכונות שכונות\u0004 (קטעים קטעים), שבודק בנפרד קטע אחר קטע בבגד זה. ואם לאחר בדיקה זו לא נמצא הכתם — שוב אין הבגד חוזר ומטמא במגעו.","בגד ש\u0003אבדה בו שכבת זרע,\u0004 שאין אנו יודעים היכן היא בבגד. מה עושים? אם היה זה בגד \u0003חדש\u0004 — \u0003בודקו ב\u0004נעיצת \u0003מחט\u0004 על פני הבגד. שכן שכבת הזרע מתקשה, ועל ידי המחט יחוש בה. ואם היה זה בגד \u0003שחוק\u0004 (משומש ומהוה) — הריהו \u0003בודקו ב\u0004העמדתו נגד ה\u0003חמה,\u0004 שבמקום בו נמצאת שכבת הזרע אין קרני השמש עוברות. ובדיקה זו אינה נוהגת בבגד חדש, שכן האריג שבו עדיין קשיח, ואין קרני השמש עוברות יפה דרכו. ובהסבר דברי ר' שמעון בן אלעזר מביאים מה ש\u0003תנא\u0004 \u0005[שנה\u0006 החכם בברייתא\u0005]:\u0006 \u0003אין \"שכונה\"\u0004 שבבגד ה\u0003פחותה מ\u0004שטח שיש בו שיעור \u0003שלש אצבעות\u0004 על שלוש אצבעות.","ומתוך שדנו בבגד שאבד בו כתם דם לענין טומאה וטהרה, מביאים עוד בדינו של בגד שאבד בו איסור. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בגד שאבד בו כלאים\u0004 (\"כלאי בגדים\") שחלק ממנו עשוי מתערובת צמר ופשתים, ואין יודעים היכן הוא בבגד. כיון שמעתה אסור הבגד בלבישה — \u0003הרי זה לא ימכרנו לגוי,\u0004 שמא ימכרנו הגוי לישראלי, ויכשל הלה באיסור לבישת כלאיים. \u0003ו\u0004כן \u0003לא יעשנו מרדעת לחמור,\u0004 שמא יבוא להשתמש בבגד זה כטלאי על בגדו. \u0003אבל עושה ממנו תכריכין למת,\u0004 שכן ברור הוא שלא יבוא הישראלי להשתמש בבגד זה לצרכיו, שהרי אסורה ההנאה מתכריכיו של המת. \u0003אמר רב יוסף: זאת אומרת\u0004 — \u0003מצו‍ת בטלות לעתיד לבא.\u0004 שהרי מת זה שנקבר בתכריכים שיש בהם איסור כלאיים, עתיד לעמוד בתחיית המתים, ויימצא עומד כשהוא לבוש בבגד שיש בו כלאיים. ומתוך שלא חששו לכך, נלמד כי לעתיד לבוא תתבטלה המצוות.","\u0003אמר ליה\u0004 \u0005[לו,\u0006 לרב יוסף\u0005]\u0006 \u0003אביי ואי תימא\u0004 \u0005[ויש שאומר]\u0006 כי \u0003רב דימי\u0004 הוא שאמר כן לרב יוסף: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר'\u0004 \u0003מני, אמר ר'\u0004 \u0003ינאי, לא שנו\u0004 היתר זה של תכריכים למת שיש בהם איסור כלאיים — \u0003אלא לספדו\u0004 כשהוא לבוש בתכריכים כאלה, \u0003אבל לקוברו\u0004 בהם — \u0003אסור.\u0004 ואם כן, אין מכאן ראיה לענין מצוות לעתיד לבוא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף בתשובה: \u0003לאו איתמר עלה\u0004 \u0005[האם לא נאמר עליה,\u0006 על הלכה זו של תכריכים שיש בהם כלאי בגדים\u0005],\u0006 ש\u0003אמר ר'\u0004 \u0003יוחנן\u0004 שמותר \u0003אפילו לקוברו\u0004 עמם. ומכאן ראיה לענין מצוות לעתיד לבוא.","\u0003ו\u0004מסבירים כי \u0003ר' יוחנן\u0004 שאמר את דבריו אלה, הרי זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003אמר ר'\u0004 \u0003יוחנן: מאי דכתיב\u0004 \u0005[מהו שכתוב]\u0006 \u0003\"במתים חפשי\u0004 כמו חללים שוכבי קבר אשר לא זכרתם עוד והמה מידך נגזרו\" (תהלים פח, ו) — \u0003כיון שמת אדם\u0004 — הריהו \u0003נעשה חפשי מן המצו‍ת.\u0004","ועוד בדינו של בגד שאבדו בו כלאיים, \u0003אמר רפרם בר פפא,\u0004 \u0003אמר רב חסדא: בגד שאבד בו כלאים\u0004 — \u0003צובעו, ומותר.\u0004 שכן על ידי הצביעה יכול להתברר שאין איסור כלאיים בבגד. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרפרם בר פפא: מנא ליה לסבא הא\u0004 \u0005[מנין לו לזקן,\u0006 כינויו של רב חסדא, הלכה \u0005זו]\u0006 שניתן לסמוך על כך?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא\u0004 זו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו]\u0006 בה בדינו של גל אבנים שידוע היה בו שהוא טמא, ונתערב בגלי אבנים אחרים, ש\u0003בודק עד שמגיע לסלע, ואי ליכא\u0004 \u0005[ואם אין,\u0006 לא נמצא\u0005]\u0006 באותו מקום כזית מן המת — \u0003אימר\u0004 \u0005[אמור]\u0006 שאמנם בתחילה היה כזית מן המת באותו המקום, ואולם לאחר מכן בא \u0003עורב\u0004 ו\u0003נטלה.\u0004 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 בענייננו יש לומר כי \u0003עמרא וכיתנא\u0004 \u0005[צמר וכותנה,\u0006 פשתים\u0005]\u0006 — \u0003בהדדי, לא סליק להו צבעא\u0004 \u0005[בשווה, אין עולה,\u0006 נקלט \u0005בהם צבע],\u0006 שהפשתן קולט צבע בקושי רב יותר מזה שקולט הצמר. וניתן איפוא באמצעות צביעת הבגד לזהות את הצמר והפשתים שבו. \u0003ו\u0004אם נעשתה בדיקה שכזו ולא נמצא שיש בבגד צמר ופשתים, לכך \u0003כיון דלא ידיע\u0004 \u0005[שאין ידוע]\u0006 לנו שעדיין יש איסור כלאיים בבגד — \u0003אימר מנתר נתר\u0004 \u0005[אמור ניתר,\u0006 ניתק\u0005]\u0006 הכלאיים מן הבגד, ומותר הבגד בלבישה.","ועוד בדינו של בגד שהיה בו איסור כלאיים. \u0003אמר רב אחא בריה\u0004 \u0005[בנו של]\u0006 \u0003רב ייבא משמיה\u0004 \u0005[משמו של]\u0006 \u0003מר זוטרא: האי מאן דרמי חוטא דכיתנא בגלימיה דעמרא ונתקיה\u0004 \u0005[מי שהטיל חוט של פשתן בגלימה של צמר,\u0006 והרי הבגד אסור משום כלאי בגדים\u0005,\u0006 ולאחר מכן עמד \u0003ונתקיה\u0004 \u0005[וניתקו],\u0006 \u0003ו\u0004אולם הוא \u0003לא ידע אי נתיק אי לא נתיק\u0004 \u0005[אינו יודע אם\u0006 אמנם \u0005ניתק\u0006 חוט הפשתן, \u0005אם לא ניתק]\u0006 — \u0003שפיר דמי\u0004 \u0005[דומה,\u0006 נראה \u0005יפה,\u0006 בסדר\u0005],\u0006 ומותר הבגד בלבישה.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? שכן \u0003מדאורייתא\u0004 \u0005[מדין תורה]\u0006 \"לא תלבש \u0003שעטנז\u0004 צמר ופשתים יחדיו\" (דברים כב, יא) \u0003כתיב\u0004 \u0005[נאמר]\u0006 באיסור כלאי בגדים. ומן המלה \"שעטנז\" אנו למדים: שאין הבגד בכלל איסור כלאי בגדים \u0003עד שיהיה\u0004 נעשה מחוט צמר וחוט פשתים \u0003שוע\u0004 (שהוחלקו יחד הצמר והפשתים במסרקות, לפני שנטוו). וכן \u0003טווי\u0004 (שנטוו) יחד, \u0003ו\u0004כן \u0003נוז\u0004 (שנארגו אל תוך הבגד). שרק באופנים אלה הרי זה איסור כלאי בגדים מן התורה. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003הוא\u0004 ש\u0003גזרו ביה\u0004 \u0005[בו]\u0006 בחוט של פשתן שנארג בגלימה של צמר, שאף זה בכלל איסור כלאיים, הגם שאין כאן אלא אריגה יחד בלבד. \u0003ו\u0004במקרה זה שלפנינו, \u0003כיון דלא ידע אי נתקיה\u0004 \u0005[שאינו יודע אם ניתקו\u0006 אם לא ניתקו\u0005]\u0006 — \u0003שרי\u0004 \u0005[מותר]\u0006 הבגד בלבישה, מן הספק.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב אשי\u0004 על הלכה זו של מר זוטרא: מנין לנו שפירוש \"שעטנז\" האמור בתורה הוא שיהא הבגד האסור בכלאי הכרם זה שהתקיימו בו שלושת אלה, שוע טווי ונוז? ושמא \u0003אימר\u0004 \u0005[אמור]\u0006 שהכוונה היא לאחד משלושת אלה, והריהו אסור מן התורה באיסור כלאיים \u0003או שוע או טווי או נוז! ו\u0004מסכמים: \u0003הלכתא\u0004 \u0005[הלכה]\u0006 היא \u0003כמר זוטרא, מדאפקינהו רחמנא בחדא לישנא\u0004 \u0005[מתוך שהוציא אותן הכתוב בלשון,\u0006 במלה \u0005אחת].\u0006","ועוד בדין כתם הנמצא בבגד, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 כתם דם הנמצא ב\u0003בגד צבוע\u0004 — \u0003מטמא משום כתם.\u0004 \u0003ר'\u0004 \u0003נתן בר יוסף אומר: אינו מטמא משום כתם, ש\u0004הרי \u0003לא תקנו\u0004 חכמים לבישת \u0003בגדי צבעונין לאשה, אלא\u0004 משום שיש בכך כדי \u0003להקל על כתמיהן.\u0004 שכן אין הכתם ניכר בבגד צבעוני.","ותוהים על דבריו ש\u0003תקנו\u0004 חכמים לבישת בגדי צבעונים לנשים, \u0003מאי תקנינהו\u0004 \u0005[מה\u0006 היא ש\u0005תיקנו להן\u0006 כן\u0005]?\u0006 ומשיבים: \u0003אלא\u0004 כוונת דבריו, \u0003שלא הותרו בגדי צבעונין לאשה אלא\u0004 על מנת \u0003להקל\u0004 בכך \u0003על כתמיהן.\u0004 ושואלים: מן הלשון \u0003\"הותרו\"\u0004 יש לדייק, \u0003מכלל\u0004 הדברים נלמד \u0003דאסירי\u0004 \u0005[שאסורים\u0006 בגדים צבעוניים\u0005]\u0006 מעיקר הדין!","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 אמנם אסורים בגדים צבעוניים בלבישה. \u0003דתנן\u0004 \u0005[ש\u0006כך \u0005שנינו]\u0006 \u0003בפולמוס של אספסינוס גזרו\u0004 חכמים \u0003על עטרות חתנים ועל האירוס\u0004 (כלי זמר), משום צער החורבן. ו\u0003בקשו\u0004 חכמים \u0003לגזור\u0004 אף \u0003על בגדי צבעונין\u0004 שלא ללובשם, ואולם \u0003אמרי\u0004 \u0005[אמרו]:\u0006 \u0003הא עדיפא\u0004 \u0005[זה עדיף],\u0006 שתלבשנה הנשים בגדים צבעוניים — \u0003כדי להקל\u0004 בכך \u0003על כתמיהן.\u0004","\u0003שבעה סמנין\u0004 (חומרים) \u0003מעבירין\u0004 אותם \u0003על הכתם\u0004 הנמצא בבגד, כדי לבדוק אם דם הוא או צבע. שכן שבעה סממנים אלה מסלקים את הדם. ואלה הם: \u0003רוק תפל, ומי גריסין, ומי רגלים,\u0004 \u0003ונתר, ובורית,\u0004"]]};
